def get_pptx_slide_image_count__eb53145b(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Get the number of slides and images per slide in a PowerPoint file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key for VM file path

    Returns:
        Dict with 'slide_count' and 'images_per_slide' (list of image counts)
    """
    vm_path = config.get('path', '/home/user/Desktop/4.3-Template_4.29.2016.pptx')
    file_bytes = env.controller.get_file(vm_path)
    if not file_bytes:
        return {'slide_count': 0, 'images_per_slide': []}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide_count = len(prs.slides)
        images_per_slide = []
        for slide in prs.slides:
            image_count = 0
            for shape in slide.shapes:
                if shape.shape_type == 13:
                    image_count += 1
            images_per_slide.append(image_count)
        return {'slide_count': slide_count, 'images_per_slide': images_per_slide}
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

def get_slide_content_from_docx__8890dcab6eb014437adbb9b7df1c7374(env, config: Dict):
    """Extract all text content from a Word document (expected to contain slide content).

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the docx file on VM

    Returns:
        str: All text content from the document concatenated
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return ''
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        all_text = []
        for para in doc.paragraphs:
            text = para.text.strip()
            if text:
                all_text.append(text)
        return '\n'.join(all_text)
    finally:
        os.unlink(tmp_path)

def get_ppt_slide_count_footer__166960ad(env, config: dict):
    """Extract slide count and footer text from all slides.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with ppt_file_path

    Returns:
        dict: {
            'slide_count': int,
            'footer_texts': list of footer text from each slide
        }
    """
    ppt_file_path = config['ppt_file_path']
    ppt_localhost_path = get_vm_file(env, {'path': ppt_file_path, 'dest': os.path.basename(ppt_file_path)})
    prs = Presentation(ppt_localhost_path)
    slide_count = len(prs.slides)
    footer_texts = []
    for slide in prs.slides:
        slide_footer = ''
        for shape in slide.shapes:
            if hasattr(shape, 'text') and hasattr(shape, 'top') and hasattr(shape, 'height'):
                slide_height = prs.slide_height
                shape_bottom = shape.top + shape.height
                if shape_bottom > slide_height * 0.8:
                    if shape.text.strip():
                        slide_footer = shape.text.strip()
                        break
        footer_texts.append(slide_footer)
    return {'slide_count': slide_count, 'footer_texts': footer_texts}

def get_pptx_specific_para_text__b690c1ab(env, config: Dict):
    """
    Get text from a specific paragraph in a specific shape on a specific slide.

    Args:
        env: Environment object
        config: Dict with 'path', 'dest', 'slide_idx', 'shape_idx', 'para_idx'

    Returns:
        str: The text content of the specified paragraph
    """
    ppt_path = config.get('path')
    dest = config.get('dest')
    slide_idx = config.get('slide_idx', 0)
    shape_idx = config.get('shape_idx', 0)
    para_idx = config.get('para_idx', 0)
    ppt_localhost = get_vm_file(env, {'path': ppt_path, 'dest': dest})
    prs = Presentation(ppt_localhost)
    if slide_idx >= len(prs.slides):
        return None
    slide = prs.slides[slide_idx]
    if shape_idx >= len(slide.shapes):
        return None
    shape = slide.shapes[shape_idx]
    if not hasattr(shape, 'text_frame'):
        return None
    if para_idx >= len(shape.text_frame.paragraphs):
        return None
    paragraph = shape.text_frame.paragraphs[para_idx]
    return paragraph.text.strip()

def get_pptx_textbox_fonts__f5216e3a(env, config):
    """Extract font sizes from two specific textboxes in a PowerPoint slide.
    
    Args:
        env: DesktopEnv instance
        config: Configuration dict with parameters:
            - ppt_file_path: Path to PPTX file on VM
            - slide_index: Slide index (0-based)
            - textbox1_shape_idx: First textbox shape index
            - textbox2_shape_idx: Second textbox shape index
            
    Returns:
        dict: {"textbox1_font_size": float, "textbox2_font_size": float}
    """
    ppt_file_path = config['ppt_file_path']
    slide_index = int(config['slide_index'])
    textbox1_idx = int(config['textbox1_shape_idx'])
    textbox2_idx = int(config['textbox2_shape_idx'])
    ppt_file_localhost = get_vm_file(env, {'path': ppt_file_path, 'dest': os.path.basename(ppt_file_path)})
    prs = Presentation(ppt_file_localhost)
    if slide_index >= len(prs.slides):
        return {'error': f'Slide index {slide_index} out of range'}
    slide = prs.slides[slide_index]
    result = {'textbox1_font_size': None, 'textbox2_font_size': None}
    if textbox1_idx < len(slide.shapes):
        shape1 = slide.shapes[textbox1_idx]
        if hasattr(shape1, 'text_frame') and shape1.has_text_frame:
            for para in shape1.text_frame.paragraphs:
                for run in para.runs:
                    if run.font.size:
                        result['textbox1_font_size'] = run.font.size.pt
                        break
                if result['textbox1_font_size'] is not None:
                    break
    if textbox2_idx < len(slide.shapes):
        shape2 = slide.shapes[textbox2_idx]
        if hasattr(shape2, 'text_frame') and shape2.has_text_frame:
            for para in shape2.text_frame.paragraphs:
                for run in para.runs:
                    if run.font.size:
                        result['textbox2_font_size'] = run.font.size.pt
                        break
                if result['textbox2_font_size'] is not None:
                    break
    return result

def get_slide_notes__1eb34c5c26f1351b91b989c3517fde01(env, config):
    """Get the notes text from a specific slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and optional 'slide_idx' keys

    Returns:
        str: Notes text from the slide, or empty string if no notes
    """
    import tempfile
    import os
    from pptx import Presentation
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return ''
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide_idx = config.get('slide_idx', 0)
        if slide_idx >= len(prs.slides):
            return ''
        slide = prs.slides[slide_idx]
        notes_slide = slide.notes_slide
        if notes_slide and notes_slide.notes_text_frame:
            return notes_slide.notes_text_frame.text.strip()
        return ''
    finally:
        os.unlink(tmp_path)

def get_pptx_table_left_align__735a2413a6d3476870d41134ce6212ec(env, config: Dict):
    """
    Extract table position to check left alignment.

    Args:
        env: DesktopEnv instance
        config: Dict with 'path' (VM file path) and 'slide_index' (0-based)

    Returns:
        Dict with table position info: {'left': int, 'top': int, 'width': int, 'height': int}
        or None if no table found
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return None
    slide_index = config.get('slide_index', 0)
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        if slide_index >= len(prs.slides):
            return None
        slide = prs.slides[slide_index]
        for shape in slide.shapes:
            if hasattr(shape, 'has_table') and shape.has_table:
                return {'left': shape.left, 'top': shape.top, 'width': shape.width, 'height': shape.height}
        return None
    finally:
        import os
        os.unlink(tmp_path)

def get_pptx_file__11b877a27a380575d5bab482e21af6e1(env, config: dict):
    """
    Get PPTX file from VM and return the file path.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM path) and 'dest' (cache filename)

    Returns:
        str: Path to cached file or None if failed
    """
    vm_path = config['path']
    dest_name = config['dest']
    file_bytes = env.controller.get_file(vm_path)
    if not file_bytes:
        logger.error(f'Failed to get file from VM: {vm_path}')
        return None
    cache_path = os.path.join(env.cache_dir, dest_name)
    try:
        os.makedirs(env.cache_dir, exist_ok=True)
        with open(cache_path, 'wb') as f:
            f.write(file_bytes)
        logger.info(f'Successfully saved PPTX file: {cache_path} ({len(file_bytes)} bytes)')
        return cache_path
    except Exception as e:
        logger.error(f'Error saving file: {e}')
        return None

def get_pptx_notes_content__01305e03(env, config: dict):
    """Extract speaker notes from specific slides.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'slide_indices' (list of slide indices)

    Returns:
        dict: Map of slide_index to notes text
    """
    ppt_path = config.get('path')
    slide_indices = config.get('slide_indices', [])
    ppt_file_localhost = get_vm_file(env, {'path': ppt_path, 'dest': os.path.split(ppt_path)[-1]})
    prs = Presentation(ppt_file_localhost)
    notes_map = {}
    for idx in slide_indices:
        idx_int = int(idx)
        if idx_int < len(prs.slides):
            slide = prs.slides[idx_int]
            if slide.has_notes_slide:
                notes_text = slide.notes_slide.notes_text_frame.text.strip()
                notes_map[str(idx_int)] = notes_text
            else:
                notes_map[str(idx_int)] = ''
        else:
            notes_map[str(idx_int)] = ''
    return notes_map

def get_pptx_font_size__6b2f48045a7b219cd21244d53ea51f11(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Extract slide properties including title font size and notes.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'slide_index' (0-based)

    Returns:
        Dict with slide properties: title_text, title_font_size_pt, notes_text
    """
    file_path = config['path']
    slide_index = config.get('slide_index', 0)
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        if slide_index >= len(prs.slides):
            return {}
        slide = prs.slides[slide_index]
        result = {'title_text': '', 'title_font_size_pt': None, 'notes_text': ''}
        if slide.shapes.title and slide.shapes.title.text_frame.paragraphs:
            result['title_text'] = slide.shapes.title.text
            for para in slide.shapes.title.text_frame.paragraphs:
                for run in para.runs:
                    if run.font.size:
                        result['title_font_size_pt'] = run.font.size.pt
                    break
                break
        notes_slide = slide.notes_slide
        if notes_slide and notes_slide.notes_text_frame:
            result['notes_text'] = notes_slide.notes_text_frame.text.strip()
        return result
    finally:
        os.unlink(tmp_path)

def get_pptx_image_info__aff85b93(env, config):
    """
    Extract image information from a specific slide.

    Args:
        env: DesktopEnv instance
        config: Dict with 'ppt_path', 'slide_idx' (0-indexed)

    Returns:
        List of dicts with image information (width, height, left, top in EMUs)
    """
    ppt_path = config.get('ppt_path')
    slide_idx = config.get('slide_idx', 0)
