def get_slide_and_save_info__778efd0a_compound(env, config: Dict[str, str]) -> Optional[Dict]:
    """
    Get both slide count and file modification time for a PowerPoint file.

    This compound getter retrieves:
    1. The number of slides in the presentation
    2. The file's modification timestamp

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'ppt_file_path'

    Returns:
        Dict with 'slide_count' and 'file_modified_time' keys, or None if error
    """
    ppt_file_path = config['ppt_file_path']
    result = {'slide_count': None, 'file_modified_time': None}
    file_bytes = env.controller.get_file(ppt_file_path)
    if file_bytes:
        with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        try:
            prs = Presentation(tmp_path)
            result['slide_count'] = len(prs.slides)
        except Exception:
            pass
        finally:
            try:
                os.unlink(tmp_path)
            except:
                pass
    bash_result = env.controller.run_bash_script(f"stat -c %Y '{ppt_file_path}' 2>/dev/null || echo 'ERROR'", timeout=10)
    if bash_result.get('status') == 'success' and bash_result.get('returncode') == 0:
        output = bash_result.get('output', '').strip()
        if output and output != 'ERROR':
            try:
                result['file_modified_time'] = float(output)
            except ValueError:
                pass
    if result['slide_count'] is None and result['file_modified_time'] is None:
        return None
    return result

