def get_pptx_slide_info__0b3229fd(env, config: dict) -> Dict[str, Any]:
    """
    Extract slide information from a PPTX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dictionary with slide information
    """
    pptx_path = config.get('path', '')
    if not pptx_path:
        return {'error': 'No path provided'}
    try:
        file_content = env.controller.get_file(pptx_path)
        if not file_content:
            return {'error': f'Could not read file: {pptx_path}'}
        import tempfile
        with tempfile.NamedTemporaryFile(delete=False, suffix='.pptx') as tmp:
            tmp.write(file_content)
            tmp_path = tmp.name
        prs = Presentation(tmp_path)
        slides_info = []
        for (slide_idx, slide) in enumerate(prs.slides):
            text_content = []
            for shape in slide.shapes:
                if hasattr(shape, 'text') and shape.text.strip():
                    text_content.append(shape.text.strip())
            slides_info.append({'index': slide_idx, 'text_content': text_content, 'text_hash': hash(''.join(text_content))})
        import os
        os.unlink(tmp_path)
        return {'total_slides': len(prs.slides), 'slides': slides_info}
    except Exception as e:
        return {'error': str(e)}

def get_pptx_slide_dimensions__76b25b299b0f99df101b8296ac321ee4(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract slide dimensions from PPTX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to VM file path

    Returns:
        Dict with slide width, height, and orientation info
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        logger.error(f"Failed to get file from VM: {config['path']}")
        return {}
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        width = prs.slide_width
        height = prs.slide_height
        if width > height:
            orientation = 'landscape'
        elif height > width:
            orientation = 'portrait'
        else:
            orientation = 'square'
        return {'width': width, 'height': height, 'orientation': orientation}
    except Exception as e:
        logger.error(f'Error reading presentation: {e}')
        return {}
    finally:
        os.unlink(tmp_path)

