def get_impress_slide_text_font__e6965787(env, config):
    """Extract text and font from specified slide placeholder.
    
    Args:
        env: DesktopEnv instance
        config: Dict with 'path', 'slide_idx', 'placeholder_idx'
        
    Returns:
        Dict with 'text' and 'font' keys
    """
    ppt_path = config.get('path')
    slide_idx = config.get('slide_idx', 0)
    placeholder_idx = config.get('placeholder_idx', 0)
    local_path = get_vm_file(env, {'path': ppt_path, 'dest': os.path.basename(ppt_path)})
    prs = Presentation(local_path)
    if slide_idx >= len(prs.slides):
        return {'text': '', 'font': ''}
    slide = prs.slides[slide_idx]
    if placeholder_idx == 0:
        target_shape = slide.shapes.title
        if target_shape is None:
            return {'text': '', 'font': ''}
    else:
        text_shapes = []
        for shape in slide.shapes:
            if hasattr(shape, 'text_frame') and hasattr(shape, 'text'):
                text_shapes.append(shape)
        if placeholder_idx >= len(text_shapes):
            return {'text': '', 'font': ''}
        target_shape = text_shapes[placeholder_idx]
    text = target_shape.text
    font_name = ''
    if target_shape.text_frame and target_shape.text_frame.paragraphs:
        for para in target_shape.text_frame.paragraphs:
            for run in para.runs:
                if run.text.strip() and run.font.name:
                    font_name = run.font.name
                    break
            if font_name:
                break
    return {'text': text, 'font': font_name}

