def get_pptx_image_info__1d908c97(env, config):
    """
    Extract image information from a specific slide, including image data hash.

    Args:
        env: DesktopEnv instance
        config: Dict with 'ppt_path', 'slide_idx' (0-indexed)

    Returns:
        List of dicts with image information (width, height, left, top, name, image_hash in EMUs)
    """
    ppt_path = config.get('ppt_path')
    slide_idx = config.get('slide_idx', 0)
    local_path = get_vm_file(env, {'path': ppt_path, 'dest': os.path.basename(ppt_path)})
    prs = Presentation(local_path)
    if slide_idx >= len(prs.slides):
        return []
    slide = prs.slides[slide_idx]
    images = []
    for shape in slide.shapes:
        if shape.shape_type == 13:
            image_hash = None
            try:
                if hasattr(shape, 'image') and hasattr(shape.image, 'blob'):
                    image_data = shape.image.blob
                    image_hash = hashlib.md5(image_data).hexdigest()
            except Exception:
                pass
            images.append({'width': shape.width, 'height': shape.height, 'left': shape.left, 'top': shape.top, 'name': shape.name, 'image_hash': image_hash})
    return images

