def get_pptx_start_slide__8c2c71df(env, config):
    """Get the starting slide index for slideshow.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'ppt_file_path'

    Returns:
        int: Starting slide index (0-based), or 0 if not set
    """
    ppt_file_path = config.get('ppt_file_path', '/home/user/Desktop/Forests.pptx')
    local_path = get_vm_file(env, {'path': ppt_file_path, 'dest': os.path.basename(ppt_file_path)})
    try:
        with zipfile.ZipFile(local_path, 'r') as zip_file:
            if 'ppt/presentation.xml' in zip_file.namelist():
                with zip_file.open('ppt/presentation.xml') as xml_file:
                    tree = ET.parse(xml_file)
                    root = tree.getroot()
                    ns = {'p': 'http://schemas.openxmlformats.org/presentationml/2006/main', 'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'}
                    show_pr = root.find('.//p:showPr', ns)
                    if show_pr is not None:
                        show_attr = show_pr.get('show')
                        if show_attr:
                            try:
                                return int(show_attr)
                            except:
                                pass
                        for child in show_pr:
                            if 'slide' in child.tag.lower() or 'start' in child.tag.lower():
                                idx_attr = child.get('idx') or child.get('id')
                                if idx_attr:
                                    try:
                                        return int(idx_attr) - 1
                                    except:
                                        pass
    except Exception as e:
        pass
    return 0

def get_pptx_slide_content__d9336aa8(env, config):
    """Extract all text content from a specific slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'slide_index' keys

    Returns:
        dict: Text content including title and all text items
    """
    filepath = config.get('path', '')
    slide_index = config.get('slide_index', 0)
    try:
        prs = Presentation(filepath)
        if slide_index < 0 or slide_index >= len(prs.slides):
            return {'title': '', 'text_items': []}
        slide = prs.slides[slide_index]
        title = ''
        if slide.shapes.title:
            title = slide.shapes.title.text.strip()
        text_items = []
        for shape in slide.shapes:
            if hasattr(shape, 'text'):
                text = shape.text.strip()
                if text and text != title:
                    text_items.append(text)
        return {'title': title, 'text_items': text_items}
    except Exception as e:
        return {'title': '', 'text_items': [], 'error': str(e)}

def get_pptx_slide_font_italic__de723f8fff9c9070bdb647e25bba4ac0(env, config: Dict):
    """Get font italic status from all text in a specific slide in a PowerPoint file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM file path) and 'slide_index' (0-based)

    Returns:
        Boolean indicating if ALL text in the slide is italic, or None if no text found
    """
    file_path = config.get('path')
    slide_index = config.get('slide_index', 0)
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return None
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        if slide_index >= len(prs.slides):
            return None
        slide = prs.slides[slide_index]
        has_text = False
        all_italic = True
        for shape in slide.shapes:
            if hasattr(shape, 'text') and hasattr(shape, 'text_frame'):
                for paragraph in shape.text_frame.paragraphs:
                    for run in paragraph.runs:
                        if run.text.strip():
                            has_text = True
                            if not run.font.italic:
                                all_italic = False
        if not has_text:
            return None
        return all_italic
    finally:
        os.unlink(tmp_path)

