def get_pptx_text_alignment__12c62142(env, config):
    """Get the text alignment of a PowerPoint shape.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'ppt_file_path', 'slide_index', 'shape_index'

    Returns:
        str: Alignment type ('left', 'center', 'right', 'justify') or None
    """
    ppt_file_path = config.get('ppt_file_path', '/home/user/Desktop/69_4.pptx')
    slide_index = config.get('slide_index', 0)
    shape_index = config.get('shape_index', 0)
    ppt_file_localhost_path = get_vm_file(env, {'path': ppt_file_path, 'dest': os.path.basename(ppt_file_path)})
    prs = Presentation(ppt_file_localhost_path)
    if slide_index >= len(prs.slides):
        return None
    slide = prs.slides[slide_index]
    if shape_index >= len(slide.shapes):
        return None
    shape = slide.shapes[shape_index]
    if not hasattr(shape, 'text_frame'):
        return None
    if len(shape.text_frame.paragraphs) > 0:
        para = shape.text_frame.paragraphs[0]
        if para.alignment == PP_ALIGN.CENTER:
            return 'center'
        elif para.alignment == PP_ALIGN.RIGHT:
            return 'right'
        elif para.alignment == PP_ALIGN.JUSTIFY:
            return 'justify'
        elif para.alignment == PP_ALIGN.LEFT:
            return 'left'
    return None

def get_ppt_title_font_size__c723daec(env, config):
    """Get the font size of the title text.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (PPTX file) and 'slide_index' keys

    Returns:
        int or None: Font size in EMU, or None if not found
    """
    file_path = config.get('path', '')
    slide_index = config.get('slide_index', 0)
    try:
        prs = Presentation(file_path)
        if slide_index < 0 or slide_index >= len(prs.slides):
            return None
        slide = prs.slides[slide_index]
        title_shape = None
        for shape in slide.shapes:
            if shape.shape_type == MSO_SHAPE_TYPE.PLACEHOLDER:
                if hasattr(shape, 'placeholder_format'):
                    if shape.placeholder_format.type == 1:
                        title_shape = shape
                        break
        if title_shape is None:
            for shape in slide.shapes:
                if hasattr(shape, 'name') and 'title' in shape.name.lower():
                    if hasattr(shape, 'text_frame'):
                        title_shape = shape
                        break
        if title_shape and hasattr(title_shape, 'text_frame'):
            for paragraph in title_shape.text_frame.paragraphs:
                for run in paragraph.runs:
                    if run.font.size:
                        return run.font.size
            for paragraph in title_shape.text_frame.paragraphs:
                if paragraph.font.size:
                    return paragraph.font.size
        return None
    except Exception as e:
        print(f'Error reading PPTX file: {e}')
        return None

