def get_slide_note_and_bg__829c39abbeb9cd060977e0226f1c8310(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract slide note text and background color.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key for the PPTX file path on VM

    Returns:
        Dict with 'note_text' and 'background_rgb' keys
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'note_text': '', 'background_rgb': None}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide_index = config.get('slide_index', 0)
        if slide_index >= len(prs.slides):
            return {'note_text': '', 'background_rgb': None}
        slide = prs.slides[slide_index]
        notes_slide = slide.notes_slide
        note_text = ''
        if notes_slide:
            note_text = notes_slide.notes_text_frame.text.strip()
        background_rgb = None
        fill = slide.background.fill
        if fill.type == 1:
            rgb_color = fill.fore_color.rgb
            background_rgb = (rgb_color[0], rgb_color[1], rgb_color[2])
        elif fill.type == 5:
            master_fill = slide.slide_layout.slide_master.background.fill
            if master_fill.type == 1:
                rgb_color = master_fill.fore_color.rgb
                background_rgb = (rgb_color[0], rgb_color[1], rgb_color[2])
        return {'note_text': note_text, 'background_rgb': background_rgb}
    finally:
        os.unlink(tmp_path)

