def get_pptx_text_count__a1b7e5fc16dddd07dc964bb42536ae4f(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract first 4 item texts from slide and check for old text removal.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with keys:
            - path: Path to the PPTX file on VM
            - slide_index: 0-based slide index
            - target_texts: List of new texts that should replace old ones

    Returns:
        Dict with:
            - first_four_items: List of first 4 item texts found on slide
            - all_texts: All texts found on slide (for old text checking)
            - old_texts_removed: Whether old texts are absent
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'first_four_items': [], 'all_texts': [], 'old_texts_removed': False}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide_index = config.get('slide_index', 0)
        if slide_index >= len(prs.slides):
            return {'first_four_items': [], 'all_texts': [], 'old_texts_removed': False}
        slide = prs.slides[slide_index]
        all_texts = []
        text_shapes = []
        for shape in slide.shapes:
            if hasattr(shape, 'text'):
                text = shape.text.strip()
                if text:
                    text_shapes.append({'text': text, 'top': shape.top if hasattr(shape, 'top') else 0, 'left': shape.left if hasattr(shape, 'left') else 0})
        text_shapes.sort(key=lambda x: (x['top'], x['left']))
        all_texts = [ts['text'] for ts in text_shapes]
        first_four_items = all_texts[:4] if len(all_texts) >= 4 else all_texts
        old_texts = ['Books', 'Newspapers', 'Audiobooks', 'Videotapes']
        old_texts_removed = all((old_text not in all_texts for old_text in old_texts))
        return {'first_four_items': first_four_items, 'all_texts': all_texts, 'old_texts_removed': old_texts_removed}
    finally:
        os.unlink(tmp_path)

