def get_impress_title_bold_italic__222ee8b2(env, config):
    """Get title bold and italic status.

    Args:
        env: DesktopEnv instance
        config: {"ppt_file_path": str, "slide_index": int}

    Returns:
        dict: {"bold": bool, "italic": bool}
    """
    ppt_file_path = config['ppt_file_path']
    slide_index = int(config['slide_index'])
    ppt_file_localhost_path = get_vm_file(env, {'path': ppt_file_path, 'dest': os.path.split(ppt_file_path)[-1]})
    prs = Presentation(ppt_file_localhost_path)
    if slide_index >= len(prs.slides):
        return {'bold': False, 'italic': False}
    slide = prs.slides[slide_index]
    if not slide.shapes.title:
        return {'bold': False, 'italic': False}
    title = slide.shapes.title
    if not hasattr(title, 'text_frame') or not title.text_frame.paragraphs:
        return {'bold': False, 'italic': False}
    first_para = title.text_frame.paragraphs[0]
    if not first_para.runs:
        return {'bold': False, 'italic': False}
    run = first_para.runs[0]
    return {'bold': run.font.bold is True, 'italic': run.font.italic is True}

