def get_pptx_text_alignment__bbfd9a0e(env, config):
    """Extract alignment of specific text from PPTX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with parameters:
            - path: VM file path to the PPTX file
            - dest: Local destination filename
            - slide_idx: Slide index (0-based)
            - text_to_find: Text content to search for

    Returns:
        String indicating alignment ("LEFT", "CENTER", "RIGHT", "JUSTIFY", etc.)
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return 'UNKNOWN'
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp_file:
        tmp_file.write(file_bytes)
        tmp_path = tmp_file.name
    try:
        prs = Presentation(tmp_path)
        slide_idx = config.get('slide_idx', 0)
        text_to_find = config.get('text_to_find', '')
        if slide_idx >= len(prs.slides):
            return 'UNKNOWN'
        slide = prs.slides[slide_idx]
        for shape in slide.shapes:
            if hasattr(shape, 'text') and text_to_find in shape.text:
                if hasattr(shape, 'text_frame'):
                    for para in shape.text_frame.paragraphs:
                        if text_to_find in para.text:
                            alignment = para.alignment
                            if alignment is None:
                                return 'LEFT'
                            elif alignment == PP_ALIGN.CENTER:
                                return 'CENTER'
                            elif alignment == PP_ALIGN.RIGHT:
                                return 'RIGHT'
                            elif alignment == PP_ALIGN.JUSTIFY:
                                return 'JUSTIFY'
                            elif alignment == PP_ALIGN.LEFT:
                                return 'LEFT'
                            else:
                                return str(alignment)
        return 'UNKNOWN'
    finally:
        os.unlink(tmp_path)

def get_pptx_text_font_size__b174ead8df003d2b0e1183f63d4b2d22(env, config: Dict):
    """Extract font size of all text runs in the PowerPoint presentation.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the PPTX file

    Returns:
        Dict with font size information for all text runs
    """
    file_path = config['path']
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'all_target_size': False, 'total_runs': 0, 'target_size_runs': 0}
    target_size = config.get('target_size', 24)
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        total_runs = 0
        target_size_runs = 0
        for slide in prs.slides:
            for shape in slide.shapes:
                if hasattr(shape, 'text_frame'):
                    for paragraph in shape.text_frame.paragraphs:
                        for run in paragraph.runs:
                            total_runs += 1
                            if run.font.size == Pt(target_size):
                                target_size_runs += 1
                if shape.shape_type == 19:
                    table = shape.table
                    for row in table.rows:
                        for cell in row.cells:
                            for paragraph in cell.text_frame.paragraphs:
                                for run in paragraph.runs:
                                    total_runs += 1
                                    if run.font.size == Pt(target_size):
                                        target_size_runs += 1
        all_target_size = total_runs > 0 and total_runs == target_size_runs
        return {'all_target_size': all_target_size, 'total_runs': total_runs, 'target_size_runs': target_size_runs}
    finally:
        os.unlink(tmp_path)

def get_pptx_table_dims__0dfe386c(env, config: dict):
    """Extract table dimensions from a specific slide in a PPTX file.
    
    Args:
        env: DesktopEnv instance
        config: Configuration dict with parameters:
            - ppt_file_path: Path to PPTX file on VM
            - slide_index: Index of slide to check (0-based)
            - dest: Local destination filename
            
    Returns:
        dict: {"rows": int, "cols": int, "has_table": bool}
    """
    ppt_file_path = config['ppt_file_path']
    slide_index = int(config['slide_index'])
    dest = config.get('dest', os.path.basename(ppt_file_path))
    ppt_file_localhost_path = get_vm_file(env, {'path': ppt_file_path, 'dest': dest})
    prs = Presentation(ppt_file_localhost_path)
    if slide_index >= len(prs.slides):
        return {'has_table': False, 'rows': 0, 'cols': 0}
    slide = prs.slides[slide_index]
    from pptx.enum.shapes import MSO_SHAPE_TYPE
    for shape in slide.shapes:
        if shape.shape_type == MSO_SHAPE_TYPE.TABLE:
            table = shape.table
            return {'has_table': True, 'rows': len(table.rows), 'cols': len(table.columns)}
    return {'has_table': False, 'rows': 0, 'cols': 0}

