def get_pptx_text_colors__a2fe0faa332aa822166f451f641c8ac6(env, config: dict) -> Dict[str, Any]:
    """Extract text colors from specific shapes in a PowerPoint slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM file path), 'slide_index' (0-based),
                and 'shape_indices' (list of shape indices to check)

    Returns:
        Dict mapping shape index to RGB color string (e.g., "FF0000" for red)
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide_index = config.get('slide_index', 0)
        shape_indices = config.get('shape_indices', [])
        if slide_index >= len(prs.slides):
            return {}
        slide = prs.slides[slide_index]
        result = {}
        for shape_idx in shape_indices:
            if shape_idx >= len(slide.shapes):
                continue
            shape = slide.shapes[shape_idx]
            if hasattr(shape, 'text_frame'):
                for para in shape.text_frame.paragraphs:
                    for run in para.runs:
                        if hasattr(run.font, 'color') and run.font.color.type is not None:
                            try:
                                rgb = run.font.color.rgb
                                result[str(shape_idx)] = f'{rgb[0]:02X}{rgb[1]:02X}{rgb[2]:02X}'
                            except:
                                pass
                        break
                    break
        return result
    finally:
        os.unlink(tmp_path)

