def get_pptx_slide_props__f2c2412a48d91a36910f67e03973edaa(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Extract slide properties including title text, formatting, and notes.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'slide_index' (0-based)

    Returns:
        Dict with slide properties: title_text, title_italic, notes_text
    """
    file_path = config['path']
    slide_index = config.get('slide_index', 0)
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        if slide_index >= len(prs.slides):
            return {}
        slide = prs.slides[slide_index]
        result = {'title_text': '', 'title_italic': False, 'notes_text': ''}
        if slide.shapes.title and slide.shapes.title.text_frame.paragraphs:
            result['title_text'] = slide.shapes.title.text
            all_italic = True
            has_runs = False
            for para in slide.shapes.title.text_frame.paragraphs:
                for run in para.runs:
                    has_runs = True
                    if run.font.italic is not True:
                        all_italic = False
                        break
                if not all_italic:
                    break
            result['title_italic'] = all_italic if has_runs else False
        notes_slide = slide.notes_slide
        if notes_slide and notes_slide.notes_text_frame:
            result['notes_text'] = notes_slide.notes_text_frame.text.strip()
        return result
    finally:
        os.unlink(tmp_path)

