def get_pptx_slide_info__f7bc87b7(env, config: dict) -> Dict[str, Any]:
    """
    Extract slide information from a PPTX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dictionary with slide information
    """
    pptx_path = config.get('path', '')
    if not pptx_path:
        return {'error': 'No path provided'}
    try:
        file_content = env.controller.get_file(pptx_path)
        if not file_content:
            return {'error': f'Could not read file: {pptx_path}'}
        import tempfile
        with tempfile.NamedTemporaryFile(delete=False, suffix='.pptx') as tmp:
            tmp.write(file_content)
            tmp_path = tmp.name
        prs = Presentation(tmp_path)
        slides_info = []
        for (slide_idx, slide) in enumerate(prs.slides):
            text_content = []
            for shape in slide.shapes:
                if hasattr(shape, 'text') and shape.text.strip():
                    text_content.append(shape.text.strip())
            slides_info.append({'index': slide_idx, 'text_content': text_content, 'text_hash': hash(''.join(text_content))})
        import os
        os.unlink(tmp_path)
        return {'total_slides': len(prs.slides), 'slides': slides_info}
    except Exception as e:
        return {'error': str(e)}

def get_pptx_image_centered__7dd603be8baddadbade4627cafe348dc(env, config: dict):
    """Get the horizontal position of an image and slide width to check centering.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with parameters:
            - path: Path to the PPTX file on VM
            - slide_index: 0-based slide index (default: 0)
            - shape_type: Shape type to find (default: 13 for PICTURE)

    Returns:
        dict: Shape position info with keys: left, width, slide_width, center_x
    """
    file_path = config.get('path', '')
    slide_index = config.get('slide_index', 0)
    shape_type = config.get('shape_type', 13)
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        if slide_index >= len(prs.slides):
            return {}
        slide = prs.slides[slide_index]
        slide_width = prs.slide_width
        for shape in slide.shapes:
            if shape.shape_type == shape_type:
                center_x = shape.left + shape.width / 2
                slide_center = slide_width / 2
                return {'left': shape.left, 'width': shape.width, 'slide_width': slide_width, 'center_x': center_x, 'slide_center': slide_center, 'offset_from_center': abs(center_x - slide_center)}
        return {}
    finally:
        os.unlink(tmp_path)

