def get_slide_bg_color__80de3a8cf8e0e83b7c4b907269f7565e(env, config: Dict[str, Any]) -> Optional[Tuple[int, int, int]]:
    """Extract background color from a specific slide in a PowerPoint file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - path: VM path to the PPTX file
            - slide_index: Index of the slide to check (0-based)

    Returns:
        RGB tuple (r, g, b) if solid fill background exists, None otherwise
    """
    file_path = config.get('path')
    slide_index = config.get('slide_index', 0)
    if not file_path:
        return None
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return None
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        if slide_index >= len(prs.slides):
            return None
        slide = prs.slides[slide_index]
        fill = slide.background.fill
        if fill.type == 1:
            rgb = fill.fore_color.rgb
            return (rgb[0], rgb[1], rgb[2])
        elif fill.type == 5:
            master_fill = slide.slide_layout.slide_master.background.fill
            if master_fill.type == 1:
                rgb = master_fill.fore_color.rgb
                return (rgb[0], rgb[1], rgb[2])
        return None
    finally:
        os.unlink(tmp_path)

def get_pptx_slide_title_subtitle__0755868b(env, config: Dict[str, Any]):
    """Extract both title and subtitle text from a specific slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with keys:
            - path: VM path to the PowerPoint file
            - dest: Destination filename
            - slide_index: Index of the slide (0-based)

    Returns:
        dict: {'title': str, 'subtitle': str} or None if slide doesn't exist
    """
    ppt_path = config['path']
    dest = config['dest']
    slide_index = config['slide_index']
    local_path = get_vm_file(env, {'path': ppt_path, 'dest': dest})
    prs = Presentation(local_path)
    if slide_index >= len(prs.slides):
        return None
    slide = prs.slides[slide_index]
    title = ''
    subtitle = ''
    for shape in slide.shapes:
        if shape.shape_type == MSO_SHAPE_TYPE.PLACEHOLDER and hasattr(shape, 'placeholder_format'):
            placeholder_type = shape.placeholder_format.type
            if placeholder_type == PP_PLACEHOLDER.TITLE:
                if hasattr(shape, 'text_frame'):
                    title = shape.text_frame.text.strip()
            elif placeholder_type == PP_PLACEHOLDER.SUBTITLE:
                if hasattr(shape, 'text_frame'):
                    subtitle = shape.text_frame.text.strip()
    return {'title': title, 'subtitle': subtitle}

