def get_pptx_text_alignment__4ca61115(env, config):
    """Get text alignment of paragraphs in a specific slide and shape.

    Args:
        env: DesktopEnv instance
        config: Dict with keys: ppt_path, slide_index, shape_index

    Returns:
        str: Alignment type ('LEFT', 'CENTER', 'RIGHT') if all paragraphs have same alignment, None otherwise
    """
    ppt_path = config['ppt_path']
    slide_index = int(config['slide_index'])
    shape_index = int(config['shape_index'])
    local_path = get_vm_file(env, {'path': ppt_path, 'dest': os.path.basename(ppt_path)})
    prs = Presentation(local_path)
    slide = prs.slides[slide_index]
    shape = slide.shapes[shape_index]
    if not hasattr(shape, 'text_frame'):
        return None
    first_align = None
    for paragraph in shape.text_frame.paragraphs:
        align = paragraph.alignment
        if align is None:
            align = PP_ALIGN.LEFT
        align_name = align.name if hasattr(align, 'name') else str(align)
        if first_align is None:
            first_align = align_name
        elif align_name != first_align:
            return None
    return first_align

