def get_pptx_slide_all_text__a95c712738854b59d70ef971da9aed06(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract text content from a specific slide with shape-level details.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'slide_index'

    Returns:
        Dict containing:
            - all_text: List of all text strings from the slide
            - shapes: List of dicts with shape info (text, is_bulleted, contains_marker)
    """
    file_path = config['path']
    slide_index = config.get('slide_index', 0)
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'all_text': [], 'shapes': []}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        if slide_index >= len(prs.slides):
            return {'all_text': [], 'shapes': []}
        slide = prs.slides[slide_index]
        all_text = []
        shapes_info = []
        for shape in slide.shapes:
            if hasattr(shape, 'text') and shape.text.strip():
                shape_text_lines = []
                is_bulleted = False
                if hasattr(shape, 'text_frame'):
                    for paragraph in shape.text_frame.paragraphs:
                        para_text = paragraph.text.strip()
                        if para_text:
                            shape_text_lines.append(para_text)
                            all_text.append(para_text)
                            if paragraph.level is not None and paragraph.level >= 0:
                                is_bulleted = True
                else:
                    for line in shape.text.strip().split('\n'):
                        if line.strip():
                            shape_text_lines.append(line.strip())
                            all_text.append(line.strip())
                contains_question_mark = '?' in shape.text
                shapes_info.append({'text_lines': shape_text_lines, 'is_bulleted': is_bulleted, 'contains_question_mark': contains_question_mark, 'full_text': shape.text.strip()})
        return {'all_text': all_text, 'shapes': shapes_info}
    finally:
        os.unlink(tmp_path)

