def get_pptx_text_alignment__91f2d4efc8abe159b08e05f3f915dc20(env, config: dict):
    """Extract text alignment from specific shape in PowerPoint slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM file path), 'slide_idx' (0-based), 'shape_idx'

    Returns:
        dict: Dictionary with alignment info for each paragraph
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide_idx = config.get('slide_idx', 0)
        shape_idx = config.get('shape_idx', 0)
        if slide_idx >= len(prs.slides):
            return {}
        slide = prs.slides[slide_idx]
        if shape_idx >= len(slide.shapes):
            return {}
        shape = slide.shapes[shape_idx]
        if not hasattr(shape, 'text_frame'):
            return {}
        alignments = []
        for para in shape.text_frame.paragraphs:
            align = para.alignment
            if align == PP_ALIGN.LEFT or align is None:
                align_str = 'LEFT'
            elif align == PP_ALIGN.CENTER:
                align_str = 'CENTER'
            elif align == PP_ALIGN.RIGHT:
                align_str = 'RIGHT'
            elif align == PP_ALIGN.JUSTIFY:
                align_str = 'JUSTIFY'
            else:
                align_str = str(align)
            alignments.append({'text': para.text, 'alignment': align_str})
        return {'slide_idx': slide_idx, 'shape_idx': shape_idx, 'alignments': alignments}
    finally:
        os.unlink(tmp_path)

