def get_pptx_all_font_sizes__49bb51459f60a59fee0c5ae974eef314(env, config: Dict):
    """Extract all effective font sizes used in the presentation, including Slide Master defaults.

    This function reads explicit font sizes from all text runs in the presentation.
    For text with inherited sizes (None), it attempts to determine the actual inherited size
    by checking the Slide Master default font sizes.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: Contains 'explicit_sizes' (set of explicit font sizes),
              'has_inherited' (bool indicating if there are inherited sizes),
              'master_default_sizes' (set of default font sizes from Slide Master)
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'explicit_sizes': set(), 'has_inherited': False, 'master_default_sizes': set()}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        explicit_sizes = set()
        has_inherited = False
        has_any_text = False
        master_default_sizes = set()
        for slide_master in prs.slide_masters:
            for shape in slide_master.shapes:
                if hasattr(shape, 'text_frame'):
                    for paragraph in shape.text_frame.paragraphs:
                        for run in paragraph.runs:
                            if run.font.size:
                                master_default_sizes.add(run.font.size.pt)
        for slide in prs.slides:
            for shape in slide.shapes:
                if hasattr(shape, 'text_frame'):
                    for paragraph in shape.text_frame.paragraphs:
                        for run in paragraph.runs:
                            if run.text.strip():
                                has_any_text = True
                                if run.font.size:
                                    size_in_pt = run.font.size.pt
                                    explicit_sizes.add(size_in_pt)
                                else:
                                    has_inherited = True
        return {'explicit_sizes': explicit_sizes, 'has_inherited': has_inherited, 'has_any_text': has_any_text, 'master_default_sizes': master_default_sizes}
    finally:
        os.unlink(tmp_path)

def get_slide_attributes__bc9d70e051ecb26bd847ac838273b6bf(env, config: dict) -> Dict[str, Any]:
    """Extract slide attributes including title text and background color.
    
    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the PPTX file on VM
        
    Returns:
        Dict with slide attributes: {slide_index: {"title": str, "bg_color": str}}
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        result = {}
        for (idx, slide) in enumerate(prs.slides):
            attrs = {}
            title = None
            if slide.shapes.title and slide.shapes.title.text:
                title = slide.shapes.title.text.strip()
            else:
                for shape in slide.shapes:
                    if hasattr(shape, 'text') and shape.text and shape.text.strip():
                        title = shape.text.strip()
                        break
            attrs['title'] = title
            bg_color = None
            try:
                if slide.background.fill.type == 1:
                    if hasattr(slide.background.fill, 'fore_color'):
                        color = slide.background.fill.fore_color
                        if hasattr(color, 'rgb'):
                            rgb = color.rgb
                            bg_color = f'#{rgb[0]:02X}{rgb[1]:02X}{rgb[2]:02X}'
            except:
                pass
            attrs['bg_color'] = bg_color
            result[idx] = attrs
        return result
    finally:
        os.unlink(tmp_path)

