def get_pptx_pic_text_props__8f26e0b2(env, config: dict) -> Dict[str, Any]:
    """
    Extract picture dimension and text font sizes from PowerPoint file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict

    Returns:
        Dict with picture dimension and font sizes
    """
    file_path = config.get('file_path', '/home/user/Desktop/42_2.pptx')
    slide_picture_idx = config.get('slide_picture', 3)
    slide_text_idx = config.get('slide_text', 1)
    picture_idx = config.get('picture_index', 0)
    picture_check_dim = config.get('picture_check', 'width')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'error': 'Failed to retrieve file'}
    import tempfile
    import os as os_mod
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        picture_value_cm = None
        if slide_picture_idx < len(prs.slides):
            slide_pic = prs.slides[slide_picture_idx]
            if picture_idx < len(slide_pic.shapes):
                shape = slide_pic.shapes[picture_idx]
                if hasattr(shape, picture_check_dim):
                    value_emu = getattr(shape, picture_check_dim)
                    picture_value_cm = round(value_emu / 360000, 2)
        font_sizes = []
        if slide_text_idx < len(prs.slides):
            slide_text = prs.slides[slide_text_idx]
            for shape in slide_text.shapes:
                if hasattr(shape, 'text_frame'):
                    for para in shape.text_frame.paragraphs:
                        for run in para.runs:
                            if run.font.size:
                                font_sizes.append(run.font.size.pt)
        result_key = f'picture_{picture_check_dim}_cm'
        return {result_key: picture_value_cm, 'font_sizes': font_sizes}
    finally:
        os_mod.unlink(tmp_path)

