def get_pptx_slide_font_bold__dd63ef312759002c748e6d417914be1a(env, config: Dict):
    """Get font bold status from a specific slide in a PowerPoint file.

    Checks ALL text runs in ALL shapes in the slide to ensure comprehensive verification.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM file path) and 'slide_index' (0-based)

    Returns:
        Boolean indicating if ALL text is bold (True if all bold, False if any not bold, None if no text found)
    """
    file_path = config.get('path')
    slide_index = config.get('slide_index', 0)
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return None
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        if slide_index >= len(prs.slides):
            return None
        slide = prs.slides[slide_index]
        has_text = False
        all_bold = True
        for shape in slide.shapes:
            if hasattr(shape, 'text') and hasattr(shape, 'text_frame'):
                for paragraph in shape.text_frame.paragraphs:
                    for run in paragraph.runs:
                        if run.text.strip():
                            has_text = True
                            run_bold = run.font.bold if run.font.bold is not None else False
                            if not run_bold:
                                all_bold = False
        if not has_text:
            return None
        return all_bold
    finally:
        os.unlink(tmp_path)

