def get_pptx_table_dims__01428053(env, config: dict):
    """Extract table dimensions from a specific slide in a PPTX file.
    
    Args:
        env: DesktopEnv instance
        config: Configuration dict with parameters:
            - ppt_file_path: Path to PPTX file on VM
            - slide_index: Index of slide to check (0-based)
            - dest: Local destination filename
            
    Returns:
        dict: {"rows": int, "cols": int, "has_table": bool}
    """
    ppt_file_path = config['ppt_file_path']
    slide_index = int(config['slide_index'])
    dest = config.get('dest', os.path.basename(ppt_file_path))
    ppt_file_localhost_path = get_vm_file(env, {'path': ppt_file_path, 'dest': dest})
    prs = Presentation(ppt_file_localhost_path)
    if slide_index >= len(prs.slides):
        return {'has_table': False, 'rows': 0, 'cols': 0}
    slide = prs.slides[slide_index]
    from pptx.enum.shapes import MSO_SHAPE_TYPE
    for shape in slide.shapes:
        if shape.shape_type == MSO_SHAPE_TYPE.TABLE:
            table = shape.table
            return {'has_table': True, 'rows': len(table.rows), 'cols': len(table.columns)}
    return {'has_table': False, 'rows': 0, 'cols': 0}

def get_impress_title_alignment__c78bffa7(env, config):
    """Get title alignment on specified slide.

    Args:
        env: DesktopEnv instance
        config: {"ppt_file_path": str, "slide_index": int}

    Returns:
        int: Alignment value (PP_ALIGN enum), or None
    """
    ppt_file_path = config['ppt_file_path']
    slide_index = int(config['slide_index'])
    ppt_file_localhost_path = get_vm_file(env, {'path': ppt_file_path, 'dest': os.path.split(ppt_file_path)[-1]})
    prs = Presentation(ppt_file_localhost_path)
    if slide_index >= len(prs.slides):
        return None
    slide = prs.slides[slide_index]
    if not slide.shapes.title:
        return None
    title = slide.shapes.title
    if not hasattr(title, 'text_frame') or not title.text_frame.paragraphs:
        return None
    first_para = title.text_frame.paragraphs[0]
    alignment = first_para.alignment
    if alignment is None:
        return PP_ALIGN.LEFT
    return alignment

def get_ppt_note_and_bg__ac6c4c6d3625788da1eaae3df98b2ca5(env, config: dict):
    """Extract both note text and background color from a PowerPoint slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'slide_index' keys

    Returns:
        dict: Dictionary with 'note_text' and 'background_rgb' keys
    """
    pptx_path = config.get('path', '')
    slide_index = config.get('slide_index', 0)
    file_bytes = env.controller.get_file(pptx_path)
    if not file_bytes:
        return {'note_text': '', 'background_rgb': None}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        if slide_index >= len(prs.slides):
            return {'note_text': '', 'background_rgb': None}
        slide = prs.slides[slide_index]
        note_text = ''
        if hasattr(slide, 'notes_slide') and slide.notes_slide:
            notes_text_frame = slide.notes_slide.notes_text_frame
            if notes_text_frame:
                note_text = notes_text_frame.text.strip()
        background_rgb = None
        fill = slide.background.fill
        if fill.type == 1:
            background_rgb = fill.fore_color.rgb
        elif fill.type == 5:
            master_fill = slide.slide_layout.slide_master.background.fill
            if master_fill.type == 1:
                background_rgb = master_fill.fore_color.rgb
        return {'note_text': note_text, 'background_rgb': background_rgb}
    finally:
        os.unlink(tmp_path)

def get_pptx_pic_text_props__e25123ff(env, config: dict) -> Dict[str, Any]:
    """
    Extract picture dimension and text font sizes from PowerPoint file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict

    Returns:
        Dict with picture dimension and font sizes
    """
    file_path = config.get('file_path', '/home/user/Desktop/42_2.pptx')
    slide_picture_idx = config.get('slide_picture', 2)
    slide_text_idx = config.get('slide_text', 4)
    picture_idx = config.get('picture_index', 0)
    picture_check_dim = config.get('picture_check', 'width')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'error': 'Failed to retrieve file'}
    import tempfile
    import os as os_mod
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        picture_value_cm = None
        if slide_picture_idx < len(prs.slides):
            slide_pic = prs.slides[slide_picture_idx]
            if picture_idx < len(slide_pic.shapes):
                shape = slide_pic.shapes[picture_idx]
                if hasattr(shape, picture_check_dim):
                    value_emu = getattr(shape, picture_check_dim)
                    picture_value_cm = round(value_emu / 360000, 2)
        font_sizes = []
        if slide_text_idx < len(prs.slides):
            slide_text = prs.slides[slide_text_idx]
            for shape in slide_text.shapes:
                if hasattr(shape, 'text_frame'):
                    for para in shape.text_frame.paragraphs:
                        for run in para.runs:
                            if run.font.size:
                                font_sizes.append(run.font.size.pt)
        result_key = f'picture_{picture_check_dim}_cm'
        return {result_key: picture_value_cm, 'font_sizes': font_sizes}
    finally:
        os_mod.unlink(tmp_path)

def get_pptx_image_aspect_ratio__8db3949b(env, config):
    """Get aspect ratio of first image in a slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'ppt_file_path' and 'slide_index'

    Returns:
        float: Aspect ratio (width/height), or None if no image
    """
    ppt_file_path = config['ppt_file_path']
    slide_index = int(config['slide_index'])
    ppt_file_localhost = get_vm_file(env, {'path': ppt_file_path, 'dest': os.path.basename(ppt_file_path)})
    prs = Presentation(ppt_file_localhost)
    if slide_index >= len(prs.slides):
        return None
    slide = prs.slides[slide_index]
    for shape in slide.shapes:
        if shape.shape_type == 13:
            if shape.height == 0:
                return None
            aspect_ratio = round(shape.width / shape.height, 3)
            return aspect_ratio
    return None

