def get_pptx_slide_text__5a77909cb03dbc0ff918e04df7629ca9(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract text and formatting from a PowerPoint slide.
    
    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key for the PPTX file path
        
    Returns:
        Dictionary containing slide text and formatting information
    """
    file_path = config.get('path')
    if not file_path:
        return {'error': 'No file path provided'}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'error': 'Failed to retrieve file from VM'}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        result = {'slides': [], 'total_slides': len(prs.slides)}
        for (slide_idx, slide) in enumerate(prs.slides):
            slide_info = {'slide_index': slide_idx, 'shapes': []}
            for shape in slide.shapes:
                if hasattr(shape, 'text_frame'):
                    shape_data = {'text': shape.text, 'runs': []}
                    for paragraph in shape.text_frame.paragraphs:
                        for run in paragraph.runs:
                            if run.text.strip():
                                run_info = {'text': run.text, 'font_name': run.font.name, 'font_size': run.font.size.pt if run.font.size else None, 'bold': run.font.bold, 'italic': run.font.italic}
                                if run.font.color and run.font.color.type == 1:
                                    rgb = run.font.color.rgb
                                    run_info['color'] = {'r': rgb[0], 'g': rgb[1], 'b': rgb[2]}
                                shape_data['runs'].append(run_info)
                    if shape_data['runs']:
                        slide_info['shapes'].append(shape_data)
            result['slides'].append(slide_info)
        return result
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

def get_ppt_properties__63399308(env, config: Dict):
    """
    Extract PPT properties (font size, bold, italic, colors, background).

    Args:
        env: DesktopEnv instance
        config: Dict with 'path' and 'dest'

    Returns:
        Dict with various properties
    """
    from desktop_env.evaluators.getters.file import get_vm_file
    ppt_path = config.get('path', '/home/user/Desktop/16_2.pptx')
    dest = config.get('dest', '16_2.pptx')
    local_path = get_vm_file(env, {'path': ppt_path, 'dest': dest})
    prs = Presentation(local_path)
    slide = prs.slides[0]
    result = {}
    if len(slide.shapes) > 0:
        title_shape = slide.shapes[0]
        if hasattr(title_shape, 'text_frame'):
            para = title_shape.text_frame.paragraphs[0]
            if para.runs:
                run = para.runs[0]
                result['title_size'] = run.font.size
                result['title_bold'] = run.font.bold
                result['title_italic'] = run.font.italic
                if hasattr(run.font.color, 'rgb'):
                    rgb = run.font.color.rgb
                    result['title_color'] = (rgb[0], rgb[1], rgb[2])
    if len(slide.shapes) > 1:
        content_shape = slide.shapes[1]
        if hasattr(content_shape, 'text_frame'):
            para = content_shape.text_frame.paragraphs[0]
            if para.runs:
                run = para.runs[0]
                result['content_size'] = run.font.size
                result['content_bold'] = run.font.bold
                result['content_italic'] = run.font.italic
                if hasattr(run.font.color, 'rgb'):
                    rgb = run.font.color.rgb
                    result['content_color'] = (rgb[0], rgb[1], rgb[2])
    fill = slide.background.fill
    if fill.type == 1:
        if hasattr(fill.fore_color, 'rgb'):
            rgb = fill.fore_color.rgb
            result['bg_color'] = (rgb[0], rgb[1], rgb[2])
    return result

def get_pptx_text_underline__b4f0ad7e(env, config):
    """Get underline status of text in a specific slide and shape.

    Args:
        env: DesktopEnv instance
        config: Dict with keys: ppt_path, slide_index, shape_index

    Returns:
        bool: True if all text is underlined, False otherwise
    """
    ppt_path = config['ppt_path']
    slide_index = int(config['slide_index'])
    shape_index = int(config['shape_index'])
    local_path = get_vm_file(env, {'path': ppt_path, 'dest': os.path.basename(ppt_path)})
    prs = Presentation(local_path)
    slide = prs.slides[slide_index]
    shape = slide.shapes[shape_index]
    if not hasattr(shape, 'text_frame'):
        return False
    for paragraph in shape.text_frame.paragraphs:
        for run in paragraph.runs:
            if not run.font.underline:
                return False
    return True

def get_pptx_slide_info__7806b81c(env, config: dict) -> Dict[str, Any]:
    """
    Extract slide information from a PPTX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dictionary with slide information
    """
    pptx_path = config.get('path', '')
    if not pptx_path:
        return {'error': 'No path provided'}
    try:
        file_content = env.controller.get_file(pptx_path)
        if not file_content:
            return {'error': f'Could not read file: {pptx_path}'}
        import tempfile
        with tempfile.NamedTemporaryFile(delete=False, suffix='.pptx') as tmp:
            tmp.write(file_content)
            tmp_path = tmp.name
        prs = Presentation(tmp_path)
        slides_info = []
        for (slide_idx, slide) in enumerate(prs.slides):
            text_content = []
            for shape in slide.shapes:
                if hasattr(shape, 'text') and shape.text.strip():
                    text_content.append(shape.text.strip())
            slides_info.append({'index': slide_idx, 'text_content': text_content, 'text_hash': hash(''.join(text_content))})
        import os
        os.unlink(tmp_path)
        return {'total_slides': len(prs.slides), 'slides': slides_info}
    except Exception as e:
        return {'error': str(e)}

