def get_pptx_title_font_size__a253de75e700af370d8f8a5a31c60bce(env, config):
    """Extract font sizes of titles in specified slides.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with keys:
            - path: VM file path (e.g., "/home/user/Desktop/4_1.pptx")
            - slides: List of slide indices (0-based) to check

    Returns:
        dict: Mapping of slide_index -> font_size_in_points (float or None)
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        result = {}
        for slide_idx in config.get('slides', []):
            if slide_idx >= len(prs.slides):
                continue
            slide = prs.slides[slide_idx]
            title_shape = None
            if slide.shapes.title:
                title_shape = slide.shapes.title
            else:
                for shape in slide.shapes:
                    if hasattr(shape, 'text') and shape.text.strip():
                        title_shape = shape
                        break
            if title_shape and hasattr(title_shape, 'text_frame'):
                for para in title_shape.text_frame.paragraphs:
                    for run in para.runs:
                        if run.text.strip() and run.font.size is not None:
                            result[slide_idx] = run.font.size.pt
                            break
                    if slide_idx in result:
                        break
        return result
    finally:
        os.unlink(tmp_path)

def get_impress_slide_images__360e07ae(env, config):
    """
    Get detailed information about images in each slide of a PPTX presentation.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key for the PPTX file path on VM

    Returns:
        dict: Dictionary with slide_count and slide_images information
            {
                'slide_count': int,
                'slide_images': [
                    {'slide_num': 1, 'image_count': int, 'image_names': [str]},
                    ...
                ]
            }
    """
    from desktop_env.evaluators.getters.file import get_vm_file
    vm_path = config.get('path', '/home/user/Desktop/4.3-Template_4.29.2016.pptx')
    local_path = get_vm_file(env, {'path': vm_path, 'dest': os.path.basename(vm_path)})
    prs = Presentation(local_path)
    slide_images_info = []
    for (slide_idx, slide) in enumerate(prs.slides):
        image_names = []
        image_count = 0
