def get_pptx_all_fonts__b4e3d024006609a5c60d8783521e88dc(env, config: Dict):
    """Extract all unique fonts used in the presentation, including Slide Master fonts.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key (e.g., {'path': '/home/user/file.pptx'})

    Returns:
        dict: Dictionary with 'slide_fonts' (set of fonts in slides) and 'master_fonts' (set of fonts in Slide Master)
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'slide_fonts': set(), 'master_fonts': set()}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide_fonts = set()
        master_fonts = set()

        def extract_fonts_from_shape(shape, font_set: Set):
            if hasattr(shape, 'text_frame'):
                for paragraph in shape.text_frame.paragraphs:
                    if hasattr(paragraph, 'font') and paragraph.font.name:
                        font_set.add(paragraph.font.name)
                    for run in paragraph.runs:
                        if run.font.name:
                            font_set.add(run.font.name)
                        elif hasattr(paragraph, 'font') and paragraph.font.name:
                            font_set.add(paragraph.font.name)
        if hasattr(prs, 'slide_master'):
            slide_master = prs.slide_master
            for shape in slide_master.shapes:
                extract_fonts_from_shape(shape, master_fonts)
            if hasattr(slide_master, 'slide_layouts'):
                for layout in slide_master.slide_layouts:
                    for shape in layout.shapes:
                        extract_fonts_from_shape(shape, master_fonts)
        for slide in prs.slides:
            for shape in slide.shapes:
                extract_fonts_from_shape(shape, slide_fonts)
        return {'slide_fonts': slide_fonts, 'master_fonts': master_fonts}
    finally:
        os.unlink(tmp_path)

def get_pptx_note_and_bg__3b49735e(env, config):
    """Extract slide note text and background color from PowerPoint file.
    
    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key for the .pptx file path
        
    Returns:
        dict: {"note": str, "bg_color": tuple or None}
    """
    from desktop_env.evaluators.getters.file import get_vm_file
    import os
    pptx_path = config.get('path', '/home/user/Desktop/181_2.pptx')
    local_path = get_vm_file(env, {'path': pptx_path, 'dest': os.path.basename(pptx_path)})
    prs = Presentation(local_path)
    if len(prs.slides) == 0:
        return {'note': '', 'bg_color': None}
    slide = prs.slides[0]
    notes_slide = slide.notes_slide
    note_text = notes_slide.notes_text_frame.text.strip() if notes_slide else ''

    def get_slide_background_color(slide):
        fill = slide.background.fill
        if fill.type == 1:
            return fill.fore_color.rgb
        elif fill.type == 5:
            master_fill = slide.slide_layout.slide_master.background.fill
            if master_fill.type == 1:
                return master_fill.fore_color.rgb
            else:
                return None
        else:
            return None
    bg_color = get_slide_background_color(slide)
    return {'note': note_text, 'bg_color': bg_color}

def get_pptx_slide_images__ac767a1a553ddde79f4861578e853e9e(env, config: Dict):
    """Extract slide count, image information, hashes, and non-image shapes from PowerPoint file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the PPTX file

    Returns:
        dict: {
            'slide_count': int,
            'slides': [{
                'slide_idx': int,
                'image_count': int,
                'non_image_shape_count': int,
                'image_hashes': [str, ...]  # MD5 hashes of images on this slide
            }, ...]
        }
    """
    file_path = config['path']
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'slide_count': 0, 'slides': []}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide_count = len(prs.slides)
        slides = []
        for (slide_idx, slide) in enumerate(prs.slides):
            image_count = 0
            non_image_shape_count = 0
            image_hashes = []
            for shape in slide.shapes:
                if shape.shape_type == 13:
                    image_count += 1
                    try:
                        image = shape.image
                        image_bytes = image.blob
                        image_hash = hashlib.md5(image_bytes).hexdigest()
                        image_hashes.append(image_hash)
                    except Exception:
                        image_hashes.append(None)
                elif hasattr(shape, 'has_text_frame') and shape.has_text_frame:
                    if shape.text_frame.text.strip():
                        non_image_shape_count += 1
                elif not hasattr(shape, 'is_placeholder') or not shape.is_placeholder:
                    non_image_shape_count += 1
            slides.append({'slide_idx': slide_idx, 'image_count': image_count, 'non_image_shape_count': non_image_shape_count, 'image_hashes': image_hashes})
        return {'slide_count': slide_count, 'slides': slides}
    finally:
        os.unlink(tmp_path)

