def get_pptx_text_italic_and_color__c87a628e6a03815cd122590aceaf95ed(env, config: Dict):
    """Extract italic status and color of all text runs in the PowerPoint presentation.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the PPTX file

    Returns:
        Dict with italic and color status information for all text runs
    """
    file_path = config['path']
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'all_italic_and_blue': False, 'total_runs': 0, 'italic_runs': 0, 'blue_runs': 0}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        total_runs = 0
        italic_runs = 0
        blue_runs = 0
        both_runs = 0
        for slide in prs.slides:
            for shape in slide.shapes:
                if hasattr(shape, 'text_frame'):
                    for paragraph in shape.text_frame.paragraphs:
                        for run in paragraph.runs:
                            total_runs += 1
                            is_italic = run.font.italic is True
                            is_blue = False
                            if hasattr(run.font.color, 'rgb') and run.font.color.rgb is not None:
                                rgb = run.font.color.rgb
                                if rgb[2] > 150 and rgb[2] > rgb[0] + 50 and (rgb[2] > rgb[1] + 50):
                                    is_blue = True
                            if is_italic:
                                italic_runs += 1
                            if is_blue:
                                blue_runs += 1
                            if is_italic and is_blue:
                                both_runs += 1
                if shape.shape_type == 19:
                    table = shape.table
                    for row in table.rows:
                        for cell in row.cells:
                            for paragraph in cell.text_frame.paragraphs:
                                for run in paragraph.runs:
                                    total_runs += 1
                                    is_italic = run.font.italic is True
                                    is_blue = False
                                    if hasattr(run.font.color, 'rgb') and run.font.color.rgb is not None:
                                        rgb = run.font.color.rgb
                                        if rgb[2] > 150 and rgb[2] > rgb[0] + 50 and (rgb[2] > rgb[1] + 50):
                                            is_blue = True
                                    if is_italic:
                                        italic_runs += 1
                                    if is_blue:
                                        blue_runs += 1
                                    if is_italic and is_blue:
                                        both_runs += 1
        all_italic_and_blue = total_runs > 0 and total_runs == both_runs
        return {'all_italic_and_blue': all_italic_and_blue, 'total_runs': total_runs, 'italic_runs': italic_runs, 'blue_runs': blue_runs, 'both_runs': both_runs}
    finally:
        os.unlink(tmp_path)

def get_pptx_text_bold__a8c28903eaed59fecc0fe86ee46c82c0(env, config):
    """Extract bold status of text runs from specific slides in a PPTX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with parameters:
            - path: Path to the PPTX file on VM
            - slide_indices: List of slide indices (0-based) to check

    Returns:
        dict: Mapping of slide_index -> list of bold status for each text run
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide_indices = config.get('slide_indices', [0])
        result = {}
        for slide_idx in slide_indices:
            if slide_idx >= len(prs.slides):
                continue
            slide = prs.slides[slide_idx]
            bold_status = []
            for shape in slide.shapes:
                if hasattr(shape, 'text_frame') and shape.text:
                    for para in shape.text_frame.paragraphs:
                        for run in para.runs:
                            bold_status.append(run.font.bold if run.font.bold is not None else False)
            result[slide_idx] = bold_status
        return result
    finally:
        os.unlink(tmp_path)

def get_slide_bg_and_notes__3a2c0296(env, config: Dict) -> Dict:
    """
    Get slide background color and notes text for variation 2 (green background).

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'pptx_path' and 'slide_idx'

    Returns:
        Dict with 'background_rgb' (tuple or None) and 'notes_text' (str)
    """
    pptx_path = config.get('pptx_path')
    slide_idx = config.get('slide_idx', 0)
    file_bytes = env.controller.get_file(pptx_path)
    if not file_bytes:
        return {'background_rgb': None, 'notes_text': ''}
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(delete=False, suffix='.pptx') as tmp_file:
        tmp_file.write(file_bytes)
        tmp_path = tmp_file.name
    try:
        prs = Presentation(tmp_path)
        if slide_idx >= len(prs.slides):
            return {'background_rgb': None, 'notes_text': ''}
        slide = prs.slides[slide_idx]
        bg_rgb = None
        fill = slide.background.fill
        if fill.type == 1:
            try:
                bg_rgb = fill.fore_color.rgb
            except:
                bg_rgb = None
        elif fill.type == 5:
            try:
                master_fill = slide.slide_layout.slide_master.background.fill
                if master_fill.type == 1:
                    bg_rgb = master_fill.fore_color.rgb
            except:
                bg_rgb = None
        notes_text = ''
        if slide.has_notes_slide:
            notes_slide = slide.notes_slide
            if notes_slide.notes_text_frame:
                notes_text = notes_slide.notes_text_frame.text.strip()
        return {'background_rgb': bg_rgb, 'notes_text': notes_text}
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

def get_pptx_picture_dims__debd2a2c(env, config):
    """Extract picture dimension(s) from specified slide(s).
    
    Args:
        env: DesktopEnv instance
        config: Configuration dict
        
    Returns:
        dict: Dimension data based on task requirements
    """
    import tempfile
    import os
    from pptx import Presentation
    vm_path = config.get('path', '/home/user/Desktop/30_1.pptx')
    file_content = env.controller.get_file(vm_path)
    if not file_content:
        return None
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp_file:
        tmp_file.write(file_content)
        tmp_path = tmp_file.name
    try:
        prs = Presentation(tmp_path)
        result = {}
        slides_to_check = config.get('slides', [])
        shape_indices = config.get('shape_indices', [])
        dimensions = config.get('dimensions', ['height', 'width'])
        for (i, slide_num) in enumerate(slides_to_check):
            if len(prs.slides) >= slide_num:
                slide = prs.slides[slide_num - 1]
                shape_idx = shape_indices[i] if i < len(shape_indices) else 0
                if len(slide.shapes) > shape_idx and slide.shapes[shape_idx].shape_type == 13:
                    slide_data = {}
                    if 'height' in dimensions:
                        slide_data['height'] = round(slide.shapes[shape_idx].height / 360000, 2)
                    if 'width' in dimensions:
                        slide_data['width'] = round(slide.shapes[shape_idx].width / 360000, 2)
                    result[slide_num] = slide_data
                else:
                    result[slide_num] = None
        return result
    finally:
        os.unlink(tmp_path)

def get_pptx_text_italic__835d542d(env, config):
    """Get italic status of text in a specific slide and shape.

    Args:
        env: DesktopEnv instance
        config: Dict with keys: ppt_path, slide_index, shape_index

    Returns:
        bool: True if all text is italic, False otherwise
    """
    ppt_path = config['ppt_path']
    slide_index = int(config['slide_index'])
    shape_index = int(config['shape_index'])
    local_path = get_vm_file(env, {'path': ppt_path, 'dest': os.path.basename(ppt_path)})
    prs = Presentation(local_path)
    slide = prs.slides[slide_index]
    shape = slide.shapes[shape_index]
    if not hasattr(shape, 'text_frame'):
        return False
    for paragraph in shape.text_frame.paragraphs:
        for run in paragraph.runs:
            if not run.font.italic:
                return False
    return True

def get_pptx_fonts__4525cb8d0a211ea4343ee095274a9830(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract all fonts used in a PowerPoint presentation.
    
    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the PPTX file on VM
        
    Returns:
        Dict containing fonts used per slide and overall statistics
    """
    try:
        from pptx import Presentation
    except ImportError:
        return {'error': 'python-pptx library not available'}
    file_path = config.get('path', '')
    if not file_path:
        return {'error': 'No file path specified'}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'error': f'Could not retrieve file from VM: {file_path}'}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        result = {'total_slides': len(prs.slides), 'slides': [], 'all_fonts': set()}
        for (slide_idx, slide) in enumerate(prs.slides, 1):
            slide_fonts = set()
            text_runs = 0
            for shape in slide.shapes:
                if hasattr(shape, 'text_frame'):
                    for paragraph in shape.text_frame.paragraphs:
                        for run in paragraph.runs:
                            text_runs += 1
                            if run.font.name:
                                slide_fonts.add(run.font.name)
                                result['all_fonts'].add(run.font.name)
            result['slides'].append({'slide_number': slide_idx, 'fonts': list(slide_fonts), 'text_runs': text_runs})
        result['all_fonts'] = list(result['all_fonts'])
        return result
    except Exception as e:
        return {'error': f'Error processing PowerPoint file: {str(e)}'}
    finally:
        try:
            os.unlink(tmp_path)
        except:
            pass

def get_slide_subtitle_bold__4b8ed709(env, config):
    """Get whether the subtitle (second text shape) on a specific slide is bold.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'ppt_path', 'slide_index'

    Returns:
        Boolean: True if subtitle is bold, False otherwise, None if not found
    """
    ppt_path = config.get('ppt_path', '/home/user/Desktop/71_6.pptx')
    slide_index = int(config.get('slide_index', 1))
    local_path = get_vm_file(env, {'path': ppt_path, 'dest': 'temp_71_6.pptx'})
    prs = Presentation(local_path)
    if slide_index >= len(prs.slides):
        return None
    slide = prs.slides[slide_index]
    text_shapes = []
    for shape in slide.shapes:
        if hasattr(shape, 'text_frame') and hasattr(shape, 'text') and shape.text:
            text_shapes.append(shape)
    if len(text_shapes) < 2:
        return None
    subtitle_shape = text_shapes[1]
