def get_pptx_multi_properties__ad47b7e2(env, config):
    """Get multiple properties from multiple slides.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with parameters:
            - ppt_file_path: Path to PPTX file on VM
            - checks: List of dicts with slide_index and property type

    Returns:
        dict: Results for each check
    """
    ppt_file_path = config['ppt_file_path']
    checks = config['checks']
    ppt_file_localhost_path = get_vm_file(env, {'path': ppt_file_path, 'dest': os.path.split(ppt_file_path)[-1]})
    prs = Presentation(ppt_file_localhost_path)
    results = {}
    for (idx, check) in enumerate(checks):
        slide_index = check['slide_index']
        prop_type = check['type']
        if slide_index < 0 or slide_index >= len(prs.slides):
            results[idx] = None
            continue
        slide = prs.slides[slide_index]
        if prop_type == 'title':
            if slide.shapes.title:
                results[idx] = slide.shapes.title.text.strip()
            else:
                results[idx] = ''
        elif prop_type == 'bg_color':
            fill = slide.background.fill
            if fill.type == 1:
                results[idx] = fill.fore_color.rgb
            elif fill.type == 5:
                master_fill = slide.slide_layout.slide_master.background.fill
                if master_fill.type == 1:
                    results[idx] = master_fill.fore_color.rgb
                else:
                    results[idx] = None
            else:
                results[idx] = None
        elif prop_type == 'notes':
            notes_slide = slide.notes_slide
            if notes_slide:
                results[idx] = notes_slide.notes_text_frame.text.strip()
            else:
                results[idx] = ''
    return results

def get_slide_subtitle_color__cd16e52d7de9c2b9fe4560c7bf6aa3eb(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract subtitle text color from a specific slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'slide_index'

    Returns:
        Dict with subtitle color info (RGB tuple or None if no subtitle/color)
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'has_color': False, 'color': None}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide_index = config.get('slide_index', 0)
        if slide_index >= len(prs.slides):
            return {'has_color': False, 'color': None}
        slide = prs.slides[slide_index]
        text_shapes = []
        for shape in slide.shapes:
            if hasattr(shape, 'text') and shape.text.strip():
                text_shapes.append((shape.top, shape))
        text_shapes.sort()
        if len(text_shapes) < 2:
            return {'has_color': False, 'color': None}
        subtitle_shape = text_shapes[1][1]
        for paragraph in subtitle_shape.text_frame.paragraphs:
            for run in paragraph.runs:
                if run.font.color and run.font.color.type == 1:
                    rgb = run.font.color.rgb
                    return {'has_color': True, 'color': (rgb[0], rgb[1], rgb[2])}
        return {'has_color': False, 'color': None}
    finally:
        os.unlink(tmp_path)

