def get_slide_uppercase_italic_status__1b870fcaf133c6d0ae90b1f383ccdb32(env, config: Dict):
    """Extract italic formatting status from quote text on a specific slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM file path) and 'slide_index' (0-based)

    Returns:
        Dict with 'total_uppercase_runs' (int) and 'italic_uppercase_runs' (int)
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'total_uppercase_runs': 0, 'italic_uppercase_runs': 0}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide_index = config.get('slide_index', 0)
        if slide_index >= len(prs.slides):
            return {'total_uppercase_runs': 0, 'italic_uppercase_runs': 0}
        slide = prs.slides[slide_index]
        total_quote_runs = 0
        italic_quote_runs = 0
        quote_keywords = ['WRITE AN ORIGINAL', 'INSPIRING QUOTE', 'STATEMENT OR INSPIRING']
        for shape in slide.shapes:
            if hasattr(shape, 'text_frame'):
                for paragraph in shape.text_frame.paragraphs:
                    for run in paragraph.runs:
                        text = run.text.strip()
                        if not text:
                            continue
                        text_upper = text.upper()
                        is_quote_text = any((keyword in text_upper for keyword in quote_keywords))
                        if is_quote_text:
                            total_quote_runs += 1
                            if run.font.italic:
                                italic_quote_runs += 1
        return {'total_uppercase_runs': total_quote_runs, 'italic_uppercase_runs': italic_quote_runs}
    finally:
        os.unlink(tmp_path)

