def get_pptx_table_dims__f92e5dab(env, config: dict):
    """Extract table dimensions from a specific slide in a PPTX file.
    
    Args:
        env: DesktopEnv instance
        config: Configuration dict with parameters:
            - ppt_file_path: Path to PPTX file on VM
            - slide_index: Index of slide to check (0-based)
            - dest: Local destination filename
            
    Returns:
        dict: {"rows": int, "cols": int, "has_table": bool}
    """
    ppt_file_path = config['ppt_file_path']
    slide_index = int(config['slide_index'])
    dest = config.get('dest', os.path.basename(ppt_file_path))
    ppt_file_localhost_path = get_vm_file(env, {'path': ppt_file_path, 'dest': dest})
    prs = Presentation(ppt_file_localhost_path)
    if slide_index >= len(prs.slides):
        return {'has_table': False, 'rows': 0, 'cols': 0}
    slide = prs.slides[slide_index]
    from pptx.enum.shapes import MSO_SHAPE_TYPE
    for shape in slide.shapes:
        if shape.shape_type == MSO_SHAPE_TYPE.TABLE:
            table = shape.table
            return {'has_table': True, 'rows': len(table.rows), 'cols': len(table.columns)}
    return {'has_table': False, 'rows': 0, 'cols': 0}

def get_pptx_para_level__473e9b3a8e2865e7a0acc65789c0d20a(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract paragraph level information from a PowerPoint file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - path: VM file path (e.g., '/home/user/Desktop/file.pptx')
            - slide_index: 0-based slide index
            - shape_index: 0-based shape index within the slide
            - text_search: Text to search for within the shape's paragraphs

    Returns:
        Dict with paragraph levels for matching text
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide_index = config.get('slide_index', 0)
        shape_index = config.get('shape_index', 0)
        text_search = config.get('text_search', '')
        if slide_index >= len(prs.slides):
            return {}
        slide = prs.slides[slide_index]
        shapes = [s for s in slide.shapes if hasattr(s, 'text_frame')]
        if shape_index >= len(shapes):
            return {}
        shape = shapes[shape_index]
        result = {}
        for para in shape.text_frame.paragraphs:
            if text_search.lower() in para.text.lower():
                result[para.text.strip()] = para.level
        return result
    finally:
        os.unlink(tmp_path)

def get_pptx_title_fonts__9e62713c(env, config):
    """Extract fonts used in title placeholders across all slides.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'ppt_file_path' key

    Returns:
        set: Set of font names used in title placeholders
    """
    ppt_file_path = config['ppt_file_path']
    ppt_file_localhost_path = get_vm_file(env, {'path': ppt_file_path, 'dest': os.path.split(ppt_file_path)[-1]})
    prs = Presentation(ppt_file_localhost_path)
    title_fonts = set()
    for slide in prs.slides:
        for shape in slide.shapes:
            if hasattr(shape, 'text_frame') and shape.is_placeholder:
                if hasattr(shape, 'placeholder_format'):
                    if shape.placeholder_format.type in [1, 3]:
                        for paragraph in shape.text_frame.paragraphs:
                            for run in paragraph.runs:
                                if run.font.name:
                                    title_fonts.add(run.font.name)
    return title_fonts

