def get_ppt_slide_title__34ac30131d2bc2e5d4870cf45c6bbadc(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract slide title text and color from PowerPoint file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'slide_index' keys

    Returns:
        Dict with 'text', 'color_rgb', 'font_name', 'font_size', 'bold' keys
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide_index = config.get('slide_index', 0)
        if slide_index >= len(prs.slides):
            return {}
        slide = prs.slides[slide_index]
        title_shape = None
        for shape in slide.shapes:
            if shape.is_placeholder:
                try:
                    if shape.placeholder_format.type == PP_PLACEHOLDER.TITLE:
                        title_shape = shape
                        break
                except:
                    pass
        if title_shape is None:
            return {'error': 'no_title_placeholder'}
        if not hasattr(title_shape, 'text_frame') or not title_shape.text:
            return {'text': '', 'color_rgb': None}
        text = title_shape.text.strip()
        color_rgb = None
        font_name = None
        font_size = None
        bold = None
        if title_shape.text_frame.paragraphs:
            first_para = title_shape.text_frame.paragraphs[0]
            if first_para.runs:
                first_run = first_para.runs[0]
                if hasattr(first_run.font, 'color') and first_run.font.color:
                    if hasattr(first_run.font.color, 'rgb') and first_run.font.color.rgb:
                        rgb = first_run.font.color.rgb
                        color_rgb = (rgb[0], rgb[1], rgb[2])
                font_name = first_run.font.name
                font_size = first_run.font.size
                bold = first_run.font.bold
        return {'text': text, 'color_rgb': color_rgb, 'font_name': font_name, 'font_size': font_size, 'bold': bold}
    finally:
        os.unlink(tmp_path)

def get_pptx_image_info__607877f20f4f09366563ea8baf7aa560(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract image information from a specific slide in a PPTX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - path: VM path to the PPTX file
            - slide_index: 0-based slide index (optional, default: 0)

    Returns:
        Dict with image information:
        {
            "image_count": int,
            "images": [
                {
                    "width_cm": float,
                    "height_cm": float,
                    "left_cm": float,
                    "top_cm": float
                },
                ...
            ]
        }
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'image_count': 0, 'images': []}
