        for shape in slide.shapes:
            if shape.shape_type == 13:
                images.append({'width_cm': round(shape.width / Cm(1), 2), 'height_cm': round(shape.height / Cm(1), 2), 'left_cm': round(shape.left / Cm(1), 2), 'top_cm': round(shape.top / Cm(1), 2)})
        return {'image_count': len(images), 'images': images}
