def get_ppt_slide_count__1a123de6(env, config):
    """Get the number of slides and verify content of remaining slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the PPTX file

    Returns:
        dict: Dictionary with 'count' (number of slides) and 'has_content_slide' (bool indicating if 'Sustainable Energy' title exists)
    """
    file_path = config.get('path', '')
    try:
        prs = Presentation(file_path)
        slide_count = len(prs.slides)
        has_content_slide = False
        for slide in prs.slides:
            for shape in slide.shapes:
                if hasattr(shape, 'text') and 'Sustainable Energy' in shape.text:
                    has_content_slide = True
                    break
            if has_content_slide:
                break
        return {'count': slide_count, 'has_content_slide': has_content_slide}
    except Exception as e:
        print(f'Error reading PPTX file: {e}')
        return {'count': -1, 'has_content_slide': False}

def get_pptx_slide_title__b89020eb4704d83938bd56dc8b423922(env, config: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """
    Extract title text and alignment from a specific slide in a PowerPoint file.
    
    Args:
        env: Desktop environment instance
        config: Configuration dict with 'path' (VM file path) and 'slide_idx' (0-indexed slide number)
        
    Returns:
        Dict with 'text' and 'alignment' keys, or None if no title found
    """
    file_path = config.get('path')
    slide_idx = config.get('slide_idx', 0)
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return None
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        if slide_idx >= len(prs.slides):
            return None
        slide = prs.slides[slide_idx]
        for shape in slide.shapes:
            if hasattr(shape, 'text') and hasattr(shape, 'text_frame'):
                text = shape.text.strip()
                if text:
                    alignment = None
                    if shape.text_frame.paragraphs:
                        para = shape.text_frame.paragraphs[0]
                        alignment = para.alignment
                    align_str = 'NONE'
                    if alignment is not None:
                        from pptx.enum.text import PP_ALIGN
                        if alignment == PP_ALIGN.LEFT or alignment == 1:
                            align_str = 'LEFT'
                        elif alignment == PP_ALIGN.CENTER or alignment == 2:
                            align_str = 'CENTER'
                        elif alignment == PP_ALIGN.RIGHT or alignment == 3:
                            align_str = 'RIGHT'
                        elif alignment == PP_ALIGN.JUSTIFY or alignment == 4:
                            align_str = 'JUSTIFY'
                    else:
                        align_str = 'LEFT'
                    return {'text': text, 'alignment': align_str}
        return None
    finally:
        os.unlink(tmp_path)

def get_pptx_title_bold_italic__400d220eb9213bc0d85a8596995779ed(env, config):
    """Extract bold and italic properties of titles in specified slides.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with keys:
            - path: VM file path (e.g., "/home/user/Desktop/4_1.pptx")
            - slides: List of slide indices (0-based) to check

    Returns:
        dict: Mapping of slide_index -> {"bold": bool, "italic": bool} for each title
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        result = {}
        for slide_idx in config.get('slides', []):
            if slide_idx >= len(prs.slides):
                continue
            slide = prs.slides[slide_idx]
            title_shape = None
            if slide.shapes.title:
                title_shape = slide.shapes.title
            else:
                for shape in slide.shapes:
                    if hasattr(shape, 'text') and shape.text.strip():
                        title_shape = shape
                        break
            if title_shape and hasattr(title_shape, 'text_frame'):
                all_bold = True
                all_italic = True
                has_text = False
                for para in title_shape.text_frame.paragraphs:
                    for run in para.runs:
                        if run.text.strip():
                            has_text = True
                            if not run.font.bold:
                                all_bold = False
                            if not run.font.italic:
                                all_italic = False
                if has_text:
                    result[slide_idx] = {'bold': all_bold, 'italic': all_italic}
        return result
    finally:
        os.unlink(tmp_path)

