def get_pptx_title_alignment__90cf389e8462be4d838ef12921011390(env, config):
    """Extract title text alignment from specified slides.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'slide_indices' (1-based)

    Returns:
        dict: Mapping of slide_index to alignment type
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide_indices = config.get('slide_indices', [])
        result = {}
        for slide_idx in slide_indices:
            if slide_idx < 1 or slide_idx > len(prs.slides):
                continue
            slide = prs.slides[slide_idx - 1]
            title_shape = None
            for shape in slide.shapes:
                if hasattr(shape, 'text_frame') and shape.text.strip():
                    title_shape = shape
                    break
            if title_shape and hasattr(title_shape, 'text_frame'):
                for paragraph in title_shape.text_frame.paragraphs:
                    if paragraph.text.strip():
                        alignment = paragraph.alignment
                        if alignment == PP_ALIGN.CENTER:
                            result[slide_idx] = 'center'
                        elif alignment == PP_ALIGN.LEFT:
                            result[slide_idx] = 'left'
                        elif alignment == PP_ALIGN.RIGHT:
                            result[slide_idx] = 'right'
                        elif alignment == PP_ALIGN.JUSTIFY:
                            result[slide_idx] = 'justify'
                        else:
                            result[slide_idx] = 'unknown'
                        break
        return result
    finally:
        os.unlink(tmp_path)

def get_ppt_slide_numbers__801e16c7(env, config: dict):
    """Check if slides have numbers in bottom-right corner.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with ppt_file_path

    Returns:
        dict: {
            'slide_number_info': list of dicts with 'has_number' and 'position' for each slide
        }
    """
    ppt_file_path = config['ppt_file_path']
    ppt_localhost_path = get_vm_file(env, {'path': ppt_file_path, 'dest': os.path.basename(ppt_file_path)})
    prs = Presentation(ppt_localhost_path)
    slide_number_info = []
    slide_width = prs.slide_width
    slide_height = prs.slide_height
    for slide in prs.slides:
        has_number = False
        in_bottom_right = False
        for shape in slide.shapes:
            if hasattr(shape, 'text') and shape.text.strip().isdigit():
                has_number = True
                if hasattr(shape, 'left') and hasattr(shape, 'top'):
                    if shape.top > slide_height * 0.8 and shape.left > slide_width * 0.5:
                        in_bottom_right = True
                        break
        slide_number_info.append({'has_number': has_number, 'in_bottom_right': in_bottom_right})
    return {'slide_number_info': slide_number_info}

def get_pptx_paragraph_level__9bbb59cf(env, config):
    """
    Get the indentation levels of specified paragraphs in a specific shape of a slide.

    Args:
        env: Environment object
        config: Dict containing:
            - path: Path to the PPTX file on VM
            - dest: Destination filename for local copy
            - slide_index: 0-indexed slide number
            - shape_index: 0-indexed shape number
            - paragraph_indices: List of 0-indexed paragraph numbers

    Returns:
        dict: Dictionary containing paragraph levels, e.g., {0: 1, 1: 1} for paragraphs at indices 0 and 1 both at level 1
    """
    pptx_file = get_vm_file(env, {'path': config['path'], 'dest': config['dest']})
    prs = Presentation(pptx_file)
    slide_index = config['slide_index']
    if slide_index >= len(prs.slides):
        return {}
    slide = prs.slides[slide_index]
    shape_index = config['shape_index']
    if shape_index >= len(slide.shapes):
        return {}
    shape = slide.shapes[shape_index]
    if not hasattr(shape, 'text_frame'):
        return {}
    paragraph_indices = config.get('paragraph_indices', [])
    result = {}
    for para_idx in paragraph_indices:
        if para_idx < len(shape.text_frame.paragraphs):
            paragraph = shape.text_frame.paragraphs[para_idx]
            result[para_idx] = paragraph.level
    return result

def get_pptx_state__8c2d804d(env, config):
    """Get PowerPoint slide state for variation 8.
    
    Args:
        env: DesktopEnv instance
        config: Configuration dict with path to PPTX file
        
    Returns:
        dict: Slide state including background color, notes, title formatting
    """
    from desktop_env.evaluators.getters.file import get_vm_file
    import os
    pptx_path = config.get('path', '/home/user/Desktop/186_3.pptx')
