    fill = slide.background.fill
    if fill.type == 1:
        bg_color = str(fill.fore_color.rgb)
    notes = ''
    if slide.has_notes_slide:
        notes = slide.notes_slide.notes_text_frame.text.strip()
    title_shape = None
