def get_pptx_text_color__0b0076c6533639910b3542ade609d2df(env, config: Dict):
    """Extract text color from shapes on a specific slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (file path), 'slide_index' (0-based),
                and optional 'text_contains' to filter specific text

    Returns:
        dict: Dictionary containing color info for text shapes
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide_index = int(config.get('slide_index', 0))
        if slide_index >= len(prs.slides):
            return {}
        slide = prs.slides[slide_index]
        text_filter = config.get('text_contains', None)
        result = {'shapes_color': []}
        for (idx, shape) in enumerate(slide.shapes):
            if hasattr(shape, 'text_frame'):
                shape_text = shape.text if hasattr(shape, 'text') else ''
                if text_filter and text_filter not in shape_text:
                    continue
                shape_info = {'shape_index': idx, 'text': shape_text[:50], 'colors': []}
                for para in shape.text_frame.paragraphs:
                    for run in para.runs:
                        if hasattr(run.font.color, 'rgb'):
                            rgb = run.font.color.rgb
                            shape_info['colors'].append({'rgb': (rgb[0], rgb[1], rgb[2]), 'text': run.text})
                result['shapes_color'].append(shape_info)
        return result
    finally:
        os.unlink(tmp_path)

def get_slide_title_bold__9e749c72(env, config):
    """Extract title text and check if it's bold.

    Args:
        env: DesktopEnv instance
        config: dict with 'ppt_file_path' and 'slide_index'

    Returns:
        dict with 'text' and 'is_bold' keys
    """
    ppt_file_path = config['ppt_file_path']
    slide_index = int(config.get('slide_index', 0))
    local_path = get_vm_file(env, {'path': ppt_file_path, 'dest': ppt_file_path.split('/')[-1]})
    prs = Presentation(local_path)
    if slide_index >= len(prs.slides):
        return {'text': '', 'is_bold': False}
    slide = prs.slides[slide_index]
    for shape in slide.shapes:
        if hasattr(shape, 'text_frame') and shape.is_placeholder:
            if shape.placeholder_format.idx == 0:
                text = shape.text.strip()
                is_bold = False
                if shape.text_frame.paragraphs:
                    for para in shape.text_frame.paragraphs:
                        if para.runs:
                            is_bold = para.runs[0].font.bold == True
                            break
                return {'text': text, 'is_bold': is_bold}
    return {'text': '', 'is_bold': False}

def get_slides_with_notes_from_docx__f84e3848c788254387c79a0944166381(env, config: Dict):
    """Extract list of slide numbers that have notes from a Word document.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the docx file on VM

    Returns:
        List of integers representing slide numbers that have notes
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return []
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        slide_numbers = []
        for para in doc.paragraphs:
            text = para.text.strip()
            if not text:
                continue
            match = re.match('^\\s*(\\d+)\\s*$', text)
            if match:
                num = int(match.group(1))
                if 1 <= num <= 100 and num not in slide_numbers:
                    slide_numbers.append(num)
        slide_numbers.sort()
        return slide_numbers
    finally:
        os.unlink(tmp_path)

