def get_pptx_slide3_title_italic_size__59c60c56(env, config):
    """Get italic status and font size of slide 3 title.

    Checks ALL runs in ALL paragraphs of the title shape to ensure
    the entire title has consistent formatting.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with pptx_path parameter

    Returns:
        dict: {"italic": bool, "font_size": float or None}
              italic is True only if ALL runs are italic
              font_size is the size if ALL runs have the same size, None otherwise
    """
    pptx_path = config.get('pptx_path', '/home/user/Desktop/39_2.pptx')
    local_path = get_vm_file(env, {'path': pptx_path, 'dest': os.path.basename(pptx_path)})
    prs = Presentation(local_path)
    if len(prs.slides) < 3:
        return {'italic': False, 'font_size': None}
    slide = prs.slides[2]
    title_shape = None
    for shape in slide.shapes:
        if hasattr(shape, 'is_placeholder') and shape.is_placeholder:
            if hasattr(shape, 'placeholder_format'):
                if shape.placeholder_format.type == 1:
                    title_shape = shape
                    break
        elif not title_shape and hasattr(shape, 'text') and shape.text.strip():
            if hasattr(shape, 'text_frame') and shape.text_frame.paragraphs:
                if not title_shape:
                    title_shape = shape
    if not title_shape or not hasattr(title_shape, 'text_frame'):
        return {'italic': False, 'font_size': None}
    all_runs = []
    for para in title_shape.text_frame.paragraphs:
        all_runs.extend(para.runs)
    if not all_runs:
        return {'italic': False, 'font_size': None}
    all_italic = True
    font_sizes = []
    for run in all_runs:
        run_italic = run.font.italic if run.font.italic is not None else False
        if not run_italic:
            all_italic = False
        if run.font.size:
            font_sizes.append(run.font.size.pt)
        else:
            font_sizes.append(None)
    valid_font_sizes = [fs for fs in font_sizes if fs is not None]
    if valid_font_sizes and all((abs(fs - valid_font_sizes[0]) <= 0.5 for fs in valid_font_sizes)):
        final_font_size = valid_font_sizes[0]
    else:
        final_font_size = None
    return {'italic': all_italic, 'font_size': final_font_size}

def get_pptx_font_name__8deb6853(env, config):
    """Get font name of text in a specific slide and shape.

    Args:
        env: DesktopEnv instance
        config: Dict with keys: ppt_path, slide_index, shape_index

    Returns:
        str: Font name if all text has same font, None otherwise
    """
    ppt_path = config['ppt_path']
    slide_index = int(config['slide_index'])
    shape_index = int(config['shape_index'])
    local_path = get_vm_file(env, {'path': ppt_path, 'dest': os.path.basename(ppt_path)})
    prs = Presentation(local_path)
    slide = prs.slides[slide_index]
    shape = slide.shapes[shape_index]
    if not hasattr(shape, 'text_frame'):
        return None
    first_font = None
    for paragraph in shape.text_frame.paragraphs:
        for run in paragraph.runs:
            if run.font.name:
                if first_font is None:
                    first_font = run.font.name
                elif run.font.name != first_font:
                    return None
    return first_font

