def get_pptx_text_underline_status__b8ddeb45(env, config):
    """Extract underline status of text in specific shapes.

    Args:
        env: DesktopEnv instance
        config: Dict with keys:
            - pptx_path: Path to PPTX file on VM
            - slide_index: 0-based slide index
            - shape_indices: List of shape indices to check

    Returns:
        List of booleans indicating if each shape's text is underlined
    """
    pptx_path = config['pptx_path']
    slide_index = config['slide_index']
    shape_indices = config['shape_indices']
    local_file = get_vm_file(env, {'path': pptx_path, 'dest': os.path.basename(pptx_path)})
    prs = Presentation(local_file)
    slide = prs.slides[slide_index]
    underline_statuses = []
    for shape_idx in shape_indices:
        shape = slide.shapes[shape_idx]
        if hasattr(shape, 'text_frame'):
            is_underlined = False
            for paragraph in shape.text_frame.paragraphs:
                for run in paragraph.runs:
                    if run.font.underline:
                        is_underlined = True
                        break
                if is_underlined:
                    break
            underline_statuses.append(is_underlined)
        else:
            underline_statuses.append(False)
    return underline_statuses

def get_pptx_para_props__7e58fdf5(env, config: dict):
    """
    Extract paragraph level and bullet status for ALL occurrences of specific text on a slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - path: Path to PPTX file on VM
            - dest: Destination filename
            - slide_idx: Slide index (0-based)
            - target_text: Text to find

    Returns:
        list of dicts, each with 'level' (int) and 'has_bullet' (bool) for each occurrence
        Returns empty list if no matches found
    """
    file_content = env.controller.get_file(config['path'])
    if not file_content:
        return []
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_content)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide_idx = config.get('slide_idx', 0)
        target_text = config.get('target_text', '')
        if slide_idx >= len(prs.slides):
            return []
        slide = prs.slides[slide_idx]
        occurrences = []
        for shape in slide.shapes:
            if hasattr(shape, 'text_frame'):
                for para in shape.text_frame.paragraphs:
                    if para.text.strip() == target_text.strip():
                        level = para.level
                        has_bu_none = para._element.find('.//{http://schemas.openxmlformats.org/drawingml/2006/main}buNone')
                        has_bullet = has_bu_none is None
                        occurrences.append({'level': level, 'has_bullet': has_bullet})
        return occurrences
    finally:
        os.unlink(tmp_path)

def get_pptx_slide_title__89f306f8(env, config):
    """Get the title text from a specific slide.

    Args:
        env: DesktopEnv instance
        config: Dict with 'path', 'slide_index'

    Returns:
        str: The title text or None
    """
    path = config['path']
    slide_index = config['slide_index']
    local_path = get_vm_file(env, {'path': path, 'dest': os.path.basename(path)})
    prs = Presentation(local_path)
    slide = prs.slides[slide_index]
    if hasattr(slide.shapes, 'title') and slide.shapes.title is not None:
        if hasattr(slide.shapes.title, 'text'):
            return slide.shapes.title.text.strip() if slide.shapes.title.text.strip() else None
    for shape in slide.shapes:
        if shape.is_placeholder:
            placeholder = shape.placeholder_format
            if placeholder.type == PP_PLACEHOLDER.TITLE:
                if hasattr(shape, 'text') and shape.text.strip():
                    return shape.text.strip()
    return None

def get_impress_slide_count__360e07ae(env, config):
    """
    Get the number of slides and image information from a PPTX presentation.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key for the PPTX file path on VM

    Returns:
        dict: {
            'slide_count': int - Number of slides in the presentation,
            'slides_with_images': list - Indices of slides containing images,
            'image_count_per_slide': dict - Mapping of slide index to image count
        }
    """
    from desktop_env.evaluators.getters.file import get_vm_file
    import os
    vm_path = config.get('path', '/home/user/Desktop/4.3-Template_4.29.2016.pptx')
    local_path = get_vm_file(env, {'path': vm_path, 'dest': os.path.basename(vm_path)})
    prs = Presentation(local_path)
    slides_with_images = []
    image_count_per_slide = {}
    for (idx, slide) in enumerate(prs.slides):
        image_count = 0
        for shape in slide.shapes:
            if shape.shape_type == MSO_SHAPE_TYPE.PICTURE:
                image_count += 1
        if image_count > 0:
            slides_with_images.append(idx)
        image_count_per_slide[idx] = image_count
    return {'slide_count': len(prs.slides), 'slides_with_images': slides_with_images, 'image_count_per_slide': image_count_per_slide}

