def get_pptx_font_size__1dbd34ebfc900aee6c2fe73499a2577a(env, config: Dict):
    """Extract font size from a specific shape in PowerPoint.

    Args:
        env: DesktopEnv instance
        config: Dict with 'path', 'slide_index' (0-based), 'shape_index' (0-based)

    Returns:
        Dict with text and font size in points: {'text': str, 'font_size_pt': float}
    """
    ppt_path = config['path']
    slide_idx = int(config.get('slide_index', 0))
    shape_idx = int(config.get('shape_index', 0))
    file_bytes = env.controller.get_file(ppt_path)
    if not file_bytes:
        return {'text': '', 'font_size_pt': 0}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        if slide_idx >= len(prs.slides):
            return {'text': '', 'font_size_pt': 0}
        slide = prs.slides[slide_idx]
        if shape_idx >= len(slide.shapes):
            return {'text': '', 'font_size_pt': 0}
        shape = slide.shapes[shape_idx]
        if not hasattr(shape, 'text_frame'):
            return {'text': '', 'font_size_pt': 0}
        text = shape.text.strip()
        font_size_pt = 0
        if shape.text_frame.paragraphs:
            para = shape.text_frame.paragraphs[0]
            if para.runs:
                run = para.runs[0]
                if run.font.size:
                    font_size_pt = run.font.size.pt
        return {'text': text, 'font_size_pt': font_size_pt}
    finally:
        os.unlink(tmp_path)

def get_ppt_slide_text_content__a6df6f94(env, config):
    """Get all text content from a specific slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (PPTX file) and 'slide_index' keys

    Returns:
        list: List of text strings found on the slide
    """
    file_path = config.get('path', '')
    slide_index = config.get('slide_index', 0)
    try:
        prs = Presentation(file_path)
        if slide_index < 0 or slide_index >= len(prs.slides):
            return []
        slide = prs.slides[slide_index]
        texts = []
        for shape in slide.shapes:
            if hasattr(shape, 'text') and shape.text.strip():
                texts.append(shape.text.strip())
        return texts
    except Exception as e:
        print(f'Error reading PPTX file: {e}')
        return []

def get_pptx_last_slide_text__fc32c651(env, config):
    """Get text from the last slide of a PPTX file and return dict with text and slide count"""
    from desktop_env.evaluators.getters.file import get_vm_file
