def get_pptx_slide_title__1be8dc92(env, config):
    """Get title text and color from a specific slide in PowerPoint file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with parameters:
            - path: Path to PPTX file on VM
            - slide_index: Index of slide (0-based)
            - dest: Local destination filename

    Returns:
        dict: {"text": str, "color": tuple(r, g, b)} or {"text": "", "color": None} if no title
    """
    pptx_path = config.get('path', '/home/user/Desktop/189_4.pptx')
    slide_index = config.get('slide_index', 1)
    dest = config.get('dest', '189_4.pptx')
    local_path = get_vm_file(env, {'path': pptx_path, 'dest': dest})
    prs = Presentation(local_path)
    if slide_index >= len(prs.slides):
        return {'text': '', 'color': None}
    slide = prs.slides[slide_index]
    for shape in slide.shapes:
        if hasattr(shape, 'text') and hasattr(shape, 'text_frame'):
            text = shape.text.strip()
            if text:
                if shape.text_frame.paragraphs:
                    para = shape.text_frame.paragraphs[0]
                    if para.runs:
                        run = para.runs[0]
                        if hasattr(run.font.color, 'rgb'):
                            rgb = run.font.color.rgb
                            return {'text': text, 'color': (rgb[0], rgb[1], rgb[2])}
                        else:
                            return {'text': text, 'color': None}
                return {'text': text, 'color': None}
    return {'text': '', 'color': None}

