def get_pptx_structure__4d68fae1(env, config):
    """Extract presentation structure including slide count and titles.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: Structure info with slide_count, titles, and first_slide details
    """
    filepath = config.get('path', '')
    try:
        prs = Presentation(filepath)
        titles = []
        for slide in prs.slides:
            title = ''
            if slide.shapes.title:
                title = slide.shapes.title.text.strip()
            titles.append(title)
        first_slide_info = {}
        if len(prs.slides) > 0:
            first_slide = prs.slides[0]
            first_slide_info['title'] = ''
            first_slide_info['subtitle'] = ''
            if first_slide.shapes.title:
                first_slide_info['title'] = first_slide.shapes.title.text.strip()
            for shape in first_slide.shapes:
                if hasattr(shape, 'placeholder_format') and shape != first_slide.shapes.title:
                    try:
                        if shape.placeholder_format.idx == 1:
                            if hasattr(shape, 'text'):
                                text = shape.text.strip()
                                if text:
                                    first_slide_info['subtitle'] = text
                                    break
                    except:
                        pass
            if not first_slide_info['subtitle']:
                for shape in first_slide.shapes:
                    if hasattr(shape, 'text') and shape != first_slide.shapes.title:
                        if hasattr(shape, 'placeholder_format'):
                            text = shape.text.strip()
                            if text:
                                first_slide_info['subtitle'] = text
                                break
        return {'slide_count': len(prs.slides), 'titles': titles, 'first_slide': first_slide_info}
    except Exception as e:
        return {'slide_count': 0, 'titles': [], 'first_slide': {}, 'error': str(e)}

def get_pptx_textbox_fonts__bfe611cbb854876006c0fbdeafab8682(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract font sizes from specific textboxes on a slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - path: VM path to the PPTX file
            - slide_index: 0-based slide index
            - textbox_indices: List of 0-based shape indices to check

    Returns:
        Dict mapping textbox_index to font_size (in points)
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide_index = config.get('slide_index', 0)
        textbox_indices = config.get('textbox_indices', [])
        if slide_index >= len(prs.slides):
            return {}
        slide = prs.slides[slide_index]
        result = {}
        for tb_idx in textbox_indices:
            if tb_idx < len(slide.shapes):
                shape = slide.shapes[tb_idx]
                if hasattr(shape, 'text_frame'):
                    for paragraph in shape.text_frame.paragraphs:
                        for run in paragraph.runs:
                            if run.font.size:
                                result[str(tb_idx)] = run.font.size.pt
                                break
                        if str(tb_idx) in result:
                            break
        return result
    finally:
        os.unlink(tmp_path)

def get_pptx_slide_font_size__1452cc07b597787abfe241ee1d6bb8ed(env, config: Dict):
    """Extract font sizes from text in specific slides.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'slides' keys

    Returns:
        Dict mapping slide indices to list of average font sizes for each textbox
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        result = {}
        slides_to_check = config.get('slides', [])
        for slide_idx in slides_to_check:
            if slide_idx >= len(prs.slides):
                continue
            slide = prs.slides[slide_idx]
            slide_textboxes = []
            for shape in slide.shapes:
                if hasattr(shape, 'text_frame'):
                    if not shape.text_frame.text.strip():
                        continue
                    font_sizes = []
                    for paragraph in shape.text_frame.paragraphs:
                        for run in paragraph.runs:
                            if run.font.size is not None:
                                font_sizes.append(run.font.size.pt)
                    if font_sizes:
                        avg_size = sum(font_sizes) / len(font_sizes)
                        slide_textboxes.append(avg_size)
                    else:
                        slide_textboxes.append(None)
            result[slide_idx] = slide_textboxes
        return result
    finally:
        os.unlink(tmp_path)

