def get_pptx_slide1_title_alignment__cb33ca9a(env, config):
    """Get text alignment of slide 1 title.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with pptx_path parameter

    Returns:
        str: Alignment name (LEFT, CENTER, RIGHT, JUSTIFY) or None
    """
    pptx_path = config.get('pptx_path', '/home/user/Desktop/39_2.pptx')
    local_path = get_vm_file(env, {'path': pptx_path, 'dest': os.path.basename(pptx_path)})
    prs = Presentation(local_path)
    if len(prs.slides) < 1:
        return None
    slide = prs.slides[0]
    for shape in slide.shapes:
        if hasattr(shape, 'is_placeholder') and shape.is_placeholder:
            if hasattr(shape, 'placeholder_format'):
                placeholder_type = shape.placeholder_format.type
                if placeholder_type in [1, 3, 13]:
                    if hasattr(shape, 'text_frame') and shape.text_frame:
                        for para in shape.text_frame.paragraphs:
                            align = para.alignment
                            if align is None:
                                return 'LEFT'
                            return align.name if hasattr(align, 'name') else str(align)
        elif hasattr(shape, 'text_frame') and shape.text_frame and (len(shape.text_frame.paragraphs) > 0):
            if shape.text_frame.text.strip():
                for para in shape.text_frame.paragraphs:
                    if para.text.strip():
                        align = para.alignment
                        if align is None:
                            return 'LEFT'
                        return align.name if hasattr(align, 'name') else str(align)
                break
    return None

def get_ppt_title_properties__a99a51a5(env, config: dict):
    """Extract title formatting properties from specified slides.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - ppt_file_path: Path to PowerPoint file on VM
            - target_slides: List of slide indices (0-based)
            - properties: List of properties to extract (color, bold, size, italic, underline, font_name)

    Returns:
        dict: Mapping of slide_index -> {property: value}
    """
    ppt_file_path = config['ppt_file_path']
    target_slides = config['target_slides']
    properties = config.get('properties', ['color', 'bold', 'size', 'italic', 'underline', 'font_name'])
    ppt_localhost_path = get_vm_file(env, {'path': ppt_file_path, 'dest': ppt_file_path.split('/')[-1]})
    prs = Presentation(ppt_localhost_path)
    results = {}
    for slide_idx in target_slides:
        if slide_idx >= len(prs.slides):
            continue
        slide = prs.slides[slide_idx]
        title_shape = None
        max_size = 0
        for shape in slide.shapes:
            if hasattr(shape, 'text') and shape.text and hasattr(shape, 'text_frame'):
                if shape.text_frame.paragraphs:
                    para = shape.text_frame.paragraphs[0]
                    if para.runs:
                        run = para.runs[0]
                        if run.font.size:
                            size_pt = run.font.size.pt
                            if size_pt > max_size:
                                max_size = size_pt
                                title_shape = shape
        if not title_shape:
            continue
        para = title_shape.text_frame.paragraphs[0]
        run = para.runs[0]
        font = run.font
        slide_properties = {}
        if 'color' in properties:
            if font.color and hasattr(font.color, 'rgb'):
                rgb = font.color.rgb
                slide_properties['color'] = f'#{rgb[0]:02X}{rgb[1]:02X}{rgb[2]:02X}'
            else:
                slide_properties['color'] = None
        if 'bold' in properties:
            slide_properties['bold'] = bool(font.bold) if font.bold is not None else False
        if 'size' in properties:
            slide_properties['size'] = font.size.pt if font.size else None
        if 'italic' in properties:
            slide_properties['italic'] = bool(font.italic) if font.italic is not None else False
        if 'underline' in properties:
            slide_properties['underline'] = bool(font.underline) if font.underline is not None else False
        if 'font_name' in properties:
            slide_properties['font_name'] = font.name
        results[slide_idx] = slide_properties
    return results

def get_pptx_formatting__8602e6c5(env, config: dict):
    """Extract formatting state for text in specified slides.
    
    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'dest', 'slide_indices'
        
    Returns:
        dict: Formatting information for all text runs in specified slides
    """
    pptx_path = config.get('path', '/home/user/Desktop/43_1.pptx')
    dest = config.get('dest', '43_1.pptx')
    slide_indices = config.get('slide_indices', [])
    local_path = get_vm_file(env, {'path': pptx_path, 'dest': dest})
    prs = Presentation(local_path)
    formatting_data = {}
    for slide_idx in slide_indices:
        if slide_idx < 1 or slide_idx > len(prs.slides):
            continue
        slide = prs.slides[slide_idx - 1]
        for (shape_idx, shape) in enumerate(slide.shapes):
            if not hasattr(shape, 'text_frame'):
                continue
            for (para_idx, para) in enumerate(shape.text_frame.paragraphs):
                for (run_idx, run) in enumerate(para.runs):
                    key = (slide_idx, shape_idx, para_idx, run_idx)
                    formatting_data[key] = {'text': run.text, 'bold': run.font.bold, 'italic': run.font.italic, 'underline': run.font.underline, 'size': run.font.size.pt if run.font.size else None, 'color': run.font.color.rgb if hasattr(run.font.color, 'rgb') else None, 'alignment': para.alignment}
    return formatting_data

def get_pptx_all_image_heights__e84b6244c77ec262ee7d931c01a24ca3(env, config: Dict[str, Any]):
    """Get heights of all images on a specific slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM file path) and 'slide_index' (0-based)

    Returns:
        List of image heights in cm, or empty list if no images found
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return []
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide_index = int(config.get('slide_index', 0))
        if slide_index >= len(prs.slides):
            return []
        slide = prs.slides[slide_index]
        image_heights = []
        for shape in slide.shapes:
            if shape.shape_type == 13:
                height_cm = shape.height / 360000
                image_heights.append(round(height_cm, 2))
        return image_heights
    finally:
        os.unlink(tmp_path)

def get_pptx_textbox_fonts__7191179b(env, config):
    """Extract font sizes from two specific textboxes in a PowerPoint slide.
    
    Args:
        env: DesktopEnv instance
        config: Configuration dict with parameters:
            - ppt_file_path: Path to PPTX file on VM
            - slide_index: Slide index (0-based)
            - textbox1_shape_idx: First textbox shape index
            - textbox2_shape_idx: Second textbox shape index
            
    Returns:
        dict: {"textbox1_font_size": float, "textbox2_font_size": float}
    """
    ppt_file_path = config['ppt_file_path']
    slide_index = int(config['slide_index'])
    textbox1_idx = int(config['textbox1_shape_idx'])
    textbox2_idx = int(config['textbox2_shape_idx'])
    ppt_file_localhost = get_vm_file(env, {'path': ppt_file_path, 'dest': os.path.basename(ppt_file_path)})
    prs = Presentation(ppt_file_localhost)
    if slide_index >= len(prs.slides):
        return {'error': f'Slide index {slide_index} out of range'}
    slide = prs.slides[slide_index]
    result = {'textbox1_font_size': None, 'textbox2_font_size': None}
    if textbox1_idx < len(slide.shapes):
        shape1 = slide.shapes[textbox1_idx]
        if hasattr(shape1, 'text_frame') and shape1.has_text_frame:
            for para in shape1.text_frame.paragraphs:
                for run in para.runs:
                    if run.font.size:
                        result['textbox1_font_size'] = run.font.size.pt
                        break
                if result['textbox1_font_size'] is not None:
                    break
    if textbox2_idx < len(slide.shapes):
        shape2 = slide.shapes[textbox2_idx]
        if hasattr(shape2, 'text_frame') and shape2.has_text_frame:
            for para in shape2.text_frame.paragraphs:
                for run in para.runs:
                    if run.font.size:
                        result['textbox2_font_size'] = run.font.size.pt
                        break
                if result['textbox2_font_size'] is not None:
                    break
    return result

