def get_first_slide_text__b3a4b9dc(env, config):
    """Extract text from first slide saved in docx.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        str: Text from the document
    """
    path = config.get('path', '/home/user/Desktop/first_slide.docx')
    file_bytes = env.controller.get_file(path)
    if not file_bytes:
        return ''
    import os
    cache_path = os.path.join(env.cache_dir, 'first_slide.docx')
    with open(cache_path, 'wb') as f:
        f.write(file_bytes)
    try:
        doc = Document(cache_path)
        text = ' '.join([p.text.strip() for p in doc.paragraphs if p.text.strip()])
        return text
    except:
        return ''

def get_pptx_slide_text_and_font__68e1f6f01ead98626051731e37b8ae59(env, config: Dict):
    """Extract text content and font properties from a specific slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'slide_index'

    Returns:
        dict: Dictionary containing text shapes with their text and font properties
    """
    file_path = config['path']
    slide_index = config.get('slide_index', 0)
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        if slide_index >= len(prs.slides):
            return {}
        slide = prs.slides[slide_index]
        result = {'shapes': []}
        for (shape_idx, shape) in enumerate(slide.shapes):
            if hasattr(shape, 'text') and hasattr(shape, 'text_frame'):
                shape_info = {'text': shape.text.strip(), 'runs': []}
                for para in shape.text_frame.paragraphs:
                    for run in para.runs:
                        if run.text.strip():
                            run_info = {'text': run.text.strip(), 'font_name': run.font.name, 'font_size': run.font.size, 'font_bold': run.font.bold, 'font_italic': run.font.italic}
                            shape_info['runs'].append(run_info)
                if shape_info['text']:
                    result['shapes'].append(shape_info)
        return result
    finally:
        os.unlink(tmp_path)

def get_pptx_pic_text_props__81412d8b(env, config: dict) -> Dict[str, Any]:
    """
    Extract picture dimension and text font sizes from PowerPoint file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict

    Returns:
        Dict with picture dimension and font sizes
    """
    file_path = config.get('file_path', '/home/user/Desktop/42_2.pptx')
    slide_picture_idx = config.get('slide_picture', 2)
    slide_text_idx = config.get('slide_text', 4)
    picture_idx = config.get('picture_index', 0)
    picture_check_dim = config.get('picture_check', 'width')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'error': 'Failed to retrieve file'}
    import tempfile
    import os as os_mod
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        picture_value_cm = None
        if slide_picture_idx < len(prs.slides):
            slide_pic = prs.slides[slide_picture_idx]
            if picture_idx < len(slide_pic.shapes):
                shape = slide_pic.shapes[picture_idx]
                if hasattr(shape, picture_check_dim):
                    value_emu = getattr(shape, picture_check_dim)
                    picture_value_cm = round(value_emu / 360000, 2)
        font_sizes = []
        if slide_text_idx < len(prs.slides):
            slide_text = prs.slides[slide_text_idx]
            for shape in slide_text.shapes:
                if hasattr(shape, 'text_frame'):
                    for para in shape.text_frame.paragraphs:
                        for run in para.runs:
                            if run.font.size:
                                font_sizes.append(run.font.size.pt)
        result_key = f'picture_{picture_check_dim}_cm'
        return {result_key: picture_value_cm, 'font_sizes': font_sizes}
    finally:
        os_mod.unlink(tmp_path)

def get_pptx_slide_notes_status__04e351f5cb7d6255945f5cc8dee4d0d5(env, config: Dict) -> Dict[int, bool]:
    """
    Extract which slides have speaker notes in a PPTX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to PPTX file on VM

    Returns:
        Dict mapping slide number (1-indexed) to boolean indicating if it has notes
    """
    file_path = config.get('path')
    if not file_path:
        return {}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        notes_status = {}
        for (i, slide) in enumerate(prs.slides):
            slide_num = i + 1
            has_notes = False
            if slide.has_notes_slide:
                notes_slide = slide.notes_slide
                if notes_slide.notes_text_frame:
                    notes_text = notes_slide.notes_text_frame.text.strip()
                    if notes_text:
                        has_notes = True
            notes_status[slide_num] = has_notes
        return notes_status
    finally:
        os.unlink(tmp_path)

def get_pptx_slide_info__15ef8d4a(env, config: Dict[str, str]):
    """
    Extract slide count and text content from specified slides in a PPTX file.

    Args:
        env: Environment object
        config: Dict with 'path' (VM file path) and 'dest' (destination filename)

    Returns:
        dict: {
            'total_slides': int,
            'slides': {
                '0': 'text from slide 1',
                '1': 'text from slide 2',
                ...
            }
        }
    """
    pptx_path = config['path']
    dest = config['dest']
    local_path = get_vm_file(env, {'path': pptx_path, 'dest': dest})
    prs = Presentation(local_path)
    result = {'total_slides': len(prs.slides), 'slides': {}}
    for (idx, slide) in enumerate(prs.slides):
        slide_text_parts = []
        for shape in slide.shapes:
            if hasattr(shape, 'text') and shape.text.strip():
                slide_text_parts.append(shape.text.strip())
        result['slides'][str(idx)] = ' '.join(slide_text_parts)
    return result

def get_pptx_slide_title__40bd66624b51552d1a8e25508546c714(env, config: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """
    Extract title text and alignment from a specific slide in a PowerPoint file.
    
    Args:
        env: Desktop environment instance
        config: Configuration dict with 'path' (VM file path) and 'slide_idx' (0-indexed slide number)
        
    Returns:
        Dict with 'text' and 'alignment' keys, or None if no title found
    """
    file_path = config.get('path')
    slide_idx = config.get('slide_idx', 0)
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return None
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        if slide_idx >= len(prs.slides):
            return None
        slide = prs.slides[slide_idx]
        title_shape = None
        try:
            if hasattr(slide.shapes, 'title') and slide.shapes.title is not None:
                title_shape = slide.shapes.title
        except:
            pass
        if title_shape is None:
            from pptx.enum.shapes import MSO_SHAPE_TYPE
            try:
                from pptx.enum.shapes import PP_PLACEHOLDER
            except:
                PP_PLACEHOLDER = None
            for shape in slide.shapes:
                if shape.shape_type == MSO_SHAPE_TYPE.PLACEHOLDER or hasattr(shape, 'is_placeholder'):
                    if hasattr(shape, 'placeholder_format'):
                        try:
                            if PP_PLACEHOLDER is not None:
                                if shape.placeholder_format.type == PP_PLACEHOLDER.TITLE:
                                    title_shape = shape
                                    break
                            elif shape.placeholder_format.type == 1:
                                title_shape = shape
                                break
                        except:
                            pass
                    if hasattr(shape, 'name') and 'Title' in shape.name:
                        if hasattr(shape, 'text_frame'):
                            title_shape = shape
                            break
        if title_shape is None:
            for shape in slide.shapes:
                if hasattr(shape, 'name') and hasattr(shape, 'text_frame'):
                    if 'Title' in shape.name or 'title' in shape.name:
                        title_shape = shape
                        break
        if title_shape is not None and hasattr(title_shape, 'text_frame'):
            text = title_shape.text.strip()
            alignment = None
            if title_shape.text_frame.paragraphs:
                para = title_shape.text_frame.paragraphs[0]
                alignment = para.alignment
            align_str = 'NONE'
            if alignment is not None:
                from pptx.enum.text import PP_ALIGN
                if alignment == PP_ALIGN.LEFT or alignment == 1:
                    align_str = 'LEFT'
                elif alignment == PP_ALIGN.CENTER or alignment == 2:
                    align_str = 'CENTER'
                elif alignment == PP_ALIGN.RIGHT or alignment == 3:
                    align_str = 'RIGHT'
                elif alignment == PP_ALIGN.JUSTIFY or alignment == 4:
                    align_str = 'JUSTIFY'
            else:
                align_str = 'LEFT'
            return {'text': text, 'alignment': align_str}
        return None
    finally:
        os.unlink(tmp_path)

