def get_pptx_title_alignment__8a74a6c0(env, config):
    """Get the alignment of the title on a specific slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'vm_path' and 'slide_index'

    Returns:
        dict: {'alignment': alignment_value, 'text': title_text}
    """
    vm_path = config.get('vm_path', '/home/user/Desktop/22_6.pptx')
    slide_index = config.get('slide_index', 1)
    file_content = env.controller.get_file(vm_path)
    if not file_content:
        return {'alignment': None, 'text': None}
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(delete=False, suffix='.pptx') as tmp:
        tmp.write(file_content)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        if slide_index >= len(prs.slides):
            return {'alignment': None, 'text': None}
        slide = prs.slides[slide_index]
        title_shape = None
        for shape in slide.shapes:
            if hasattr(shape, 'text') and shape.text.strip():
                title_shape = shape
                break
        if not title_shape or not hasattr(title_shape, 'text_frame'):
            return {'alignment': None, 'text': None}
        if title_shape.text_frame.paragraphs:
            para = title_shape.text_frame.paragraphs[0]
            alignment = para.alignment
            if alignment is None:
                align_str = 'LEFT'
            elif alignment == PP_ALIGN.LEFT:
                align_str = 'LEFT'
            elif alignment == PP_ALIGN.CENTER:
                align_str = 'CENTER'
            elif alignment == PP_ALIGN.RIGHT:
                align_str = 'RIGHT'
            elif alignment == PP_ALIGN.JUSTIFY:
                align_str = 'JUSTIFY'
            else:
                align_str = str(alignment)
            return {'alignment': align_str, 'text': title_shape.text.strip()}
        return {'alignment': None, 'text': title_shape.text.strip()}
    finally:
        os.unlink(tmp_path)

def get_pptx_auto_advance__288fb8d24f15b54505d66c2670b3ccad(env, config: Dict[str, Any]) -> List[Dict[str, Any]]:
    """Extract automatic advance timing for all slides from PPTX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to VM file path

    Returns:
        List of dicts with slide timing information: [{"slide_idx": 0, "auto_advance_ms": 3000}, ...]
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        logger.error(f"Failed to get file from VM: {config['path']}")
        return []
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        slide_timings = []
        with zipfile.ZipFile(tmp_path, 'r') as zip_ref:
            slide_files = [name for name in zip_ref.namelist() if name.startswith('ppt/slides/slide') and name.endswith('.xml')]
            slide_files.sort()
            for (slide_idx, slide_file) in enumerate(slide_files):
                try:
                    with zip_ref.open(slide_file) as sf:
                        tree = ET.parse(sf)
                        root = tree.getroot()
                        namespaces = {'p': 'http://schemas.openxmlformats.org/presentationml/2006/main'}
                        transition = root.find('.//p:transition', namespaces)
                        auto_advance_ms = None
                        if transition is not None:
                            adv_tm = transition.get('advTm')
                            if adv_tm is not None:
                                auto_advance_ms = int(adv_tm)
                        slide_timings.append({'slide_idx': slide_idx, 'auto_advance_ms': auto_advance_ms})
                except Exception as e:
                    logger.error(f'Error processing slide {slide_file}: {e}')
                    slide_timings.append({'slide_idx': slide_idx, 'auto_advance_ms': None})
        return slide_timings
    finally:
        os.unlink(tmp_path)

def get_pptx_text_font_sizes__bcd304c2(env, config):
    """Extract font sizes of text in specific shapes.

    Args:
        env: DesktopEnv instance
        config: Dict with keys:
            - pptx_path: Path to PPTX file on VM
            - slide_index: 0-based slide index
            - shape_indices: List of shape indices to check

    Returns:
        List of font sizes (in points) for each shape
    """
    pptx_path = config['pptx_path']
    slide_index = config['slide_index']
    shape_indices = config['shape_indices']
    local_file = get_vm_file(env, {'path': pptx_path, 'dest': os.path.basename(pptx_path)})
    prs = Presentation(local_file)
    slide = prs.slides[slide_index]
    font_sizes = []
    for shape_idx in shape_indices:
        shape = slide.shapes[shape_idx]
        if hasattr(shape, 'text_frame') and shape.text_frame.paragraphs:
            for paragraph in shape.text_frame.paragraphs:
                if paragraph.runs:
                    size = paragraph.runs[0].font.size
                    font_sizes.append(size.pt if size else None)
                    break
            else:
                font_sizes.append(None)
        else:
            font_sizes.append(None)
    return font_sizes

def get_pptx_file__150d1ffa1e5d4fa7d9e270aec358de3a(env, config: Dict[str, Any]) -> str:
    """
    Get PPTX file from VM and save to cache.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Local file path to the downloaded PPTX file
    """
    vm_path = config['path']
    file_bytes = env.controller.get_file(vm_path)
    if not file_bytes:
        return None
    dest_filename = os.path.basename(vm_path)
    cache_path = os.path.join(env.cache_dir, dest_filename)
    os.makedirs(env.cache_dir, exist_ok=True)
    with open(cache_path, 'wb') as f:
        f.write(file_bytes)
    return cache_path

