def get_ppt_picture_widths__929c0de50fb0c8b71584d5f1ccde4eab(env, config: Dict):
    """Extract picture widths from specified slides in a PowerPoint file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM file path) and 'slide_picture_map'
                (dict mapping slide_index to picture_index)

    Returns:
        Dict mapping slide_picture keys to width values in cm
    """
    file_path = config.get('path', '')
    slide_picture_map = config.get('slide_picture_map', {})
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        result = {}
        for (slide_idx_str, picture_idx) in slide_picture_map.items():
            slide_idx = int(slide_idx_str)
            if slide_idx >= len(prs.slides):
                continue
            slide = prs.slides[slide_idx]
            pictures = [shape for shape in slide.shapes if hasattr(shape, 'image')]
            if picture_idx < len(pictures):
                picture = pictures[picture_idx]
                width_cm = picture.width / 360000
                result[f'{slide_idx}_{picture_idx}'] = width_cm
        return result
    finally:
        os.unlink(tmp_path)

def get_pptx_font_and_italic__9e62713c(env, config):
    """Get font and italic status of all text in presentation.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'ppt_file_path' key

    Returns:
        dict: {'fonts': set, 'all_italic': bool, 'italic_count': int, 'total_count': int}
    """
    ppt_file_path = config['ppt_file_path']
    ppt_file_localhost_path = get_vm_file(env, {'path': ppt_file_path, 'dest': os.path.split(ppt_file_path)[-1]})
    prs = Presentation(ppt_file_localhost_path)
    fonts_used = set()
    italic_count = 0
    total_count = 0
    for slide in prs.slides:
        for shape in slide.shapes:
            if hasattr(shape, 'text_frame'):
                for paragraph in shape.text_frame.paragraphs:
                    for run in paragraph.runs:
                        if run.text.strip():
                            total_count += 1
                            if run.font.name:
                                fonts_used.add(run.font.name)
                            if run.font.italic:
                                italic_count += 1
    all_italic = italic_count == total_count if total_count > 0 else False
    return {'fonts': fonts_used, 'all_italic': all_italic, 'italic_count': italic_count, 'total_count': total_count}

def get_pptx_combined_slide1_slide2__e72efc19a724a2d15bd876c8bb0440c7(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Get combined data: slide 1 title fonts and slide 2 picture width.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dict with 'slide1_fonts' and 'slide2_width'
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        result = {}
        if len(prs.slides) >= 1:
            slide1 = prs.slides[0]
            font_sizes = []
            for shape in slide1.shapes:
                if hasattr(shape, 'text_frame'):
                    text = shape.text_frame.text.strip()
                    if text in ['STARTUP', 'RETAIL', 'DECK', 'PITCH']:
                        for paragraph in shape.text_frame.paragraphs:
                            for run in paragraph.runs:
                                if run.font.size:
                                    font_sizes.append(run.font.size.pt)
                                    break
            result['slide1_fonts'] = font_sizes
        if len(prs.slides) >= 2:
            slide2 = prs.slides[1]
            for shape in slide2.shapes:
                if hasattr(shape, 'image'):
                    height_cm = shape.height / 360000
                    width_cm = shape.width / 360000
                    if height_cm > 10:
                        result['slide2_width'] = width_cm
                        break
        return result
    finally:
        os.unlink(tmp_path)

def get_pptx_slide_hidden__3f5dbea5(env, config):
    """Check if a slide is hidden from slideshow.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'ppt_file_path' and 'slide_index'

    Returns:
        bool: True if slide is hidden, False otherwise
    """
    ppt_file_path = config.get('ppt_file_path', '/home/user/Desktop/Forests.pptx')
    slide_index = config.get('slide_index', 0)
    local_path = get_vm_file(env, {'path': ppt_file_path, 'dest': os.path.basename(ppt_file_path)})
    try:
        with zipfile.ZipFile(local_path, 'r') as zip_file:
            slide_xml_path = f'ppt/slides/slide{slide_index + 1}.xml'
            if slide_xml_path in zip_file.namelist():
                with zip_file.open(slide_xml_path) as xml_file:
                    tree = ET.parse(xml_file)
                    root = tree.getroot()
                    ns = {'p': 'http://schemas.openxmlformats.org/presentationml/2006/main'}
                    sld_element = root.find('.//p:sld', ns)
                    if sld_element is not None:
                        show_attr = sld_element.get('show')
                        if show_attr == '0' or show_attr == 'false':
                            return True
                    csld_element = root.find('.//p:cSld', ns)
                    if csld_element is not None:
                        show_attr = csld_element.get('show')
                        if show_attr == '0' or show_attr == 'false':
                            return True
    except Exception as e:
        pass
    return False

def get_pptx_content__80c27333cebeb7353404c7cb598c7b50(env, config: dict) -> Dict[str, Any]:
    """Extract slide content including titles and background colors.
    
    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the PPTX file on VM
        
    Returns:
        Dict with slide content: {slide_index: {"title": str, "bg_color": str}}
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        result = {}
        for (idx, slide) in enumerate(prs.slides):
            content = {}
            title = None
            if slide.shapes.title and slide.shapes.title.text:
                title = slide.shapes.title.text.strip()
            else:
                for shape in slide.shapes:
                    if hasattr(shape, 'text') and shape.text and shape.text.strip():
                        title = shape.text.strip()
                        break
            content['title'] = title
            bg_color = None
            try:
                if slide.background.fill.type == 1:
                    if hasattr(slide.background.fill, 'fore_color'):
                        color = slide.background.fill.fore_color
                        if hasattr(color, 'rgb'):
                            rgb = color.rgb
                            bg_color = f'#{rgb[0]:02X}{rgb[1]:02X}{rgb[2]:02X}'
            except:
                pass
            content['bg_color'] = bg_color
            result[idx] = content
        return result
    finally:
        os.unlink(tmp_path)

def get_slide_subtitle_colors__9f08fc3e210038419434a19b8e8896ec(env, config: Dict):
    """Extract font colors from subtitle/body text shapes on a specific slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM file path) and 'slide_index' (0-based)

    Returns:
        List of RGB color tuples (R, G, B) for subtitle/body text runs
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return []
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide_index = config.get('slide_index', 0)
        if slide_index >= len(prs.slides):
            return []
        slide = prs.slides[slide_index]
        colors = []
        for shape in slide.shapes:
            if hasattr(shape, 'text_frame') and shape.text:
                is_subtitle = False
                if hasattr(shape, 'placeholder_format'):
                    try:
                        if shape.placeholder_format.type in [2, 7]:
                            is_subtitle = True
                    except:
                        pass
                for paragraph in shape.text_frame.paragraphs:
                    for run in paragraph.runs:
                        if run.text:
                            if not run.text.isupper() or is_subtitle:
                                if run.font.color and run.font.color.rgb:
                                    rgb = run.font.color.rgb
                                    colors.append((rgb[0], rgb[1], rgb[2]))
        return colors
    finally:
        os.unlink(tmp_path)

def get_pptx_para_props__9aa6e48f(env, config: dict):
    """
    Extract paragraph level and bullet status for specific text on a slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - path: Path to PPTX file on VM
            - dest: Destination filename
            - slide_idx: Slide index (0-based)
            - target_text: Text to find

    Returns:
        dict with 'level' (int or None) and 'has_bullet' (bool or None)
    """
    file_content = env.controller.get_file(config['path'])
    if not file_content:
        return {'level': None, 'has_bullet': None}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_content)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide_idx = config.get('slide_idx', 0)
        target_text = config.get('target_text', '')
        if slide_idx >= len(prs.slides):
            return {'level': None, 'has_bullet': None}
        slide = prs.slides[slide_idx]
        for shape in slide.shapes:
            if hasattr(shape, 'text_frame'):
                for para in shape.text_frame.paragraphs:
                    if para.text.strip() == target_text.strip():
                        level = para.level
                        has_bu_none = para._element.find('.//{http://schemas.openxmlformats.org/drawingml/2006/main}buNone')
                        has_bullet = has_bu_none is None
                        return {'level': level, 'has_bullet': has_bullet}
        return {'level': None, 'has_bullet': None}
    finally:
        os.unlink(tmp_path)

def get_pptx_alignment__3821d67f4f5899cf4277d8f270e8a993(env, config: Dict):
    """Extract alignment status of all text in the PowerPoint presentation.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the PPTX file

    Returns:
        Dict with alignment status information for all text
    """
    file_path = config['path']
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'all_center_aligned': False, 'total_paragraphs': 0, 'center_aligned_paragraphs': 0}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        total_paragraphs = 0
        center_aligned_paragraphs = 0
        for slide in prs.slides:
            for shape in slide.shapes:
                if hasattr(shape, 'text_frame'):
                    for paragraph in shape.text_frame.paragraphs:
                        if paragraph.text.strip():
                            total_paragraphs += 1
                            alignment = paragraph.alignment
                            if alignment == PP_ALIGN.CENTER:
                                center_aligned_paragraphs += 1
                if shape.shape_type == 19:
                    table = shape.table
                    for row in table.rows:
                        for cell in row.cells:
                            for paragraph in cell.text_frame.paragraphs:
                                if paragraph.text.strip():
                                    total_paragraphs += 1
                                    alignment = paragraph.alignment
                                    if alignment == PP_ALIGN.CENTER:
                                        center_aligned_paragraphs += 1
        all_center_aligned = total_paragraphs > 0 and total_paragraphs == center_aligned_paragraphs
        return {'all_center_aligned': all_center_aligned, 'total_paragraphs': total_paragraphs, 'center_aligned_paragraphs': center_aligned_paragraphs}
    finally:
        os.unlink(tmp_path)

