def get_ppt_title_properties__a4d81811(env, config: dict):
    """Extract title formatting properties from specified slides.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - ppt_file_path: Path to PowerPoint file on VM
            - target_slides: List of slide indices (0-based)
            - properties: List of properties to extract (color, bold, size, italic, underline, font_name)

    Returns:
        dict: Mapping of slide_index -> {property: value}
    """
    ppt_file_path = config['ppt_file_path']
    target_slides = config['target_slides']
    properties = config.get('properties', ['color', 'bold', 'size', 'italic', 'underline', 'font_name'])
    ppt_localhost_path = get_vm_file(env, {'path': ppt_file_path, 'dest': ppt_file_path.split('/')[-1]})
    prs = Presentation(ppt_localhost_path)
    results = {}
    for slide_idx in target_slides:
        if slide_idx >= len(prs.slides):
            continue
        slide = prs.slides[slide_idx]
        title_shape = None
        max_size = 0
        for shape in slide.shapes:
            if hasattr(shape, 'text') and shape.text and hasattr(shape, 'text_frame'):
                if shape.text_frame.paragraphs:
                    para = shape.text_frame.paragraphs[0]
                    if para.runs:
                        run = para.runs[0]
                        if run.font.size:
                            size_pt = run.font.size.pt
                            if size_pt > max_size:
                                max_size = size_pt
                                title_shape = shape
        if not title_shape:
            continue
        para = title_shape.text_frame.paragraphs[0]
        run = para.runs[0]
        font = run.font
        slide_properties = {}
        if 'color' in properties:
            if font.color and hasattr(font.color, 'rgb'):
                rgb = font.color.rgb
                slide_properties['color'] = f'#{rgb[0]:02X}{rgb[1]:02X}{rgb[2]:02X}'
            else:
                slide_properties['color'] = None
        if 'bold' in properties:
            slide_properties['bold'] = bool(font.bold) if font.bold is not None else False
        if 'size' in properties:
            slide_properties['size'] = font.size.pt if font.size else None
        if 'italic' in properties:
            slide_properties['italic'] = bool(font.italic) if font.italic is not None else False
        if 'underline' in properties:
            slide_properties['underline'] = bool(font.underline) if font.underline is not None else False
        if 'font_name' in properties:
            slide_properties['font_name'] = font.name
        results[slide_idx] = slide_properties
    return results

