    prs = Presentation(local_path)
    slide = prs.slides[0]
    result = {}
    if len(slide.shapes) > 0:
        title_shape = slide.shapes[0]
        if hasattr(title_shape, 'text_frame'):
            para = title_shape.text_frame.paragraphs[0]
            if para.runs:
                run = para.runs[0]
                result['title_size'] = run.font.size
                result['title_bold'] = run.font.bold
                result['title_italic'] = run.font.italic
                if hasattr(run.font.color, 'rgb'):
                    rgb = run.font.color.rgb
                    result['title_color'] = [rgb[0], rgb[1], rgb[2]]
    if len(slide.shapes) > 1:
        content_shape = slide.shapes[1]
        if hasattr(content_shape, 'text_frame'):
            para = content_shape.text_frame.paragraphs[0]
            if para.runs:
                run = para.runs[0]
                result['content_size'] = run.font.size
                result['content_bold'] = run.font.bold
                result['content_italic'] = run.font.italic
                if hasattr(run.font.color, 'rgb'):
                    rgb = run.font.color.rgb
                    result['content_color'] = [rgb[0], rgb[1], rgb[2]]
    fill = slide.background.fill
    if fill.type == 1:
        if hasattr(fill.fore_color, 'rgb'):
            rgb = fill.fore_color.rgb
            result['bg_color'] = [rgb[0], rgb[1], rgb[2]]
    return result

