def get_pptx_formatting__0315ec97(env, config: dict):
    """Extract formatting state for text in specified slides.
    
    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'dest', 'slide_indices'
        
    Returns:
        dict: Formatting information for all text runs in specified slides
    """
    pptx_path = config.get('path', '/home/user/Desktop/43_1.pptx')
    dest = config.get('dest', '43_1.pptx')
    slide_indices = config.get('slide_indices', [])
    local_path = get_vm_file(env, {'path': pptx_path, 'dest': dest})
    prs = Presentation(local_path)
    formatting_data = {}
    for slide_idx in slide_indices:
        if slide_idx >= len(prs.slides):
            continue
        slide = prs.slides[slide_idx]
        for (shape_idx, shape) in enumerate(slide.shapes):
            if not hasattr(shape, 'text_frame'):
                continue
            for (para_idx, para) in enumerate(shape.text_frame.paragraphs):
                for (run_idx, run) in enumerate(para.runs):
                    key = (slide_idx, shape_idx, para_idx, run_idx)
                    color_value = None
                    if run.font.color and hasattr(run.font.color, 'rgb'):
                        rgb = run.font.color.rgb
                        color_value = [rgb[0], rgb[1], rgb[2]]
                    formatting_data[key] = {'text': run.text, 'bold': run.font.bold, 'italic': run.font.italic, 'underline': run.font.underline, 'size': run.font.size.pt if run.font.size else None, 'color': color_value, 'alignment': para.alignment}
    return formatting_data

def get_slide_bg_and_notes__6025dd93(env, config: Dict) -> Dict:
    """
    Get slide background color and notes text for variation 8 (pink background).

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'pptx_path' and 'slide_idx'

    Returns:
        Dict with 'background_rgb' (tuple or None) and 'notes_text' (str)
    """
    pptx_path = config.get('pptx_path')
    slide_idx = config.get('slide_idx', 0)
    file_bytes = env.controller.get_file(pptx_path)
    if not file_bytes:
        return {'background_rgb': None, 'notes_text': ''}
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(delete=False, suffix='.pptx') as tmp_file:
        tmp_file.write(file_bytes)
        tmp_path = tmp_file.name
    try:
        prs = Presentation(tmp_path)
        if slide_idx >= len(prs.slides):
            return {'background_rgb': None, 'notes_text': ''}
        slide = prs.slides[slide_idx]
        bg_rgb = None
        fill = slide.background.fill
        if fill.type == 1:
            try:
                bg_rgb = fill.fore_color.rgb
            except:
                bg_rgb = None
        elif fill.type == 5:
            try:
                master_fill = slide.slide_layout.slide_master.background.fill
                if master_fill.type == 1:
                    bg_rgb = master_fill.fore_color.rgb
            except:
                bg_rgb = None
        notes_text = ''
        if slide.has_notes_slide:
            notes_slide = slide.notes_slide
            if notes_slide.notes_text_frame:
                notes_text = notes_slide.notes_text_frame.text.strip()
        return {'background_rgb': bg_rgb, 'notes_text': notes_text}
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

