def get_pptx_image_info__e9bc18b68240a0264d167fda8a8b171a(env, config):
    """Extract image information from a PowerPoint slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'slide_index', and optionally 'image_index'

    Returns:
        dict: Image information including size and position
    """
    file_path = config.get('path')
    slide_index = config.get('slide_index', 0)
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        if slide_index >= len(prs.slides):
            return {}
        slide = prs.slides[slide_index]
        images = [shape for shape in slide.shapes if shape.shape_type == 13]
        if not images:
            return {'image_count': 0}
        images_info = []
        for img in images:
            width_cm = img.width / 360000
            height_cm = img.height / 360000
            image_blob = img.image.blob
            image_hash = hashlib.md5(image_blob).hexdigest()
            image_filename = None
            try:
                image_part = img.image.part
                if hasattr(image_part, 'partname'):
                    partname = image_part.partname
                    image_filename = os.path.basename(partname)
            except:
                pass
            images_info.append({'width_cm': width_cm, 'height_cm': height_cm, 'left': img.left, 'top': img.top, 'image_hash': image_hash, 'image_filename': image_filename})
        return {'image_count': len(images), 'images': images_info}
    finally:
        os.unlink(tmp_path)

def get_pptx_slide_info__63c5ecc1546db5bcb0fccda77189e75e(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Get slide count and text from slides 15-17 and the last 3 slides.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the PPTX file on VM

    Returns:
        Dict with 'slide_count', 'slides_15_17_text' (text from slides 15-17),
        and 'last_3_slides_text' (text from last 3 slides)
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'slide_count': 0, 'slides_15_17_text': [], 'last_3_slides_text': []}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide_count = len(prs.slides)
        slides_list = list(prs.slides)

        def extract_slide_text(slide):
            """Extract all text from a slide."""
            texts = []
            for shape in slide.shapes:
                if hasattr(shape, 'text') and shape.text.strip():
                    texts.append(shape.text.strip())
            return ' '.join(texts)
        slides_15_17_text = []
        for idx in [14, 15, 16]:
            if idx < len(slides_list):
                slides_15_17_text.append(extract_slide_text(slides_list[idx]))
            else:
                slides_15_17_text.append('')
        last_3_slides_text = []
        for idx in range(max(0, slide_count - 3), slide_count):
            if idx < len(slides_list):
                last_3_slides_text.append(extract_slide_text(slides_list[idx]))
            else:
                last_3_slides_text.append('')
        return {'slide_count': slide_count, 'slides_15_17_text': slides_15_17_text, 'last_3_slides_text': last_3_slides_text}
    finally:
        os.unlink(tmp_path)

