def get_pptx_table_row__4047317c(env, config):
    """Get all cell values from a specific row in a PowerPoint table.

    Args:
        env: DesktopEnv instance
        config: Dict with 'path', 'slide_index', 'row'

    Returns:
        list: List of cell text values
    """
    path = config['path']
    slide_index = config['slide_index']
    row = config['row']
    local_path = get_vm_file(env, {'path': path, 'dest': os.path.basename(path)})
    prs = Presentation(local_path)
    slide = prs.slides[slide_index]
