def get_pptx_state__48f8588f1ee3dc46b9eb8de69949054d(env, config: dict) -> Dict[str, Any]:
    """Extract PowerPoint presentation state including titles and backgrounds.
    
    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the PPTX file on VM
        
    Returns:
        Dict with slide state: {slide_index: {"title": str, "bg_color": str}}
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        result = {}
        for (idx, slide) in enumerate(prs.slides):
            state = {}
            title = None
            if slide.shapes.title and slide.shapes.title.text:
                title = slide.shapes.title.text.strip()
            else:
                for shape in slide.shapes:
                    if hasattr(shape, 'text') and shape.text and shape.text.strip():
                        title = shape.text.strip()
                        break
            state['title'] = title
            bg_color = None
            try:
                if slide.background.fill.type == 1:
                    if hasattr(slide.background.fill, 'fore_color'):
                        color = slide.background.fill.fore_color
                        if hasattr(color, 'rgb'):
                            rgb = color.rgb
                            bg_color = f'#{rgb[0]:02X}{rgb[1]:02X}{rgb[2]:02X}'
            except:
                pass
            state['bg_color'] = bg_color
            result[idx] = state
        return result
    finally:
        os.unlink(tmp_path)

def get_pptx_bg_notes__625bf205ef72cc22a81195457bc5ad8b(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract background color and notes from PowerPoint slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dict with 'background_rgb' and 'notes' keys
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'background_rgb': None, 'notes': ''}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        if len(prs.slides) == 0:
            return {'background_rgb': None, 'notes': ''}
        slide = prs.slides[0]
        fill = slide.background.fill
        bg_rgb = None
        if fill.type == 1:
            rgb_obj = fill.fore_color.rgb
            bg_rgb = [rgb_obj[0], rgb_obj[1], rgb_obj[2]]
        elif fill.type == 5:
            master_fill = slide.slide_layout.slide_master.background.fill
            if master_fill.type == 1:
                rgb_obj = master_fill.fore_color.rgb
                bg_rgb = [rgb_obj[0], rgb_obj[1], rgb_obj[2]]
        notes = ''
        if slide.has_notes_slide:
            notes_slide = slide.notes_slide
            notes = notes_slide.notes_text_frame.text.strip()
        return {'background_rgb': bg_rgb, 'notes': notes}
    finally:
        os.unlink(tmp_path)

def get_pptx_slide1_title_formatting__31031875(env, config):
    """Get italic and font size formatting of slide 1 title.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with pptx_path parameter

    Returns:
        dict: {"italic": bool, "font_size": int/None}
    """
    pptx_path = config.get('pptx_path', '/home/user/Desktop/39_2.pptx')
    local_path = get_vm_file(env, {'path': pptx_path, 'dest': os.path.basename(pptx_path)})
    prs = Presentation(local_path)
    if len(prs.slides) < 1:
        return {'italic': False, 'font_size': None}
    slide = prs.slides[0]
    title_shape = None
    for shape in slide.shapes:
        if shape.is_placeholder:
            try:
                ph_type = shape.placeholder_format.type
                if ph_type in (1, 3):
                    title_shape = shape
                    break
            except:
                pass
    if title_shape is None:
        topmost_text_shape = None
        min_top = float('inf')
        for shape in slide.shapes:
            if hasattr(shape, 'text_frame') and shape.has_text_frame:
                if shape.top < min_top:
                    min_top = shape.top
                    topmost_text_shape = shape
        title_shape = topmost_text_shape
    if title_shape is not None and hasattr(title_shape, 'text_frame'):
        all_runs = []
        for para in title_shape.text_frame.paragraphs:
            all_runs.extend(para.runs)
        if not all_runs:
            return {'italic': False, 'font_size': None}
        italic_count = 0
        font_sizes = []
        for run in all_runs:
            if run.font.italic:
                italic_count += 1
            if run.font.size:
                font_sizes.append(run.font.size.pt)
        italic = italic_count > len(all_runs) / 2
        if font_sizes:
            font_size = max(set(font_sizes), key=font_sizes.count)
        else:
            font_size = None
        return {'italic': italic, 'font_size': font_size}
    return {'italic': False, 'font_size': None}

def get_pptx_fonts__31c59c79883028214b459291a7ebc3b8(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract all fonts used in a PowerPoint presentation.
    
    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the PPTX file on VM
        
    Returns:
        Dict containing fonts used per slide and overall statistics
    """
    try:
        from pptx import Presentation
    except ImportError:
        return {'error': 'python-pptx library not available'}
    file_path = config.get('path', '')
    if not file_path:
        return {'error': 'No file path specified'}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'error': f'Could not retrieve file from VM: {file_path}'}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        result = {'total_slides': len(prs.slides), 'slides': [], 'all_fonts': set()}
        for (slide_idx, slide) in enumerate(prs.slides, 1):
            slide_fonts = set()
            text_runs = 0
            for shape in slide.shapes:
                if hasattr(shape, 'text_frame'):
                    for paragraph in shape.text_frame.paragraphs:
                        for run in paragraph.runs:
                            text_runs += 1
                            if run.font.name:
                                slide_fonts.add(run.font.name)
                                result['all_fonts'].add(run.font.name)
            result['slides'].append({'slide_number': slide_idx, 'fonts': list(slide_fonts), 'text_runs': text_runs})
        result['all_fonts'] = list(result['all_fonts'])
        return result
    except Exception as e:
        return {'error': f'Error processing PowerPoint file: {str(e)}'}
    finally:
        try:
            os.unlink(tmp_path)
        except:
            pass

def get_pptx_title_alignment__fe0aae362680ca5c942a3c4cb5931583(env, config: Dict[str, Any]):
    """Extract alignment information for the title shape on a slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'slide_index'

    Returns:
        Dict with alignment info: {'alignment': str, 'text': str}
    """
    file_path = config['path']
    slide_index = config.get('slide_index', 0)
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        if slide_index >= len(prs.slides):
            return {}
        slide = prs.slides[slide_index]
        title_shape = None
        for shape in slide.shapes:
            if shape.is_placeholder:
                try:
                    if shape.placeholder_format.type == 1:
                        title_shape = shape
                        break
                except:
                    pass
        if not title_shape:
            for shape in slide.shapes:
                if hasattr(shape, 'text_frame') and shape.text.strip():
                    if hasattr(shape, 'name') and 'title' in shape.name.lower():
                        title_shape = shape
                        break
        if title_shape and hasattr(title_shape, 'text_frame'):
            if title_shape.text_frame.paragraphs:
                para = title_shape.text_frame.paragraphs[0]
                alignment = para.alignment
                if alignment is None:
                    alignment_str = 'LEFT'
                elif alignment == PP_ALIGN.LEFT:
                    alignment_str = 'LEFT'
                elif alignment == PP_ALIGN.CENTER:
                    alignment_str = 'CENTER'
                elif alignment == PP_ALIGN.RIGHT:
                    alignment_str = 'RIGHT'
                elif alignment == PP_ALIGN.JUSTIFY:
                    alignment_str = 'JUSTIFY'
                else:
                    alignment_str = str(alignment)
                return {'alignment': alignment_str, 'text': title_shape.text.strip()}
        return {}
    finally:
        os.unlink(tmp_path)

