def get_pptx_text_bold__5c35eef4(env, config):
    """Get bold status of text in a specific slide and shape.

    Args:
        env: DesktopEnv instance
        config: Dict with keys: ppt_path, slide_index, shape_index

    Returns:
        bool: True if all text is bold, False otherwise
    """
    ppt_path = config['ppt_path']
    slide_index = int(config['slide_index'])
    shape_index = int(config['shape_index'])
    local_path = get_vm_file(env, {'path': ppt_path, 'dest': os.path.basename(ppt_path)})
    prs = Presentation(local_path)
    slide = prs.slides[slide_index]
    shape = slide.shapes[shape_index]
    if not hasattr(shape, 'text_frame'):
        return False
    for paragraph in shape.text_frame.paragraphs:
        for run in paragraph.runs:
            if not run.font.bold:
                return False
    return True

def get_pptx_all_fonts__9e62713c(env, config):
    """Extract all unique fonts used in a PowerPoint presentation.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'ppt_file_path' key

    Returns:
        set: Set of font names used in the presentation
    """
    ppt_file_path = config['ppt_file_path']
    ppt_file_localhost_path = get_vm_file(env, {'path': ppt_file_path, 'dest': os.path.split(ppt_file_path)[-1]})
    prs = Presentation(ppt_file_localhost_path)
    fonts_used = set()
    for slide in prs.slides:
        for shape in slide.shapes:
            if hasattr(shape, 'text_frame'):
                for paragraph in shape.text_frame.paragraphs:
                    for run in paragraph.runs:
                        if run.font.name:
                            fonts_used.add(run.font.name)
    return fonts_used

def get_pptx_title_bold_color__3dcb9257c16008b1bc6bfa1de819a5c4(env, config):
    """Extract bold property and RGB color of titles in specified slides.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with keys:
            - path: VM file path (e.g., "/home/user/Desktop/4_1.pptx")
            - slides: List of slide indices (0-based) to check

    Returns:
        dict: Mapping of slide_index -> {"bold": bool, "color": (R, G, B) or None}
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        result = {}
        for slide_idx in config.get('slides', []):
            if slide_idx >= len(prs.slides):
                continue
            slide = prs.slides[slide_idx]
            title_shape = None
            if slide.shapes.title:
                title_shape = slide.shapes.title
            else:
                for shape in slide.shapes:
                    if hasattr(shape, 'text') and shape.text.strip():
                        title_shape = shape
                        break
            if title_shape and hasattr(title_shape, 'text_frame'):
                all_bold = True
                color = None
                has_text = False
                consistent_color = True
                for para in title_shape.text_frame.paragraphs:
                    for run in para.runs:
                        if run.text.strip():
                            has_text = True
                            if not run.font.bold:
                                all_bold = False
                            if hasattr(run.font.color, 'rgb'):
                                run_color = run.font.color.rgb
                                if color is None:
                                    color = run_color
                                elif color != run_color:
                                    consistent_color = False
                if has_text:
                    result[slide_idx] = {'bold': all_bold, 'color': color if consistent_color else None}
        return result
    finally:
        os.unlink(tmp_path)

def get_ppt_slide_duplicate__eb917201(env, config: dict):
    """Extract slide count and text content of specific slides.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with ppt_file_path

    Returns:
        dict: {
            'slide_count': int,
            'slide_texts': dict mapping slide_index to list of texts
        }
    """
    ppt_file_path = config['ppt_file_path']
    ppt_localhost_path = get_vm_file(env, {'path': ppt_file_path, 'dest': os.path.basename(ppt_file_path)})
    prs = Presentation(ppt_localhost_path)
    slide_count = len(prs.slides)
    slide_texts = {}
    for (idx, slide) in enumerate(prs.slides):
        texts = []
        for shape in slide.shapes:
            if hasattr(shape, 'text') and shape.text.strip():
                texts.append(shape.text.strip())
        slide_texts[idx] = sorted(texts)
    return {'slide_count': slide_count, 'slide_texts': slide_texts}

def get_ppt_slide_titles__fdf0c778(env, config):
    """Get all slide titles from a presentation.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (PPTX file)

    Returns:
        list: List of title strings for each slide (empty string if no title)
    """
    file_path = config.get('path', '')
    try:
        prs = Presentation(file_path)
        titles = []
        for slide in prs.slides:
            title_text = ''
            if hasattr(slide.shapes, 'title') and slide.shapes.title is not None:
                if hasattr(slide.shapes.title, 'text'):
                    title_text = slide.shapes.title.text.strip()
            titles.append(title_text)
        return titles
    except Exception as e:
        print(f'Error reading PPTX file: {e}')
        return []

def get_pptx_first_textbox_size__72da3ff1d92905bd2d3e7bf53c1940a3(env, config: Dict[str, Any]) -> float:
    """Extract font size from the first textbox on a slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - path: VM path to the PPTX file
            - slide_index: 0-based slide index

    Returns:
        Font size in points (or None if not found)
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return None
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
