def get_slide_title_text__0ca2c3bd7c0141a6600e332502b8fa61(env, config: Dict):
    """Extract the title text from a specific slide in a PowerPoint file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (file path) and 'slide_index' (0-based)

    Returns:
        str: The title text, or empty string if not found
    """
    ppt_path = config['path']
    slide_index = config.get('slide_index', 0)
    file_bytes = env.controller.get_file(ppt_path)
    if not file_bytes:
        return ''
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        if slide_index >= len(prs.slides):
            return ''
        slide = prs.slides[slide_index]
        for shape in slide.shapes:
            if shape.is_placeholder:
                placeholder = shape.placeholder_format
                if placeholder.type == 1:
                    if hasattr(shape, 'text'):
                        return shape.text.strip()
        for shape in slide.shapes:
            if hasattr(shape, 'text') and shape.text.strip():
                if hasattr(shape, 'top') and shape.top < prs.slide_height / 3:
                    return shape.text.strip()
        for shape in slide.shapes:
            if hasattr(shape, 'text') and shape.text.strip():
                return shape.text.strip()
        return ''
    finally:
        os.unlink(tmp_path)

def get_slide_text_bold_status__b460ab2e8a717b01367d950b2e29ed95(env, config: Dict):
    """Extract bold status from all text runs on a specific slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM file path) and 'slide_index' (0-based)

    Returns:
        Dict with 'total_runs' (int) and 'bold_runs' (int)
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'total_runs': 0, 'bold_runs': 0}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide_index = config.get('slide_index', 0)
        if slide_index >= len(prs.slides):
            return {'total_runs': 0, 'bold_runs': 0}
        slide = prs.slides[slide_index]
        total_runs = 0
        bold_runs = 0
        for shape in slide.shapes:
            if hasattr(shape, 'text_frame'):
                for paragraph in shape.text_frame.paragraphs:
                    for run in paragraph.runs:
                        if run.text.strip():
                            total_runs += 1
                            if run.font.bold:
                                bold_runs += 1
        return {'total_runs': total_runs, 'bold_runs': bold_runs}
    finally:
        os.unlink(tmp_path)

