def get_pptx_specific_text_font_sizes__142481978ec9902386828a88ad31c18c(env, config: Dict):
    """Extract font sizes for specific text patterns in a PowerPoint slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - 'path': VM file path to the PPTX file
            - 'slide_index': 0-based slide index
            - 'text_patterns': list of text patterns to search for

    Returns:
        dict: Mapping of text patterns to their font sizes {pattern: font_size_pt}
              Returns None for patterns not found or if no matching text found
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide_index = config['slide_index']
        text_patterns = config.get('text_patterns', [])
        if slide_index >= len(prs.slides):
            return {}
        slide = prs.slides[slide_index]
        result = {}
        for pattern in text_patterns:
            result[pattern] = None
        for shape in slide.shapes:
            if not hasattr(shape, 'text_frame'):
                continue
            for paragraph in shape.text_frame.paragraphs:
                for run in paragraph.runs:
                    text = run.text.strip()
                    if not text:
                        continue
                    for pattern in text_patterns:
                        normalized_text = ' '.join(text.split())
                        normalized_pattern = ' '.join(pattern.split())
                        if normalized_pattern.lower() in normalized_text.lower():
                            if run.font.size:
                                size_pt = run.font.size / 12700
                                result[pattern] = round(size_pt, 1)
                            break
        return result
    finally:
        os.unlink(tmp_path)

