def get_pptx_title_bold__1c14b47802cddd8afd5dafb27eb32d2a(env, config: Dict):
    """Extract title text bold status from PowerPoint file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to PPTX file on VM

    Returns:
        dict: {"is_bold": bool} - whether the title text is bold
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'is_bold': False}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        if len(prs.slides) == 0:
            return {'is_bold': False}
        slide = prs.slides[0]
        title_shape = None
        if hasattr(slide.shapes, 'title') and slide.shapes.title is not None:
            title_shape = slide.shapes.title
        if title_shape is None:
            from pptx.enum.shapes import MSO_SHAPE_TYPE
            try:
                from pptx.enum.shapes import PP_PLACEHOLDER
                for shape in slide.shapes:
                    if shape.is_placeholder:
                        if shape.placeholder_format.type == PP_PLACEHOLDER.TITLE:
                            title_shape = shape
                            break
            except (ImportError, AttributeError):
                for shape in slide.shapes:
                    if hasattr(shape, 'text_frame') and shape.has_text_frame:
                        if shape.text.strip():
                            title_shape = shape
                            break
        if title_shape is None or not title_shape.has_text_frame:
            return {'is_bold': False}
        for para in title_shape.text_frame.paragraphs:
            if len(para.runs) == 0:
                if para.text.strip():
                    return {'is_bold': False}
            else:
                for run in para.runs:
                    if run.font.bold != True:
                        return {'is_bold': False}
        return {'is_bold': True}
    finally:
        os.unlink(tmp_path)

def get_pptx_textbox_alignments__badca355bd4fc0b3c6698dd76f06efb2(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract textbox alignment information from PowerPoint slides.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - path: VM path to the PPTX file
            - slides: List of slide numbers (1-indexed) to check
            - textbox_indices: List of textbox indices (0-indexed) for each slide

    Returns:
        Dict mapping individual textbox keys (slide_X_tb_Y) to their alignments
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        result = {}
        slides_to_check = config.get('slides', [])
        textbox_indices = config.get('textbox_indices', [])
        for (slide_idx, (slide_num, tb_index)) in enumerate(zip(slides_to_check, textbox_indices)):
            slide_zero_idx = slide_num - 1
            if slide_zero_idx >= len(prs.slides):
                continue
            slide = prs.slides[slide_zero_idx]
            textboxes = []
            for shape in slide.shapes:
                if shape.shape_type == MSO_SHAPE_TYPE.GROUP:
                    for sub_shape in shape.shapes:
                        if hasattr(sub_shape, 'text_frame') and sub_shape.text_frame:
                            textboxes.append(sub_shape)
                elif hasattr(shape, 'text_frame') and shape.text_frame:
                    textboxes.append(shape)
            if tb_index < len(textboxes):
                textbox = textboxes[tb_index]
                if textbox.text_frame.paragraphs:
                    alignment = textbox.text_frame.paragraphs[0].alignment
                    if alignment == PP_ALIGN.LEFT or alignment == 1:
                        align_str = 'left'
                    elif alignment == PP_ALIGN.CENTER or alignment == 2:
                        align_str = 'center'
                    elif alignment == PP_ALIGN.RIGHT or alignment == 3:
                        align_str = 'right'
                    elif alignment == PP_ALIGN.JUSTIFY or alignment == 4:
                        align_str = 'justify'
                    elif alignment is None:
                        align_str = 'none'
                    else:
                        align_str = str(alignment)
                    result[f'slide_{slide_num}_tb_{tb_index}'] = align_str
        return result
    finally:
        os.unlink(tmp_path)

def get_pptx_font_italic__c0fbdf347bb34e3acd9130f4b3c8a6e0(env, config: dict):
    """Extract font italic status from specific shape in PowerPoint slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM file path), 'slide_idx' (0-based), 'shape_idx'

    Returns:
        dict: Dictionary with italic info for each run
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide_idx = config.get('slide_idx', 0)
        shape_idx = config.get('shape_idx', 0)
        if slide_idx >= len(prs.slides):
            return {}
        slide = prs.slides[slide_idx]
        if shape_idx >= len(slide.shapes):
            return {}
        shape = slide.shapes[shape_idx]
        if not hasattr(shape, 'text_frame'):
            return {}
        italic_info = []
        for para in shape.text_frame.paragraphs:
            for run in para.runs:
                is_italic = run.font.italic if run.font.italic is not None else False
                italic_info.append({'text': run.text, 'is_italic': is_italic})
        return {'slide_idx': slide_idx, 'shape_idx': shape_idx, 'italic_info': italic_info}
    finally:
        os.unlink(tmp_path)

