def get_pptx_text_color__850e83a7b77599493322d468677143fd(env, config: Dict):
    """Extract text color from textboxes in specific slides.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'slides' keys

    Returns:
        Dict mapping slide indices to list of color info dicts for each textbox.
        Each textbox dict contains:
        - 'all_colors': list of all unique RGB tuples found in all runs
        - 'dominant_color': most common color (or first color if all equal)
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        result = {}
        slides_to_check = config.get('slides', [])
        for slide_idx in slides_to_check:
            if slide_idx >= len(prs.slides):
                continue
            slide = prs.slides[slide_idx]
            slide_textboxes = []
            for shape in slide.shapes:
                if hasattr(shape, 'text_frame'):
                    if not shape.text_frame.text.strip():
                        continue
                    all_colors = []
                    for paragraph in shape.text_frame.paragraphs:
                        for run in paragraph.runs:
                            if run.text.strip():
                                try:
                                    if run.font.color.type is not None and hasattr(run.font.color, 'rgb'):
                                        rgb = run.font.color.rgb
                                        color = (rgb[0], rgb[1], rgb[2])
                                        all_colors.append(color)
                                except:
                                    pass
                    if all_colors:
                        from collections import Counter
                        color_counts = Counter(all_colors)
                        dominant_color = color_counts.most_common(1)[0][0]
                        textbox_info = {'all_colors': list(set(all_colors)), 'dominant_color': dominant_color}
                    else:
                        textbox_info = {'all_colors': [], 'dominant_color': None}
                    slide_textboxes.append(textbox_info)
            result[slide_idx] = slide_textboxes
        return result
    finally:
        os.unlink(tmp_path)

def get_pptx_slide_title__c94bbdf8a4008cd226cb8141e208a5b2(env, config: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """
    Extract title text and alignment from a specific slide in a PowerPoint file.
    
    Args:
        env: Desktop environment instance
        config: Configuration dict with 'path' (VM file path) and 'slide_idx' (0-indexed slide number)
        
    Returns:
        Dict with 'text' and 'alignment' keys, or None if no title found
    """
    file_path = config.get('path')
    slide_idx = config.get('slide_idx', 0)
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return None
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        if slide_idx >= len(prs.slides):
            return None
        slide = prs.slides[slide_idx]
        for shape in slide.shapes:
            if hasattr(shape, 'text') and hasattr(shape, 'text_frame'):
                text = shape.text.strip()
                if text:
                    alignment = None
                    if shape.text_frame.paragraphs:
                        para = shape.text_frame.paragraphs[0]
                        alignment = para.alignment
                    align_str = 'NONE'
                    if alignment is not None:
                        from pptx.enum.text import PP_ALIGN
                        if alignment == PP_ALIGN.LEFT or alignment == 1:
                            align_str = 'LEFT'
                        elif alignment == PP_ALIGN.CENTER or alignment == 2:
                            align_str = 'CENTER'
                        elif alignment == PP_ALIGN.RIGHT or alignment == 3:
                            align_str = 'RIGHT'
                        elif alignment == PP_ALIGN.JUSTIFY or alignment == 4:
                            align_str = 'JUSTIFY'
                    else:
                        align_str = 'LEFT'
                    return {'text': text, 'alignment': align_str}
        return None
    finally:
        os.unlink(tmp_path)

def get_pptx_formatting__eb1a2c3f(env, config: dict):
    """Extract formatting state for text in specified slides.
    
    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'dest', 'slide_indices'
        
    Returns:
        dict: Formatting information for all text runs in specified slides
    """
    pptx_path = config.get('path', '/home/user/Desktop/43_1.pptx')
    dest = config.get('dest', '43_1.pptx')
    slide_indices = config.get('slide_indices', [])
    local_path = get_vm_file(env, {'path': pptx_path, 'dest': dest})
    prs = Presentation(local_path)
    formatting_data = {}
    for slide_idx in slide_indices:
        if slide_idx >= len(prs.slides):
            continue
        slide = prs.slides[slide_idx]
        for (shape_idx, shape) in enumerate(slide.shapes):
            if not hasattr(shape, 'text_frame'):
                continue
            for (para_idx, para) in enumerate(shape.text_frame.paragraphs):
                for (run_idx, run) in enumerate(para.runs):
                    key = (slide_idx, shape_idx, para_idx, run_idx)
                    formatting_data[key] = {'text': run.text, 'bold': run.font.bold, 'italic': run.font.italic, 'underline': run.font.underline, 'size': run.font.size.pt if run.font.size else None, 'color': run.font.color.rgb if hasattr(run.font.color, 'rgb') else None, 'alignment': para.alignment}
    return formatting_data

