def get_slide_title_colors__32ef86d4c4f78ef3608b9720ef264e8d(env, config: Dict):
    """Extract font colors from title/heading text shapes on a specific slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM file path) and 'slide_index' (0-based)

    Returns:
        List of RGB color tuples (R, G, B) for title/heading text runs
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return []
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide_index = config.get('slide_index', 0)
        if slide_index >= len(prs.slides):
            return []
        slide = prs.slides[slide_index]
        colors = []
        for shape in slide.shapes:
            if hasattr(shape, 'text_frame') and shape.text:
                is_title = False
                if hasattr(shape, 'placeholder_format'):
                    try:
                        if shape.placeholder_format.type in [1, 3]:
                            is_title = True
                    except:
                        pass
                for paragraph in shape.text_frame.paragraphs:
                    for run in paragraph.runs:
                        if run.text:
                            try:
                                if hasattr(run.font, 'size') and run.font.size and (run.font.size.pt > 20):
                                    is_title = True
                            except:
                                pass
                            if run.font.color and run.font.color.rgb:
                                if run.text.isupper() or is_title:
                                    rgb = run.font.color.rgb
                                    colors.append((rgb[0], rgb[1], rgb[2]))
        return colors
    finally:
        os.unlink(tmp_path)

