def get_pptx_textbox_fonts__85aa6871(env, config):
    """Extract font sizes from two specific textboxes in a PowerPoint slide.
    
    Args:
        env: DesktopEnv instance
        config: Configuration dict with parameters:
            - ppt_file_path: Path to PPTX file on VM
            - slide_index: Slide index (0-based)
            - textbox1_shape_idx: First textbox shape index
            - textbox2_shape_idx: Second textbox shape index
            
    Returns:
        dict: {"textbox1_font_size": float, "textbox2_font_size": float}
    """
    ppt_file_path = config['ppt_file_path']
    slide_index = int(config['slide_index'])
    textbox1_idx = int(config['textbox1_shape_idx'])
    textbox2_idx = int(config['textbox2_shape_idx'])
    ppt_file_localhost = get_vm_file(env, {'path': ppt_file_path, 'dest': os.path.basename(ppt_file_path)})
    prs = Presentation(ppt_file_localhost)
    if slide_index >= len(prs.slides):
        return {'error': f'Slide index {slide_index} out of range'}
    slide = prs.slides[slide_index]
    result = {'textbox1_font_size': None, 'textbox2_font_size': None}
    if textbox1_idx < len(slide.shapes):
        shape1 = slide.shapes[textbox1_idx]
        if hasattr(shape1, 'text_frame') and shape1.has_text_frame:
            for para in shape1.text_frame.paragraphs:
                for run in para.runs:
                    if run.font.size:
                        result['textbox1_font_size'] = run.font.size.pt
                        break
                if result['textbox1_font_size'] is not None:
                    break
    if textbox2_idx < len(slide.shapes):
        shape2 = slide.shapes[textbox2_idx]
        if hasattr(shape2, 'text_frame') and shape2.has_text_frame:
            for para in shape2.text_frame.paragraphs:
                for run in para.runs:
                    if run.font.size:
                        result['textbox2_font_size'] = run.font.size.pt
                        break
                if result['textbox2_font_size'] is not None:
                    break
    return result

def get_pptx_table_info__f4287042fa68d8dbaeefa457a06c60a3(env, config):
    """
    Extract table information from a PowerPoint file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM file path) and 'slide_index' (0-based)

    Returns:
        dict: Table information including existence, rows, and columns
    """
    file_path = config.get('path')
    slide_index = config.get('slide_index', 0)
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'has_table': False, 'rows': 0, 'cols': 0}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        if slide_index >= len(prs.slides):
            return {'has_table': False, 'rows': 0, 'cols': 0}
        slide = prs.slides[slide_index]
        for shape in slide.shapes:
            if shape.shape_type == MSO_SHAPE_TYPE.TABLE:
                table = shape.table
                return {'has_table': True, 'rows': len(table.rows), 'cols': len(table.columns)}
        return {'has_table': False, 'rows': 0, 'cols': 0}
    finally:
        os.unlink(tmp_path)

def get_pptx_file__dba582db9f285ebba56893a94f5be30c(env, config: Dict[str, Any]) -> str:
    """
    Get PPTX file from VM and save to cache.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Local file path to the downloaded PPTX file
    """
    vm_path = config['path']
    file_bytes = env.controller.get_file(vm_path)
    if not file_bytes:
        return None
    dest_filename = os.path.basename(vm_path)
    cache_path = os.path.join(env.cache_dir, dest_filename)
    os.makedirs(env.cache_dir, exist_ok=True)
    with open(cache_path, 'wb') as f:
        f.write(file_bytes)
    return cache_path

def get_impress_slide_text_font__69500f28(env, config):
    """Extract text and font from specified slide placeholder.

    Args:
        env: DesktopEnv instance
        config: Dict with 'path', 'slide_idx', 'placeholder_idx'

    Returns:
        Dict with 'text' and 'font' keys
    """
    ppt_path = config.get('path')
    slide_idx = config.get('slide_idx', 0)
    placeholder_idx = config.get('placeholder_idx', 0)
    local_path = get_vm_file(env, {'path': ppt_path, 'dest': os.path.basename(ppt_path)})
    prs = Presentation(local_path)
    if slide_idx >= len(prs.slides):
        return {'text': '', 'font': ''}
    slide = prs.slides[slide_idx]
    target_shape = None
    for shape in slide.shapes:
        if shape.is_placeholder:
            ph_type = shape.placeholder_format.type
            if ph_type == 4 or (hasattr(shape, 'name') and 'subtitle' in shape.name.lower()):
                target_shape = shape
                break
    if target_shape is None:
        placeholders = []
        for shape in slide.shapes:
            if shape.is_placeholder and hasattr(shape, 'text_frame'):
                placeholders.append(shape)
        if placeholder_idx < len(placeholders):
            target_shape = placeholders[placeholder_idx]
    if target_shape is None:
        return {'text': '', 'font': ''}
    text = target_shape.text
    font_name = ''
    if target_shape.text_frame and target_shape.text_frame.paragraphs:
        for para in target_shape.text_frame.paragraphs:
            for run in para.runs:
                if run.text.strip() and run.font.name:
                    font_name = run.font.name
                    break
            if font_name:
                break
    return {'text': text, 'font': font_name}

