def get_pptx_slide_images__90b10b24565298567c91143461f807ac(env, config: Dict):
    """Extract slide count, image information, and text boxes from PowerPoint file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the PPTX file

    Returns:
        dict: {
            'slide_count': int,
            'slides': [
                {
                    'slide_idx': int,
                    'images': [{'image_name': str}, ...],
                    'text_boxes': [{'text': str}, ...]
                }, ...
            ]
        }
    """
    file_path = config['path']
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'slide_count': 0, 'slides': []}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide_count = len(prs.slides)
        slides = []
        for (slide_idx, slide) in enumerate(prs.slides):
            slide_data = {'slide_idx': slide_idx, 'images': [], 'text_boxes': []}
            for shape in slide.shapes:
                if shape.shape_type == 13:
                    try:
                        image_part = shape.image.part
                        partname = image_part.partname
                        full_filename = os.path.basename(partname)
                        base_name = os.path.splitext(full_filename)[0]
                        slide_data['images'].append({'image_name': base_name})
                    except:
                        slide_data['images'].append({'image_name': 'unknown'})
                elif hasattr(shape, 'text_frame'):
                    try:
                        text = shape.text_frame.text.strip()
                        if text:
                            slide_data['text_boxes'].append({'text': text})
                    except:
                        pass
            slides.append(slide_data)
        return {'slide_count': slide_count, 'slides': slides}
    finally:
        os.unlink(tmp_path)

