def get_pptx_paragraph_level__6990e537(env, config):
    """
    Get the indentation level of a specific paragraph in a PowerPoint slide.

    Args:
        env: Environment object
        config: Configuration dict with:
            - path: Path to PPTX file in VM
            - dest: Destination filename for local copy
            - slide_index: 0-indexed slide number
            - shape_index: 0-indexed shape number
            - paragraph_index: 0-indexed paragraph number

    Returns:
        int: Indentation level of the paragraph (0 = no indent, 1 = first level indent, etc.)
    """
    pptx_path = config.get('path')
    dest = config.get('dest')
    slide_index = int(config.get('slide_index', 0))
    shape_index = int(config.get('shape_index', 0))
    paragraph_index = int(config.get('paragraph_index', 0))
    pptx_file_localhost_path = get_vm_file(env, {'path': pptx_path, 'dest': dest})
    prs = Presentation(pptx_file_localhost_path)
    if slide_index >= len(prs.slides):
        return None
    slide = prs.slides[slide_index]
    if shape_index >= len(slide.shapes):
        return None
    shape = slide.shapes[shape_index]
    if not hasattr(shape, 'text_frame'):
        return None
    paragraphs = shape.text_frame.paragraphs
    if paragraph_index >= len(paragraphs):
        return None
    paragraph = paragraphs[paragraph_index]
    return paragraph.level

