def get_pptx_orientation__ac13100cf920bd3bbc93b65b566bf0cf(env, config):
    """
    Get the orientation of a PowerPoint presentation.

    Args:
        env: Desktop environment instance
        config: Configuration dict with 'path' key

    Returns:
        str: 'portrait' if width < height, 'landscape' otherwise
    """
    try:
        import tempfile
        import os
        file_bytes = env.controller.get_file(config['path'])
        if not file_bytes:
            logger.error(f"Failed to retrieve file from {config['path']}")
            return 'unknown'
        with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        try:
            prs = Presentation(tmp_path)
            slide_width = prs.slide_width
            slide_height = prs.slide_height
            if slide_width < slide_height:
                orientation = 'portrait'
            else:
                orientation = 'landscape'
            return orientation
        finally:
            os.unlink(tmp_path)
    except Exception as e:
        logger.error(f'Error getting presentation orientation: {e}')
        return 'unknown'

def get_pptx_slide_text__cbc02f6c8a7cc0adbfd3cf07b5015d49(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract text and formatting from a PowerPoint slide.
    
    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key for the PPTX file path
        
    Returns:
        Dictionary containing slide text and formatting information
    """
    file_path = config.get('path')
    if not file_path:
        return {'error': 'No file path provided'}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'error': 'Failed to retrieve file from VM'}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        result = {'slides': [], 'total_slides': len(prs.slides)}
        for (slide_idx, slide) in enumerate(prs.slides):
            slide_info = {'slide_index': slide_idx, 'shapes': []}
            for shape in slide.shapes:
                if hasattr(shape, 'text_frame'):
                    shape_data = {'text': shape.text, 'runs': []}
                    for paragraph in shape.text_frame.paragraphs:
                        for run in paragraph.runs:
                            if run.text.strip():
                                run_info = {'text': run.text, 'font_name': run.font.name, 'font_size': run.font.size.pt if run.font.size else None, 'bold': run.font.bold, 'italic': run.font.italic}
                                if run.font.color and run.font.color.type == 1:
                                    rgb = run.font.color.rgb
                                    run_info['color'] = {'r': rgb[0], 'g': rgb[1], 'b': rgb[2]}
                                shape_data['runs'].append(run_info)
                    if shape_data['runs']:
                        slide_info['shapes'].append(shape_data)
            result['slides'].append(slide_info)
        return result
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

