def get_pptx_font_and_color__48b49d333bcd59b8d855ad4d7a6aa3a8(env, config: Dict):
    """Extract font name and color of all text runs in the PowerPoint presentation.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the PPTX file

    Returns:
        Dict with font and color status information for all text runs
    """
    file_path = config['path']
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'all_target_font_and_green': False, 'total_runs': 0, 'target_font_runs': 0, 'green_runs': 0}
    target_font = config.get('target_font', 'Arial')
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        total_runs = 0
        target_font_runs = 0
        green_runs = 0
        both_runs = 0
        for slide in prs.slides:
            for shape in slide.shapes:
                if hasattr(shape, 'text_frame'):
                    for paragraph in shape.text_frame.paragraphs:
                        for run in paragraph.runs:
                            total_runs += 1
                            is_target_font = run.font.name == target_font
                            is_green = False
                            if hasattr(run.font.color, 'rgb'):
                                rgb = run.font.color.rgb
                                if rgb[1] > 200 and rgb[0] < 100 and (rgb[2] < 100):
                                    is_green = True
                            if is_target_font:
                                target_font_runs += 1
                            if is_green:
                                green_runs += 1
                            if is_target_font and is_green:
                                both_runs += 1
                if shape.shape_type == 19:
                    table = shape.table
                    for row in table.rows:
                        for cell in row.cells:
                            for paragraph in cell.text_frame.paragraphs:
                                for run in paragraph.runs:
                                    total_runs += 1
                                    is_target_font = run.font.name == target_font
                                    is_green = False
                                    if hasattr(run.font.color, 'rgb'):
                                        rgb = run.font.color.rgb
                                        if rgb[1] > 200 and rgb[0] < 100 and (rgb[2] < 100):
                                            is_green = True
                                    if is_target_font:
                                        target_font_runs += 1
                                    if is_green:
                                        green_runs += 1
                                    if is_target_font and is_green:
                                        both_runs += 1
        all_target_font_and_green = total_runs > 0 and total_runs == both_runs
        return {'all_target_font_and_green': all_target_font_and_green, 'total_runs': total_runs, 'target_font_runs': target_font_runs, 'green_runs': green_runs, 'both_runs': both_runs}
    finally:
        os.unlink(tmp_path)

