def get_pptx_title_alignment__07eb1a4e7695007b017e51f2f57702d1(env, config: Dict):
    """Extract title text alignment from PowerPoint file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to PPTX file on VM

    Returns:
        dict: {"alignment": str} - alignment value ("LEFT", "CENTER", "RIGHT", etc.)
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'alignment': 'UNKNOWN'}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        if len(prs.slides) == 0:
            return {'alignment': 'UNKNOWN'}
        slide = prs.slides[0]
        for shape in slide.shapes:
            if hasattr(shape, 'text_frame') and shape.has_text_frame:
                if shape.text.strip() == 'The History of Art':
                    para = shape.text_frame.paragraphs[0]
                    alignment = para.alignment
                    if alignment is None:
                        return {'alignment': 'LEFT'}
                    elif alignment == PP_ALIGN.LEFT:
                        return {'alignment': 'LEFT'}
                    elif alignment == PP_ALIGN.CENTER:
                        return {'alignment': 'CENTER'}
                    elif alignment == PP_ALIGN.RIGHT:
                        return {'alignment': 'RIGHT'}
                    elif alignment == PP_ALIGN.JUSTIFY:
                        return {'alignment': 'JUSTIFY'}
                    else:
                        return {'alignment': str(alignment)}
        return {'alignment': 'UNKNOWN'}
    finally:
        os.unlink(tmp_path)

