def get_pptx_slide1_title_color__333473c8(env, config):
    """Get font color of slide 1 title.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with pptx_path parameter

    Returns:
        tuple: RGB color tuple (r, g, b) or None
    """
    pptx_path = config.get('pptx_path', '/home/user/Desktop/39_2.pptx')
    local_path = get_vm_file(env, {'path': pptx_path, 'dest': os.path.basename(pptx_path)})
    prs = Presentation(local_path)
    if len(prs.slides) < 1:
        return None
    slide = prs.slides[0]
    for shape in slide.shapes:
        if hasattr(shape, 'is_placeholder') and shape.is_placeholder:
            if hasattr(shape, 'placeholder_format'):
                placeholder_type = shape.placeholder_format.type
                if placeholder_type == 1:
                    if hasattr(shape, 'text_frame') and shape.text_frame:
                        for para in shape.text_frame.paragraphs:
                            if para.runs:
                                first_run = para.runs[0]
                                if hasattr(first_run.font.color, 'rgb') and first_run.font.color.rgb:
                                    return first_run.font.color.rgb
    title_shape = None
    min_top = float('inf')
    for shape in slide.shapes:
        if shape.shape_type == MSO_SHAPE_TYPE.TEXT_BOX or shape.shape_type == MSO_SHAPE_TYPE.PLACEHOLDER:
            if hasattr(shape, 'text_frame') and shape.text_frame:
                if shape.top < min_top:
                    min_top = shape.top
                    title_shape = shape
    if title_shape and hasattr(title_shape, 'text_frame') and title_shape.text_frame:
        for para in title_shape.text_frame.paragraphs:
            if para.runs:
                first_run = para.runs[0]
                if hasattr(first_run.font.color, 'rgb') and first_run.font.color.rgb:
                    return first_run.font.color.rgb
    return None

def get_pptx_formatting__142e2add(env, config: dict):
    """Extract formatting state for text in specified slides.
    
    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'dest', 'slide_indices'
        
    Returns:
        dict: Formatting information for all text runs in specified slides
    """
    pptx_path = config.get('path', '/home/user/Desktop/43_1.pptx')
    dest = config.get('dest', '43_1.pptx')
    slide_indices = config.get('slide_indices', [])
    local_path = get_vm_file(env, {'path': pptx_path, 'dest': dest})
    prs = Presentation(local_path)
    formatting_data = {}
    for slide_idx in slide_indices:
        if slide_idx >= len(prs.slides):
            continue
        slide = prs.slides[slide_idx]
        for (shape_idx, shape) in enumerate(slide.shapes):
            if not hasattr(shape, 'text_frame'):
                continue
            for (para_idx, para) in enumerate(shape.text_frame.paragraphs):
                for (run_idx, run) in enumerate(para.runs):
                    key = (slide_idx, shape_idx, para_idx, run_idx)
                    formatting_data[key] = {'text': run.text, 'bold': run.font.bold, 'italic': run.font.italic, 'underline': run.font.underline, 'size': run.font.size.pt if run.font.size else None, 'color': run.font.color.rgb if hasattr(run.font.color, 'rgb') else None, 'alignment': para.alignment}
    return formatting_data

def get_pptx_slide_info__041e12c9(env, config: dict) -> Dict[str, Any]:
    """
    Extract slide information from a PPTX file.

    This getter extracts slide hashes to verify slide ordering and removal.
    The verification is done by comparing current slide hashes with the expected
    configuration passed through the evaluator.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dictionary with slide information including hashes for verification
    """
    pptx_path = config.get('path', '')
    if not pptx_path:
        return {'error': 'No path provided'}

    def extract_slide_info(prs):
        """Extract slide information from a presentation."""
        slides_info = []
        for (slide_idx, slide) in enumerate(prs.slides):
            text_content = []
            for shape in slide.shapes:
                if hasattr(shape, 'text') and shape.text.strip():
                    text_content.append(shape.text.strip())
            text_combined = '||'.join(text_content)
            text_hash = hashlib.md5(text_combined.encode('utf-8')).hexdigest()
            slides_info.append({'index': slide_idx, 'text_content': text_content, 'text_hash': text_hash})
        return slides_info
    try:
        file_content = env.controller.get_file(pptx_path)
        if not file_content:
            return {'error': f'Could not read file: {pptx_path}'}
        import tempfile
        import os
        with tempfile.NamedTemporaryFile(delete=False, suffix='.pptx') as tmp:
            tmp.write(file_content)
            tmp_path = tmp.name
        prs = Presentation(tmp_path)
        current_slides = extract_slide_info(prs)
        total_slides = len(prs.slides)
        os.unlink(tmp_path)
        return {'total_slides': total_slides, 'slides': current_slides, 'slide_hashes': [s['text_hash'] for s in current_slides]}
    except Exception as e:
        return {'error': str(e)}

def get_pptx_all_font_sizes__9e62713c(env, config):
    """Extract all unique font sizes used in a PowerPoint presentation.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'ppt_file_path' key

    Returns:
        set: Set of font sizes (in points) used in the presentation
    """
    ppt_file_path = config['ppt_file_path']
    ppt_file_localhost_path = get_vm_file(env, {'path': ppt_file_path, 'dest': os.path.split(ppt_file_path)[-1]})
    prs = Presentation(ppt_file_localhost_path)
    sizes_used = set()
    for slide in prs.slides:
        for shape in slide.shapes:
            if hasattr(shape, 'text_frame'):
                for paragraph in shape.text_frame.paragraphs:
                    for run in paragraph.runs:
                        if run.font.size:
                            size_in_pt = run.font.size.pt
                            sizes_used.add(size_in_pt)
    return sizes_used

