def get_pptx_title_underline__083196038656263df87bdc3dda6b4a22(env, config: dict):
    """Extract whether the title text is underlined from a PowerPoint file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key for the PPTX file path

    Returns:
        dict: {'is_underlined': bool} - True if ALL runs in the title are underlined, False otherwise
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'is_underlined': False}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        if len(prs.slides) == 0:
            return {'is_underlined': False}
        slide = prs.slides[0]
        title_shape = None
        for shape in slide.shapes:
            if shape.is_placeholder:
                try:
                    if shape.placeholder_format.type == PP_PLACEHOLDER.TITLE or shape.placeholder_format.type == PP_PLACEHOLDER.CENTERED_TITLE:
                        title_shape = shape
                        break
                except:
                    pass
            elif hasattr(shape, 'text_frame') and shape.text_frame is not None:
                if title_shape is None:
                    title_shape = shape
        if title_shape is None or not hasattr(title_shape, 'text_frame'):
            return {'is_underlined': False}
        all_underlined = True
        has_text_runs = False
        for para in title_shape.text_frame.paragraphs:
            for run in para.runs:
                if run.text.strip():
                    has_text_runs = True
                    if run.font.underline is not True:
                        all_underlined = False
                        break
            if not all_underlined:
                break
        if not has_text_runs:
            return {'is_underlined': False}
        return {'is_underlined': all_underlined}
    finally:
        os.unlink(tmp_path)

def get_pptx_text_alignment__59dc9da8(env, config):
    """Extract text alignment of specific shapes.

    Args:
        env: DesktopEnv instance
        config: Dict with keys:
            - pptx_path: Path to PPTX file on VM
            - slide_index: 0-based slide index
            - shape_indices: List of shape indices to check

    Returns:
        List of alignment values (as integers) for each shape
    """
    pptx_path = config['pptx_path']
