def get_pptx_text_colors__1f4273f47ac63784ed95be4edfc1a7eb(env, config: dict) -> Dict[str, Any]:
    """Extract text colors from specific shapes in a PowerPoint slide.

    This getter validates that ALL runs in a text element have the same color,
    ensuring the entire text element is uniformly colored as required by the task.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
                - 'path': VM file path to the .pptx file
                - 'slide_index': 0-based slide index (0 corresponds to "slide 1" in UI)
                - 'shape_indices': List of shape indices to check (e.g., [0, 1, 4])

    Returns:
        Dict mapping shape index (as string) to:
        - RGB color string (e.g., "FF0000" for red) if all runs have the same color
        - None if no color found or if runs have inconsistent colors

    Example return: {"0": "00008B", "1": "FF00FF", "4": "00FF00"}
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide_index = config.get('slide_index', 0)
        shape_indices = config.get('shape_indices', [])
        if slide_index >= len(prs.slides):
            return {}
        slide = prs.slides[slide_index]
        result = {}
        for shape_idx in shape_indices:
            if shape_idx >= len(slide.shapes):
                continue
            shape = slide.shapes[shape_idx]
            if hasattr(shape, 'text_frame'):
                colors_found = []
                for para in shape.text_frame.paragraphs:
                    for run in para.runs:
                        if hasattr(run.font, 'color') and run.font.color.type is not None:
                            try:
                                rgb = run.font.color.rgb
                                colors_found.append(str(rgb))
                            except:
                                pass
                if colors_found:
                    if all((c == colors_found[0] for c in colors_found)):
                        result[str(shape_idx)] = colors_found[0]
                    else:
                        result[str(shape_idx)] = None
        return result
    finally:
        os.unlink(tmp_path)

