def get_pptx_title_bold__d1beaadd6d4b46ef2ea10c1368a2c39c(env, config):
    """Check if the title text is bold in a PowerPoint presentation.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the PPTX file

    Returns:
        bool: True if all title text is bold, False otherwise
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return False
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        if len(prs.slides) == 0:
            return False
        slide = prs.slides[0]
        if not hasattr(slide.shapes, 'title') or slide.shapes.title is None:
            return False
        title_shape = slide.shapes.title
        if not hasattr(title_shape, 'text_frame'):
            return False
        for para in title_shape.text_frame.paragraphs:
            if para.runs:
                for run in para.runs:
                    is_bold = run.font.bold
                    if is_bold is None or not is_bold:
                        return False
        return True
    finally:
        os.unlink(tmp_path)

def get_slide_count__29ef06e2(env, config):
    """Extract slide count from a docx file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        int: The slide count number
    """
    path = config.get('path', '/home/user/Desktop/slide_count.docx')
    file_bytes = env.controller.get_file(path)
    if not file_bytes:
        return -1
    import os
    cache_path = os.path.join(env.cache_dir, 'slide_count.docx')
    with open(cache_path, 'wb') as f:
        f.write(file_bytes)
    try:
        doc = Document(cache_path)
        text = ' '.join([p.text for p in doc.paragraphs])
        import re
        numbers = re.findall('\\d+', text)
        if numbers:
            return int(numbers[0])
        return -1
    except:
        return -1

