def get_slide_summary_from_docx__ad193ef5756ae344b25ad0ec2621d4b0(env, config: Dict):
    """Extract slide summary (number and title pairs) from a Word document.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the docx file on VM

    Returns:
        List of tuples (slide_number, title) extracted from the document
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return []
    with tempfile.NamedTemporaryFile(suffix='.docx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        doc = Document(tmp_path)
        summary_entries = []
        for para in doc.paragraphs:
            text = para.text.strip()
            if not text:
                continue
            match = re.match('(?:Slide\\s+)?(\\d+)\\s*[:\\-\\.]\\s*(.+)', text, re.IGNORECASE)
            if match:
                slide_num = int(match.group(1))
                title = match.group(2).strip()
                summary_entries.append((slide_num, title))
        return summary_entries
    finally:
        os.unlink(tmp_path)

