def get_pptx_textbox_fonts__ce3d4c14(env, config):
    """Extract font sizes from two specific textboxes in a PowerPoint slide.
    
    Args:
        env: DesktopEnv instance
        config: Configuration dict with parameters:
            - ppt_file_path: Path to PPTX file on VM
            - slide_index: Slide index (0-based)
            - textbox1_shape_idx: First textbox shape index
            - textbox2_shape_idx: Second textbox shape index
            
    Returns:
        dict: {"textbox1_font_size": float, "textbox2_font_size": float}
    """
    ppt_file_path = config['ppt_file_path']
    slide_index = int(config['slide_index'])
    textbox1_idx = int(config['textbox1_shape_idx'])
    textbox2_idx = int(config['textbox2_shape_idx'])
    ppt_file_localhost = get_vm_file(env, {'path': ppt_file_path, 'dest': os.path.basename(ppt_file_path)})
    prs = Presentation(ppt_file_localhost)
    if slide_index >= len(prs.slides):
        return {'error': f'Slide index {slide_index} out of range'}
    slide = prs.slides[slide_index]
    result = {'textbox1_font_size': None, 'textbox2_font_size': None}
    if textbox1_idx < len(slide.shapes):
        shape1 = slide.shapes[textbox1_idx]
        if hasattr(shape1, 'text_frame') and shape1.has_text_frame:
            for para in shape1.text_frame.paragraphs:
                for run in para.runs:
                    if run.font.size:
                        result['textbox1_font_size'] = run.font.size.pt
                        break
                if result['textbox1_font_size'] is not None:
                    break
    if textbox2_idx < len(slide.shapes):
        shape2 = slide.shapes[textbox2_idx]
        if hasattr(shape2, 'text_frame') and shape2.has_text_frame:
            for para in shape2.text_frame.paragraphs:
                for run in para.runs:
                    if run.font.size:
                        result['textbox2_font_size'] = run.font.size.pt
                        break
                if result['textbox2_font_size'] is not None:
                    break
    return result

