def get_ppt_title_formatting__316703206f4897c9466fab9daa4f34be(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract title formatting information from specified slides.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM file path) and 'slides' (list of slide indices)

    Returns:
        Dict mapping slide indices to their title formatting details
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide_indices = config.get('slides', [])
        result = {}
        for slide_idx in slide_indices:
            if slide_idx >= len(prs.slides):
                continue
            slide = prs.slides[slide_idx]
            title_info = None
            for shape in slide.shapes:
                if hasattr(shape, 'text') and hasattr(shape, 'text_frame') and shape.text.strip():
                    if shape.text_frame.paragraphs:
                        para = shape.text_frame.paragraphs[0]
                        if para.runs:
                            run = para.runs[0]
                            color = None
                            if hasattr(run.font.color, 'rgb'):
                                rgb = run.font.color.rgb
                                color = (rgb[0], rgb[1], rgb[2])
                            title_info = {'text': shape.text.strip(), 'color': color, 'bold': run.font.bold, 'italic': run.font.italic, 'underline': run.font.underline}
                            break
            if title_info:
                result[slide_idx] = title_info
        return result
    finally:
        os.unlink(tmp_path)

