def get_pptx_slide_title_formatting__462ff7b5f11ab01598afea6ebe6b8637(env, config):
    """Extract title text and formatting information for a specific slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'slide_index' keys

    Returns:
        dict: {'title_text': str, 'first_run_bold': bool, 'first_run_text': str}
    """
    file_path = config.get('path')
    slide_index = config.get('slide_index', 0)
    if not file_path:
        return {}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    try:
        with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        prs = Presentation(tmp_path)
        if slide_index >= len(prs.slides):
            return {}
        slide = prs.slides[slide_index]
        for shape in slide.shapes:
            if hasattr(shape, 'text_frame') and hasattr(shape, 'placeholder_format'):
                try:
                    if shape.placeholder_format.type == 1:
                        title_text = shape.text.strip()
                        first_run_bold = False
                        first_run_text = ''
                        if shape.text_frame.paragraphs:
                            first_para = shape.text_frame.paragraphs[0]
                            if first_para.runs:
                                first_run = first_para.runs[0]
                                first_run_text = first_run.text
                                first_run_bold = first_run.font.bold == True
                        return {'title_text': title_text, 'first_run_bold': first_run_bold, 'first_run_text': first_run_text}
                except:
                    pass
        return {}
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

