def get_pptx_slide_images__82ff5b7c65e814d931f87d5c248a48c2(env, config: Dict):
    """Extract slide count, image hashes, and slide content from PowerPoint file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the PPTX file

    Returns:
        dict: {
            'slide_count': int,
            'images': [{'slide_idx': int, 'image_hash': str}, ...],
            'slide_shapes': [{'slide_idx': int, 'shape_types': [int, ...]}, ...]
        }
    """
    file_path = config['path']
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'slide_count': 0, 'images': [], 'slide_shapes': []}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide_count = len(prs.slides)
        images = []
        slide_shapes = []
        for (slide_idx, slide) in enumerate(prs.slides):
            shape_types = []
            for shape in slide.shapes:
                shape_types.append(shape.shape_type)
                if shape.shape_type == 13:
                    try:
                        image_blob = shape.image.blob
                        image_hash = hashlib.md5(image_blob).hexdigest()
                        images.append({'slide_idx': slide_idx, 'image_hash': image_hash})
                    except:
                        images.append({'slide_idx': slide_idx, 'image_hash': 'unknown'})
            slide_shapes.append({'slide_idx': slide_idx, 'shape_types': shape_types})
        return {'slide_count': slide_count, 'images': images, 'slide_shapes': slide_shapes}
    finally:
        os.unlink(tmp_path)

