def get_pptx_image_info__e6b29cfda7e055fe712654f4e89e7782(env, config):
    """Extract image information from a PowerPoint slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'slide_index', and optionally 'image_index'

    Returns:
        dict: Image information including size, position, and image metadata
    """
    file_path = config.get('path')
    slide_index = config.get('slide_index', 0)
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        if slide_index >= len(prs.slides):
            return {}
        slide = prs.slides[slide_index]
        images = [shape for shape in slide.shapes if shape.shape_type == 13]
        if not images:
            return {'image_count': 0}
        images_info = []
        for img in images:
            width_cm = img.width / 360000
            height_cm = img.height / 360000
            image_metadata = {}
            try:
                image_blob = img.image.blob
                image_checksum = hashlib.md5(image_blob).hexdigest()
                pil_img = Image.open(BytesIO(image_blob))
                (pixel_width, pixel_height) = pil_img.size
                image_metadata = {'checksum': image_checksum, 'pixel_width': pixel_width, 'pixel_height': pixel_height}
            except:
                image_metadata = {'checksum': None, 'pixel_width': None, 'pixel_height': None}
            images_info.append({'width_cm': width_cm, 'height_cm': height_cm, 'left': img.left, 'top': img.top, 'metadata': image_metadata})
        return {'image_count': len(images), 'images': images_info}
    finally:
        os.unlink(tmp_path)

