def get_pptx_second_textbox_size__ac2dc72f6025646badf2a45040c40720(env, config: Dict[str, Any]) -> float:
    """Extract font size from the second textbox on a slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - path: VM path to the PPTX file
            - slide_index: 0-based slide index

    Returns:
        Font size in points (or None if not found)
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return None
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide_index = config.get('slide_index', 0)
        if slide_index >= len(prs.slides):
            return None
        slide = prs.slides[slide_index]
        textboxes = []
        for shape in slide.shapes:
            if hasattr(shape, 'text_frame') and shape.text_frame.text.strip():
                textboxes.append(shape)
        if len(textboxes) < 2:
            return None
        second_textbox = textboxes[1]
        for paragraph in second_textbox.text_frame.paragraphs:
            for run in paragraph.runs:
                if run.font.size:
                    return run.font.size.pt
        return None
    finally:
        os.unlink(tmp_path)

