def get_pptx_slide1_title_font_size__bf5cbc9b(env, config):
    """Get font size of slide 1 title.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with pptx_path parameter

    Returns:
        float: Font size in points or None
    """
    pptx_path = config.get('pptx_path', '/home/user/Desktop/39_2.pptx')
    local_path = get_vm_file(env, {'path': pptx_path, 'dest': os.path.basename(pptx_path)})
    prs = Presentation(local_path)
    if len(prs.slides) < 1:
        return None
    slide = prs.slides[0]
    if hasattr(slide, 'shapes') and hasattr(slide.shapes, 'title'):
        title_shape = slide.shapes.title
        if title_shape is not None and hasattr(title_shape, 'text_frame'):
            for para in title_shape.text_frame.paragraphs:
                if para.runs:
                    first_run = para.runs[0]
                    if first_run.font.size:
                        return first_run.font.size.pt
    from pptx.enum.shapes import PP_PLACEHOLDER
    for shape in slide.shapes:
        if hasattr(shape, 'is_placeholder') and shape.is_placeholder:
            if hasattr(shape, 'placeholder_format'):
                if shape.placeholder_format.type == PP_PLACEHOLDER.TITLE:
                    if hasattr(shape, 'text_frame'):
                        for para in shape.text_frame.paragraphs:
                            if para.runs:
                                first_run = para.runs[0]
                                if first_run.font.size:
                                    return first_run.font.size.pt
    return None

def get_pptx_slide_content__adaf3338(env, config):
    """Extract all text content from a specific slide including subtitle.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'slide_index' keys

    Returns:
        dict: Content including title and subtitle
    """
    filepath = config.get('path', '')
    slide_index = config.get('slide_index', 0)
    try:
        prs = Presentation(filepath)
        if slide_index < 0 or slide_index >= len(prs.slides):
            return {'title': '', 'subtitle': '', 'all_text': []}
        slide = prs.slides[slide_index]
        title = ''
        subtitle = ''
        if slide.shapes.title:
            title = slide.shapes.title.text.strip()
        text_shapes = [s for s in slide.shapes if hasattr(s, 'text') and s.text.strip()]
        for (i, shape) in enumerate(text_shapes):
            text = shape.text.strip()
            if i == 0 and slide.shapes.title and (shape == slide.shapes.title):
                continue
            elif i <= 1 and hasattr(shape, 'placeholder_format'):
                if text and text != title:
                    subtitle = text
                    break
        if not subtitle:
            for shape in slide.shapes:
                if hasattr(shape, 'text'):
                    text = shape.text.strip()
                    if text and text != title and (shape != slide.shapes.title):
                        subtitle = text
                        break
        all_text = [shape.text.strip() for shape in slide.shapes if hasattr(shape, 'text') and shape.text.strip()]
        return {'title': title, 'subtitle': subtitle, 'all_text': all_text}
    except Exception as e:
        return {'title': '', 'subtitle': '', 'all_text': [], 'error': str(e)}

def get_pptx_file__47c310f496e67776b442944f1eb6cfb0(env, config: Dict[str, Any]) -> str:
    """
    Get PPTX file from VM and save to cache.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Local file path to the downloaded PPTX file
    """
    vm_path = config['path']
    file_bytes = env.controller.get_file(vm_path)
    if not file_bytes:
        return None
    dest_filename = os.path.basename(vm_path)
    cache_path = os.path.join(env.cache_dir, dest_filename)
    os.makedirs(env.cache_dir, exist_ok=True)
    with open(cache_path, 'wb') as f:
        f.write(file_bytes)
    return cache_path

def get_pptx_table_column__68c4aac31af1e0367d3d2b8072ceb3c6(env, config: dict):
    """Extract a specific column from a table in a PowerPoint slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with keys:
            - path: Path to the .pptx file on VM
            - slide_index: Index of the slide (0-based)
            - col_index: Index of the column to extract (0-based)
            - start_row: Starting row index (0-based, default 0)

    Returns:
        List of cell values as strings
    """
    file_path = config['path']
    slide_index = config['slide_index']
    col_index = config['col_index']
    start_row = config.get('start_row', 0)
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return []
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        if slide_index >= len(prs.slides):
            return []
        slide = prs.slides[slide_index]
        for shape in slide.shapes:
            if shape.has_table:
                table = shape.table
                column_values = []
                for row_idx in range(start_row, len(table.rows)):
                    row = table.rows[row_idx]
                    if col_index < len(row.cells):
                        column_values.append(row.cells[col_index].text)
                    else:
                        return []
                return column_values
        return []
    finally:
        os.unlink(tmp_path)

def get_slide_bg_color__77e3a30f18ab24b0ea45cfea7905a718(env, config: Dict[str, Any]) -> Optional[Tuple[int, int, int]]:
    """Extract background color from a specific slide in a PowerPoint file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - path: VM path to the PPTX file
            - slide_index: Index of the slide to check (0-based)

    Returns:
        RGB tuple (r, g, b) if solid fill background exists, None otherwise
    """
    file_path = config.get('path')
    slide_index = config.get('slide_index', 0)
    if not file_path:
        return None
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return None
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        if slide_index >= len(prs.slides):
            return None
        slide = prs.slides[slide_index]
        fill = slide.background.fill
        if fill.type == 1:
            rgb = fill.fore_color.rgb
            return (rgb[0], rgb[1], rgb[2])
        elif fill.type == 5:
            master_fill = slide.slide_layout.slide_master.background.fill
            if master_fill.type == 1:
                rgb = master_fill.fore_color.rgb
                return (rgb[0], rgb[1], rgb[2])
        return None
    finally:
        os.unlink(tmp_path)

