def get_pptx_table_row__afa9880dff96301acae7d2df625994a4(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract text from a specific row in a PowerPoint table.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with keys:
            - path: Path to the PPTX file on VM
            - slide_index: 0-based slide index
            - table_index: Index of table in slide (0 for first table)
            - row_index: Row index to extract

    Returns:
        Dict with row cell texts as a list
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'row_cells': []}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide_index = config.get('slide_index', 0)
        table_index = config.get('table_index', 0)
        row_index = config.get('row_index', 0)
        if slide_index >= len(prs.slides):
            return {'row_cells': []}
        slide = prs.slides[slide_index]
        tables = [shape for shape in slide.shapes if shape.has_table]
        if table_index >= len(tables):
            return {'row_cells': []}
        table = tables[table_index].table
        if row_index >= len(table.rows):
            return {'row_cells': []}
        row = table.rows[row_index]
        row_cells = [cell.text.strip() for cell in row.cells]
        return {'row_cells': row_cells}
    finally:
        os.unlink(tmp_path)

