def get_pptx_paragraph_level__2d4ab20f(env, config: Dict):
    """
    Get the indentation level(s) of specific paragraph(s) in a PowerPoint shape.

    This function supports two modes:
    1. Single paragraph: If 'paragraph_index' is provided, returns a single int (the level)
    2. Multiple paragraphs: If 'paragraph_indices' is provided, returns a list of ints (the levels)

    Args:
        env: Environment object
        config: Dict with the following keys:
            - path: Path to the PPTX file on VM
            - dest: Destination filename for local copy
            - slide_index: Index of the slide (0-indexed)
            - shape_index: Index of the shape containing the text (0-indexed)
            - paragraph_index: (Optional) Single paragraph index to check
            - paragraph_indices: (Optional) List of paragraph indices to check

    Returns:
        int or List[int]: The indentation level(s) of the specified paragraph(s)
    """
    ppt_path = config.get('path')
    dest = config.get('dest')
    slide_index = config.get('slide_index', 0)
    shape_index = config.get('shape_index', 0)
    paragraph_index = config.get('paragraph_index')
    paragraph_indices = config.get('paragraph_indices')
    ppt_localhost = get_vm_file(env, {'path': ppt_path, 'dest': dest})
    prs = Presentation(ppt_localhost)
    if slide_index >= len(prs.slides):
        return None
    slide = prs.slides[slide_index]
    if shape_index >= len(slide.shapes):
        return None
    shape = slide.shapes[shape_index]
    if not hasattr(shape, 'text_frame'):
        return None
    if paragraph_indices is not None:
        levels = []
        for para_idx in paragraph_indices:
            if para_idx >= len(shape.text_frame.paragraphs):
                return None
            paragraph = shape.text_frame.paragraphs[para_idx]
            levels.append(paragraph.level)
        return levels
    if paragraph_index is not None:
        if paragraph_index >= len(shape.text_frame.paragraphs):
            return None
        paragraph = shape.text_frame.paragraphs[paragraph_index]
        return paragraph.level
    return None

def get_pptx_all_text_colors__595f03695c0a03d2b875aa787f5e6f3f(env, config: Dict):
    """Check if all text in the presentation uses a specific color.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: Dictionary with 'total_runs' and 'blue_runs' counts
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'total_runs': 0, 'blue_runs': 0}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        total_runs = 0
        blue_runs = 0
        for slide in prs.slides:
            for shape in slide.shapes:
                if hasattr(shape, 'text_frame'):
                    for paragraph in shape.text_frame.paragraphs:
                        for run in paragraph.runs:
                            if run.text.strip():
                                total_runs += 1
                                is_blue = False
                                if hasattr(run.font.color, 'rgb') and run.font.color.rgb is not None:
                                    try:
                                        (r, g, b) = run.font.color.rgb
                                        if b >= 200 and b > max(r, g) * 1.5:
                                            is_blue = True
                                    except (AttributeError, TypeError):
                                        pass
                                if is_blue:
                                    blue_runs += 1
        return {'total_runs': total_runs, 'blue_runs': blue_runs}
    finally:
        os.unlink(tmp_path)

def get_pptx_table_dims__57687221(env, config: dict):
    """Extract table dimensions from a specific slide in a PPTX file.
    
    Args:
        env: DesktopEnv instance
        config: Configuration dict with parameters:
            - ppt_file_path: Path to PPTX file on VM
            - slide_index: Index of slide to check (0-based)
            - dest: Local destination filename
            
    Returns:
        dict: {"rows": int, "cols": int, "has_table": bool}
    """
    ppt_file_path = config['ppt_file_path']
    slide_index = int(config['slide_index'])
    dest = config.get('dest', os.path.basename(ppt_file_path))
    ppt_file_localhost_path = get_vm_file(env, {'path': ppt_file_path, 'dest': dest})
    prs = Presentation(ppt_file_localhost_path)
    if slide_index >= len(prs.slides):
        return {'has_table': False, 'rows': 0, 'cols': 0}
    slide = prs.slides[slide_index]
    from pptx.enum.shapes import MSO_SHAPE_TYPE
    for shape in slide.shapes:
        if shape.shape_type == MSO_SHAPE_TYPE.TABLE:
            table = shape.table
            return {'has_table': True, 'rows': len(table.rows), 'cols': len(table.columns)}
    return {'has_table': False, 'rows': 0, 'cols': 0}

def get_ppt_table_content__2c91f820c9951d53b92190cdccee21ec(env, config: dict):
    """Extract table content from a PowerPoint slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'slide_index' keys

    Returns:
        dict: Table content as nested lists, or empty dict if no table
    """
    pptx_path = config.get('path', '')
    slide_index = config.get('slide_index', 0)
    file_bytes = env.controller.get_file(pptx_path)
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        if slide_index >= len(prs.slides):
            return {}
        slide = prs.slides[slide_index]
        for shape in slide.shapes:
            if shape.shape_type == MSO_SHAPE_TYPE.TABLE:
                table = shape.table
                rows_data = []
                for row in table.rows:
                    row_data = []
                    for cell in row.cells:
                        row_data.append(cell.text.strip())
                    rows_data.append(row_data)
                return {'rows': len(table.rows), 'columns': len(table.columns), 'data': rows_data}
        return {}
    finally:
        os.unlink(tmp_path)

def get_pptx_title_font_size__563eb098efee78b8907522007f616471(env, config: dict):
    """Extract the font size of the title from a PowerPoint file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key for the PPTX file path

    Returns:
        dict: {'font_size_pt': float or None} - font size in points
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'font_size_pt': None}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        if len(prs.slides) == 0:
            return {'font_size_pt': None}
        slide = prs.slides[0]
        title_shape = None
        for shape in slide.shapes:
            if shape.is_placeholder:
                placeholder_format = shape.placeholder_format
                if placeholder_format.type == PP_PLACEHOLDER.TITLE:
                    title_shape = shape
                    break
        if title_shape is None or not hasattr(title_shape, 'text_frame'):
            return {'font_size_pt': None}
        for para in title_shape.text_frame.paragraphs:
            for run in para.runs:
                if run.text.strip():
                    if run.font.size is not None:
                        font_size_pt = run.font.size.pt
                        return {'font_size_pt': font_size_pt}
        return {'font_size_pt': None}
    finally:
        os.unlink(tmp_path)

def get_pptx_slide_text__a9fd446f20e0a78b6c6dec0497159b53(env, config):
    """
    Extract text from a specific shape on a specific slide in a PowerPoint file.

    Args:
        env: Environment object with controller access
        config: Dict containing:
            - path: Path to the PPTX file on VM
            - slide_index: Zero-based index of the slide
            - shape_index: Zero-based index of the shape

    Returns:
        str: The text content of the specified shape, or empty string if not found
    """
    pptx_path = config.get('path')
    slide_index = config.get('slide_index', 0)
    shape_index = config.get('shape_index', 0)
    if not pptx_path:
        logger.error('get_pptx_slide_text__a9fd446f20e0a78b6c6dec0497159b53: path not specified in config')
        return ''
    try:
        pptx_content = env.controller.get_file(pptx_path)
        if not pptx_content:
            logger.error(f'get_pptx_slide_text__a9fd446f20e0a78b6c6dec0497159b53: failed to read file at {pptx_path}')
            return ''
        with tempfile.NamedTemporaryFile(delete=False, suffix='.pptx') as tmp_file:
            tmp_path = tmp_file.name
            tmp_file.write(pptx_content)
        try:
            prs = Presentation(tmp_path)
            if slide_index >= len(prs.slides):
                logger.error(f'get_pptx_slide_text__a9fd446f20e0a78b6c6dec0497159b53: slide {slide_index} not found (only {len(prs.slides)} slides)')
                return ''
            slide = prs.slides[slide_index]
            if shape_index >= len(slide.shapes):
                logger.error(f'get_pptx_slide_text__a9fd446f20e0a78b6c6dec0497159b53: shape {shape_index} not found on slide {slide_index}')
                return ''
            shape = slide.shapes[shape_index]
            if hasattr(shape, 'text'):
                return shape.text.strip()
            else:
                logger.warning(f'get_pptx_slide_text__a9fd446f20e0a78b6c6dec0497159b53: shape {shape_index} on slide {slide_index} has no text')
                return ''
        finally:
            if os.path.exists(tmp_path):
                os.remove(tmp_path)
    except Exception as e:
        logger.error(f'get_pptx_slide_text__a9fd446f20e0a78b6c6dec0497159b53: Error reading PPTX: {e}')
        return ''

def get_pptx_subtitle_alignment__85233bdd8620d4027d793a907a6b6d06(env, config: dict):
    """Extract the text alignment of the subtitle from a PowerPoint file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key for the PPTX file path

    Returns:
        dict: {'alignment': str} - alignment type ('LEFT', 'CENTER', 'RIGHT', 'JUSTIFY', or 'UNKNOWN')
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'alignment': 'UNKNOWN'}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        if len(prs.slides) == 0:
            return {'alignment': 'UNKNOWN'}
        slide = prs.slides[0]
        subtitle_shape = None
        for shape in slide.shapes:
            if hasattr(shape, 'text') and 'Art is a diverse range' in shape.text:
                subtitle_shape = shape
                break
        if subtitle_shape is None or not hasattr(subtitle_shape, 'text_frame'):
            return {'alignment': 'UNKNOWN'}
        if len(subtitle_shape.text_frame.paragraphs) > 0:
            para = subtitle_shape.text_frame.paragraphs[0]
            align = para.alignment
            if align is None or align == PP_ALIGN.LEFT:
                alignment_str = 'LEFT'
            elif align == PP_ALIGN.CENTER:
                alignment_str = 'CENTER'
            elif align == PP_ALIGN.RIGHT:
                alignment_str = 'RIGHT'
            elif align == PP_ALIGN.JUSTIFY:
                alignment_str = 'JUSTIFY'
            else:
                alignment_str = 'UNKNOWN'
            return {'alignment': alignment_str}
        else:
            return {'alignment': 'UNKNOWN'}
    finally:
        os.unlink(tmp_path)

def get_pptx_textbox_fonts__04fa8230(env, config):
    """Extract font sizes from two specific textboxes in a PowerPoint slide.
    
    Args:
        env: DesktopEnv instance
        config: Configuration dict with parameters:
            - ppt_file_path: Path to PPTX file on VM
            - slide_index: Slide index (0-based)
            - textbox1_shape_idx: First textbox shape index
            - textbox2_shape_idx: Second textbox shape index
            
    Returns:
        dict: {"textbox1_font_size": float, "textbox2_font_size": float}
    """
    ppt_file_path = config['ppt_file_path']
    slide_index = int(config['slide_index'])
    textbox1_idx = int(config['textbox1_shape_idx'])
    textbox2_idx = int(config['textbox2_shape_idx'])
    ppt_file_localhost = get_vm_file(env, {'path': ppt_file_path, 'dest': os.path.basename(ppt_file_path)})
    prs = Presentation(ppt_file_localhost)
    if slide_index >= len(prs.slides):
        return {'error': f'Slide index {slide_index} out of range'}
    slide = prs.slides[slide_index]
    result = {'textbox1_font_size': None, 'textbox2_font_size': None}
    if textbox1_idx < len(slide.shapes):
        shape1 = slide.shapes[textbox1_idx]
        if hasattr(shape1, 'text_frame') and shape1.has_text_frame:
            for para in shape1.text_frame.paragraphs:
                for run in para.runs:
                    if run.font.size:
                        result['textbox1_font_size'] = run.font.size.pt
                        break
                if result['textbox1_font_size'] is not None:
                    break
    if textbox2_idx < len(slide.shapes):
        shape2 = slide.shapes[textbox2_idx]
        if hasattr(shape2, 'text_frame') and shape2.has_text_frame:
            for para in shape2.text_frame.paragraphs:
                for run in para.runs:
                    if run.font.size:
                        result['textbox2_font_size'] = run.font.size.pt
                        break
                if result['textbox2_font_size'] is not None:
                    break
    return result

