def get_pptx_image_hashes__2759cd98(env, config):
    """Get image blob hashes from slides to identify specific images.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and optional 'slide_index' keys

    Returns:
        list: List of SHA256 hashes of image blobs on specified slide(s)
    """
    ppt_file_path = config.get('path', '')
    slide_index = config.get('slide_index', 0)
    ppt_file_localhost_path = get_vm_file(env, {'path': ppt_file_path, 'dest': ppt_file_path.split('/')[-1]})
    prs = Presentation(ppt_file_localhost_path)
    image_hashes = []
    if slide_index < len(prs.slides):
        slide = prs.slides[slide_index]
        for shape in slide.shapes:
            if shape.shape_type == MSO_SHAPE_TYPE.PICTURE:
                image_blob = shape.image.blob
                image_hash = hashlib.sha256(image_blob).hexdigest()
                image_hashes.append(image_hash)
    return image_hashes

def get_pptx_image_dimensions__3292366912df43820dc8b9908bd62573(env, config):
    """Get dimensions of the largest image in a PowerPoint slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - path: Path to the .pptx file on VM
            - slide_index: Index of the slide (0-based)

    Returns:
        dict: {'width': int, 'height': int, 'image_name': str} in EMUs, or empty dict if no images found
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide_index = config.get('slide_index', 0)
        if slide_index >= len(prs.slides):
            return {}
        slide = prs.slides[slide_index]
        images = []
        for shape in slide.shapes:
            if shape.shape_type == 13:
                area = shape.width * shape.height
                images.append({'name': shape.name, 'width': shape.width, 'height': shape.height, 'area': area, 'left': shape.left, 'top': shape.top})
        if not images:
            return {}
        largest_image = max(images, key=lambda img: img['area'])
        return {'width': largest_image['width'], 'height': largest_image['height'], 'image_name': largest_image['name']}
    finally:
        os.unlink(tmp_path)

def get_pptx_text_bold__ba6e48c2(env, config):
    """Extract bold status of specific text from PPTX file."""
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return False
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp_file:
        tmp_file.write(file_bytes)
        tmp_path = tmp_file.name
    try:
        prs = Presentation(tmp_path)
        slide_idx = config.get('slide_idx', 0)
        text_to_find = config.get('text_to_find', '')
        if slide_idx >= len(prs.slides):
            return False
        slide = prs.slides[slide_idx]
        for shape in slide.shapes:
            if hasattr(shape, 'text') and text_to_find in shape.text:
                if hasattr(shape, 'text_frame'):
                    for para in shape.text_frame.paragraphs:
                        for run in para.runs:
                            if text_to_find in run.text:
                                return run.font.bold is True
        return False
    finally:
        os.unlink(tmp_path)

def get_ppt_background_text__40902a34(env, config: dict):
    """Extract background colors and text content from PowerPoint.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with ppt_file_path

    Returns:
        dict: {
            'background_colors': list of RGB tuples for each slide,
            'first_slide_texts': list of all text content from first slide
        }
    """
    ppt_file_path = config['ppt_file_path']
    ppt_localhost_path = get_vm_file(env, {'path': ppt_file_path, 'dest': os.path.basename(ppt_file_path)})
    prs = Presentation(ppt_localhost_path)
    background_colors = []
    for slide in prs.slides:
        fill = slide.background.fill
        if fill.type == 1:
            try:
                rgb = fill.fore_color.rgb
                background_colors.append((rgb[0], rgb[1], rgb[2]))
            except:
                background_colors.append(None)
        else:
            background_colors.append(None)
    first_slide_texts = []
    if len(prs.slides) > 0:
        first_slide = prs.slides[0]
        for shape in first_slide.shapes:
            if hasattr(shape, 'text'):
                text = shape.text.strip()
                if text:
                    first_slide_texts.append(text)
    return {'background_colors': background_colors, 'first_slide_texts': first_slide_texts}

def get_pptx_note_and_bg__4e791df4(env, config):
    """Extract slide note text and background color from PowerPoint file.
    
    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key for the .pptx file path
        
    Returns:
        dict: {"note": str, "bg_color": tuple or None}
    """
    from desktop_env.evaluators.getters.file import get_vm_file
    import os
    pptx_path = config.get('path', '/home/user/Desktop/181_2.pptx')
    local_path = get_vm_file(env, {'path': pptx_path, 'dest': os.path.basename(pptx_path)})
    prs = Presentation(local_path)
    if len(prs.slides) == 0:
        return {'note': '', 'bg_color': None}
    slide = prs.slides[0]
    notes_slide = slide.notes_slide
    note_text = notes_slide.notes_text_frame.text.strip() if notes_slide else ''

    def get_slide_background_color(slide):
        fill = slide.background.fill
        if fill.type == 1:
            return fill.fore_color.rgb
        elif fill.type == 5:
            master_fill = slide.slide_layout.slide_master.background.fill
            if master_fill.type == 1:
                return master_fill.fore_color.rgb
            else:
                return None
        else:
            return None
    bg_color = get_slide_background_color(slide)
    return {'note': note_text, 'bg_color': bg_color}

def get_pptx_note_bold__aa9993a107a23e8dd348cd94e399ee69(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Extract slide properties including title bold formatting and notes.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'slide_index' (0-based)

    Returns:
        Dict with slide properties: title_text, title_bold, notes_text
    """
    file_path = config['path']
    slide_index = config.get('slide_index', 0)
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        if slide_index >= len(prs.slides):
            return {}
        slide = prs.slides[slide_index]
        result = {'title_text': '', 'title_bold': False, 'notes_text': ''}
        if slide.shapes.title and slide.shapes.title.text_frame.paragraphs:
            result['title_text'] = slide.shapes.title.text
            all_runs_bold = True
            has_runs = False
            for para in slide.shapes.title.text_frame.paragraphs:
                for run in para.runs:
                    has_runs = True
                    if run.font.bold is not True:
                        all_runs_bold = False
                        break
                if not all_runs_bold:
                    break
            if has_runs and all_runs_bold:
                result['title_bold'] = True
        notes_slide = slide.notes_slide
        if notes_slide and notes_slide.notes_text_frame:
            result['notes_text'] = notes_slide.notes_text_frame.text.strip()
        return result
    finally:
        os.unlink(tmp_path)

def get_pptx_duplicate_verify__e7ffc681(env, config):
    """Verify slide duplication by checking count and titles.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'ppt_file_path', 'original_index', 'duplicate_index'

    Returns:
        dict: {'count': int, 'original_title': str, 'duplicate_title': str}
    """
    ppt_file_path = config.get('ppt_file_path', '/home/user/Desktop/Forests.pptx')
    original_index = config.get('original_index', 2)
    duplicate_index = config.get('duplicate_index', 3)
    local_path = get_vm_file(env, {'path': ppt_file_path, 'dest': os.path.basename(ppt_file_path)})
    prs = Presentation(local_path)
    slide_count = len(prs.slides)

    def get_slide_title(slide):
        """Helper to get slide title"""
        for shape in slide.shapes:
            if shape.has_text_frame and shape.is_placeholder:
                if hasattr(shape, 'placeholder_format'):
                    if shape.placeholder_format.type == 1:
                        return shape.text_frame.text.strip()
        for shape in slide.shapes:
            if shape.has_text_frame:
                text = shape.text_frame.text.strip()
                if text:
                    return text
        return ''
    original_title = ''
    duplicate_title = ''
    if original_index < slide_count:
        original_title = get_slide_title(prs.slides[original_index])
    if duplicate_index < slide_count:
        duplicate_title = get_slide_title(prs.slides[duplicate_index])
    return {'count': slide_count, 'original_title': original_title, 'duplicate_title': duplicate_title}
